var e={"nav.overview":`Áttekintés`,"nav.collector":`Linkgyűjtő`,"nav.downloads":`Letöltések`,"nav.instances":`Példányok`,"nav.accounts":`Fiókok`,"settings.accounts.setupTitle":`Oldalsáv`,"settings.accounts.showInSidebar":`Az oldalsávban is jelenjen meg`,"settings.accounts.showInSidebarHint":`Ez a lap és az oldalsáv Fiókok bejegyzése ugyanazt az oldalt mutatja. Kapcsold ki, ha a kettő együtt feleslegesnek tűnik.`,"settings.instances.showInSidebarHint":`Ez a lap és az oldalsáv Példányok bejegyzése ugyanazt az oldalt mutatja. Kapcsold ki, ha a kettő együtt feleslegesnek tűnik, vagy ha csak egy példányt futtatsz.`,"settings.instances.showInSidebar":`Az oldalsávban is jelenjen meg`,"settings.instances.setupTitle":`Oldalsáv`,"settings.nav.instances":`Példányok`,"nav.settings":`Beállítások`,"nav.workingTitle":`munkacím`,"theme.dark":`Sötét`,"theme.light":`Világos`,"theme.toggle":`Téma váltása`,"lang.label":`Nyelv`,"lang.open":`Nyelv váltása`,"lang.close":`Nyelvválasztó bezárása`,"status.collected":`Összegyűjtve`,"status.queued":`Sorban`,"status.running":`Letöltés`,"status.paused":`Szüneteltetve`,"status.extracting":`Kibontás`,"status.done":`Kész`,"status.error":`Hiba`,"task.pause":`Szünet`,"task.resume":`Folytatás`,"task.start":`Indítás`,"task.restart":`Újraindítás`,"task.remove":`Eltávolítás`,"task.left":`van hátra`,"task.file":`fájl`,"task.files":`fájl`,"task.ungrouped":`Csoport nélkül`,"task.reason.gone":`Már nincs meg`,"task.reason.auth":`Bejelentkezés kell`,"task.reason.limit":`Hoster korlát`,"task.reason.unavailable":`A hoster nem érhető el`,"task.reason.network":`Hálózat`,"task.reason.diskFull":`Megtelt a lemez`,"task.reason.unsupported":`Nincs backend`,"task.reason.captcha":`Captcha`,"task.reason.cancelled":`Megszakítva`,"task.reason.unknown":`Besorolatlan`,"overview.title":`Áttekintés`,"overview.totalSpeed":`Teljes letöltési sebesség`,"overview.active":`Aktív`,"overview.queued":`Sorban`,"overview.inCollector":`A gyűjtőben`,"overview.done":`Kész`,"overview.errors":`Hibák`,"overview.recent":`Legutóbbiak`,"overview.noDownloads":`Még nincs letöltés.`,"overview.instances":`Példányok`,"overview.idle":`tétlen`,"common.loading":`Betöltés…`,"common.loadFailed":`Nem sikerült betölteni. Elérhető a kiszolgáló?`,"common.retry":`Próbálja újra`,"hint.collector.title":`A linkek itt csak előkészülnek, még nincsenek letöltve`,"hint.collector.body":`Minden, amit hozzáad, először ebbe a gyűjtőbe kerül, ahol ellenőrizheti a neveket és méreteket, mielőtt bármi elindulna. Innen indíthatja el, vagy kapcsolja be az automatikus indítást a beállításokban, ha soha nem szeretné ezt a szünetet.`,"hint.downloads.title":`Ami ténylegesen fut`,"hint.downloads.body":`Ez az átviteli sor: az általad elindított linkek, akár futnak, akár a sorukra várnak, akár már elkészültek. Ami csak a gyűjtőben van előkészítve, az itt még nem jelenik meg.`,"empty.downloadsTitle":`Még semmi sem töltődik le`,"empty.downloadsHint":`Adjon hozzá hivatkozásokat a gyűjtőben, majd indítsa el őket.`,"collector.title":`Gyűjtő`,"collector.listTitle":`Linklista`,"collector.placeholder":`Illeszd be a linkeket, soronként egy URL-t, vagy húzd ide őket…  (Ctrl+Enter a hozzáadáshoz)`,"collector.package":`Csomag (nem kötelező)`,"collector.add":`Hivatkozások hozzáadása`,"collector.addTitle":`Linkgyűjtő`,"collector.empty":`A gyűjtő üres. Illesszen be fent hivatkozásokat az előkészítéshez.`,"collector.startSelected":`Kijelöltek indítása`,"collector.startAll":`Összes indítása`,"collector.toastStaged":`{n} hivatkozás előkészítve`,"collector.toastSkipped":`{n} hivatkozás előkészítve, {skipped} már ismert volt`,"collector.toastNone":`Nem található érvényes hivatkozás`,"collector.toastStarted":`{n} letöltés elindítva`,"collector.toastStartDisabled":`{n} link ki van kapcsolva, nem indultak el.`,"collector.toastStartedSomeDisabled":`{n} elindult, {disabled} ki van kapcsolva.`,"collector.toastStartBlocked":`Egy ütemezés tartja szünetben a sort.`,"collector.selectAll":`Összes kijelölése`,"collector.movePrompt":`Melyik csomagba kerüljenek a kijelölt hivatkozások?`,"downloads.title":`Letöltések`,"downloads.listTitle":`Letöltési lista`,"downloads.thisInstance":`Ez a példány`,"downloads.pauseAll":`Összes szüneteltetése`,"downloads.resumeAll":`Összes folytatása`,"downloads.retryFailed":`Sikertelenek újrapróbálása`,"downloads.retryCause":`A(z) {n} újrapróbálása ezzel az okkal: {reason}`,"downloads.clearFinished":`Befejezettek törlése`,"downloads.noMatch":`Semmi sem felel meg a szűrőnek.`,"downloads.finished":`{name} elkészült`,"downloads.failed":`{name} nem sikerült`,"instances.title":`Példányok`,"instances.moduleOff":`A társpéldányok ki vannak kapcsolva, ezért ez a példány nem listázza és nem is keresi meg a többit.`,"instances.thisInstance":`Ez a példány`,"instances.foundTitle":`Megtalálva a hálózatán`,"instances.foundHint":`KnightLoader-példányok, amelyek jelentkeznek ezen a hálózaton. Semmi sem kapcsolódik, amíg hozzá nem adsz egyet, és a hozzáadás is csak a címét tárolja. Az, hogy ugyanazon a hálózaton van, nem számít engedélynek. A jelszóval védett példánynak ráadásul párosítási kód is kell, mielőtt bármit elfogadna.`,"instances.foundAdd":`Hozzáadás`,"instances.foundKnown":`már hozzáadva`,"instances.connectButton":`Példány csatlakoztatása`,"instances.connectWhere":`Egy másik KnightLoadert a Távoli elérés oldalon adhatsz hozzá vagy párosíthatsz.`,"instances.offlineWarning":`Hozzáadva, de a példány nem válaszolt (offline?).`,"instances.open":`Megnyitás`,"instances.online":`Elérhető`,"instances.refused":`Elutasítva`,"instances.refusedByPassword":`Elérhető, de elutasította ezt a példányt, mert jelszó van rajta beállítva. Add meg mindkettőnek ugyanazt a kapcsolódási kifejezést a Távoli elérés oldalon, és megbíznak egymásban.`,"instances.offline":`Nem elérhető`,"instances.viaRelay":`Relén keresztül csatlakoztatva`,"instances.metricActive":`Aktív`,"instances.metricTasks":`Feladatok`,"instances.metricSpeed":`Sebesség`,"instances.removeTitle":`{name} eltávolítása`,"accounts.title":`Fiókok`,"accounts.connected":`Csatlakoztatva`,"accounts.saved":`Mentve.`,"accounts.keyLabel":`{service} API-kulcs`,"accounts.keyHint":`Azonnal érvényes; titkosítva tárolva ezen a példányon.`,"accounts.placeholder":`Illessze be a kulcsát…`,"settings.title":`Beállítások`,"settings.maxConcurrent":`Egyidejű letöltések`,"settings.maxConcurrentHint":`Hány letöltés fut egyszerre. A többi kivárja a sorát.`,"settings.maxPerHost":`Egyidejű letöltések tárhelyenként`,"settings.maxPerHostHint":`Egyetlen tárhely felső korlátja, a fenti összesen felett. A legtöbb tárhely egyszerre csak nagyon keveset enged.`,"settings.speedHint":`Az összes letöltésre együtt vonatkozó korlát, futás közben érvényesül.`,"settings.autoStart":`A hozzáadott hivatkozások azonnali indítása`,"settings.autoStartHint":`A hozzáadott linkek letöltése elindul anélkül, hogy a gyűjtőben meg kellene erősítened őket. Hogy előtte mennyit várnak, azt lent, a Gyűjtő alatti visszaszámlálás határozza meg.`,"settings.save":`Mentés`,"settings.saved":`Mentve.`,"settings.downloadDir":`Letöltési mappa`,"settings.downloadDirHint":`Abszolút útvonal. Hagyja üresen a beépített mappához.`,"settings.subfolderByPackage":`Minden csomag saját almappába kerüljön`,"settings.maxRetries":`Automatikus újrapróbálkozások`,"settings.resumeOnStart":`Újraindítás után`,"settings.resumeOnStartHint":`Az újraindított átvitel elölről kezdődik, a lemezen már meglévő részleges fájl pedig az ütközési szabályba fut. Ezért az óvatos beállítás az alapértelmezett.`,"settings.resume.never":`Semmit`,"settings.resume.running":`Ami futott`,"settings.resume.all":`Minden befejezetlent`,"settings.keepFinishedDays":`Kész elemek megtartása (nap)`,"settings.keepFinishedDaysHint":`A 0 örökre a listán tartja őket. A lemezen lévő fájlhoz soha nem nyúl, és az előzmény megőrzi a bejegyzést.`,"settings.historyMax":`Előzménybejegyzések`,"settings.historyMaxHint":`A 0 minden bejegyzést megtart.`,"settings.maxRetriesHint":`A sikertelen letöltés növekvő várakozással újraindul.`,"settings.archivePasswords":`Archívumjelszavak`,"settings.archivePasswordsHint":`Soronként egy. Titkosított archívumnál sorban próbálja ki őket.`,"settings.lockOn":`Van beállított jelszó.`,"settings.lockOff":`Nincs jelszó beállítva.`,"settings.lockHint":`Megvédi ezt a példányt mindenkitől, aki el tudja érni: ugyanazon a hálózaton, egy domainen vagy egy relén keresztül. Ha be van állítva, meg kell adni, mielőtt ez a példány egyáltalán megnyílna, mindenki számára, beleértve téged is a következő látogatáskor. Jelszó nélkül bárki, aki megtalálja a címet, láthat minden letöltést, és hozzáadhatja, szüneteltetheti vagy törölheti a sajátjait.`,"settings.passwordCurrent":`Jelenlegi jelszó`,"settings.passwordNew":`Új jelszó`,"settings.passwordHint":`Legalább 8 karakter. Hagyja üresen a zár eltávolításához.`,"settings.setPassword":`Jelszó beállítása`,"settings.passwordSaved":`A jelszó frissítve.`,"auth.title":`Ez a példány zárolva van`,"auth.password":`Jelszó`,"auth.signIn":`Bejelentkezés`,"auth.signOut":`Kijelentkezés`,"auth.wrong":`Hibás jelszó.`,"accounts.ok":`Működik`,"accounts.failed":`Nem működik`,"accounts.unchecked":`Nincs ellenőrizve`,"accounts.hosts":`támogatott tárhely`,"task.recheck":`Újraellenőrzés`,"task.online":`Elérhető`,"task.offline":`Nem elérhető`,"task.retryPending":`Automatikusan újrapróbálkozik`,"task.forced":`„Indítás most” beállítva`,"task.held":`Visszatartva`,"task.folder":`Mappa`,"task.password":`Archívum jelszava`,"task.priorityUp":`Prioritás növelése`,"task.priorityDown":`Prioritás csökkentése`,"task.moveTop":`Legfelülre`,"task.moveBottom":`Legalulra`,"task.removeWithFiles":`Eltávolítás a fájlokkal együtt`,"task.applied":`Alkalmazva.`,"select.all":`Összes kijelölése`,"select.none":`Kijelölés törlése`,"select.count":`kijelölve`,"settings.removePassword":`Jelszó eltávolítása`,"common.cancel":`Mégse`,"common.close":`Bezárás`,"pkg.moveTitle":`Áthelyezés csomagba`,"pkg.name":`Csomag neve`,"pkg.merge":`Egy csomagba vonás`,"pkg.splitByHost":`Szétosztás tárhely szerint`,"pkg.menu":`Csomag`,"settings.pathVars":`Változók: <jd:packagename>, <jd:hoster>, <jd:filename>, <jd:date>`,"settings.pathProblem.notAbsolute":`Adj meg teljes útvonalat, például /downloads vagy D:\\Downloads.`,"settings.pathProblem.cannotCreate":`Nem sikerült létrehozni: {dir}.`,"settings.pathProblem.cannotWrite":`Nem sikerült írni ide: {dir}.`,"settings.crawl":`Oldalak követése és a hivatkozott fájlok összegyűjtése`,"settings.crawl.depth":`Bejárási mélység`,"settings.crawl.depthHint":`Meddig menjen. Az 1 csak a beillesztett oldal, a 2 megnyitja a hivatkozott oldalakat is, a 3 azok hivatkozásait. Egy oldal soha nem nyílik meg kétszer, így az egymásra mutató hivatkozások lezárják a futást ahelyett, hogy körbejárnának.`,"settings.crawl.maxPages":`Oldalkorlát`,"settings.crawl.maxPagesHint":`Egy futás legfeljebb hány oldalt nyithat meg. A lekért oldalakat számolja, nem a talált hivatkozásokat. Az 1-es mélységnél csak egy oldal van, ott nincs hatása.`,"settings.crawl.sameHost":`Maradjon ugyanazon a kiszolgálón`,"settings.crawl.sameHostHint":`Csak a beillesztett gazdagép oldalait kövesse. A gazdagép pontosan hasonlítódik össze, így az aldomain másik helynek számít. A fájlokat ez soha nem korlátozza, mert a letöltések gyakran külön kiszolgálón vannak.`,"settings.crawl.include":`Csak ezek a hivatkozások`,"settings.crawl.includeHint":`Soronként egy reguláris kifejezés, a teljes címhez hasonlítva. Egy hivatkozásnak illeszkednie kell valamelyikre, hogy bekerüljön. Az oldalakat ez nem szűri, tehát soha nem akadályozza meg a mélyebbre jutást.`,"settings.crawl.exclude":`Soha ezek a hivatkozások`,"settings.crawl.excludeHint":`Soronként egy reguláris kifejezés, a teljes címhez hasonlítva. Ami illeszkedik, azt kihagyja, az oldalakat is, így a kizárt címet meg sem nyitja.`,"task.checksumOk":`Az ellenőrző összeg egyezik`,"task.checksumFail":`Az ellenőrző összeg nem egyezik`,"settings.verifyChecksums":`A kész letöltés ellenőrzése a vele érkezett ellenőrző összeggel`,"settings.shape":`Sarkok`,"settings.shapeHint":`Egyszerre vonatkozik a kártyákra, gombokra, fülekre, mezőkre és jelvényekre.`,"settings.shape.round":`Kerek`,"settings.shape.slightlyRounded":`Enyhe`,"settings.shape.square":`Szögletes`,"settings.shape.leaf":`Levél`,"settings.accent":`Kiemelőszín`,"settings.accentHint":`Az egyetlen szín a tevékenységhez. A rajta lévő szöveget a kontraszt dönti el.`,"settings.accentRainbowOwns":`A szivárvány mód most pozíció szerint osztja a színeket. Ez a szín továbbra is mindenre érvényes, aminek nincs pozíciója.`,"settings.colours":`Színek`,"settings.accentReset":`Alapérték`,"queue.stop":`Sor leállítása`,"queue.start":`Sor indítása`,"queue.stopMark":`Ez után leállás`,"queue.stopMarkOn":`Ez után leáll`,"queue.order":`Sorrend`,"queue.play":`Lejátszás`,"queue.pause":`Szünet`,"queue.hardStop":`Leállítás`,"queue.hardStopConfirmTitle":`Leállítsuk az összes átvitelt most?`,"queue.hardStopConfirmBody":`{n} folyamatban lévő átvitel azonnal leállna a befejezés helyett. {detail}`,"queue.hardStopConfirmLoss":`A már letöltött {bytes} nem folytatható, és újra le kellene tölteni.`,"queue.hardStopConfirmUnknown":`További {n} esetében nem ellenőrizték a folytatás támogatását.`,"queue.hardStopConfirmSafe":`Minden futó folyamat onnan folytatható, ahol megállt.`,"queue.hardStopConfirmCancel":`Mégse`,"queue.hardStopConfirmProceed":`Leállítás most`,"settings.rainbow":`Szivárvány mód`,"settings.rainbowHint":`Egy kiemelőszín helyett nyolcból álló paletta pozíció szerint, így a hosszú lista külön sorokként olvasható.`,"settings.rainbowOn":`Paletta használata`,"settings.rainbowReactive":`Reaktív mód`,"settings.rainbowReactiveHint":`Csendes, amíg hozzá nem érsz: szín rámutatáskor és azon, ami fut`,"settings.rainbowRotate":`Színforgatás`,"settings.rainbowRotateHint":`A paletta kezdőszínének keverése`,"settings.rainbowDisco":`Diszkó mód`,"settings.rainbowDiscoGlideHint":`Amíg a szivárvány mód be van kapcsolva, minden színes elem együtt siklik végig a palettán, 2,4 másodpercenként egy színnel. Ha a Mozgás „Ki” értékre van állítva, vagy a rendszeredben be van kapcsolva a csökkentett mozgás, akkor ehelyett színről színre ugrik.`,"settings.rainbowPalette":`Palettaszín`,"settings.rainbowPaletteLabel":`Színpaletta`,"settings.rainbowPaletteHint":`A pozíció szerint kiosztott nyolc szín. Egyenként szerkeszthető.`,"settings.look.saveFailed":`Nem sikerült menteni: {error}`,"settings.theme":`Téma`,"settings.motion.wild":`Vad`,"settings.motion.storm":`Vihar`,"settings.motion.subtle":`Visszafogott`,"settings.motion.off":`Ki`,"settings.motion.hint":`A Ki minden nem lényeges animációt kikapcsol; a Visszafogott rövidre fogja a megjelenéseket; a Vadban van a legtöbb mozgás.`,"settings.motion.title":`Mozgás`,"settings.navLabels.title":`Navigációs feliratok`,"settings.navLabels.titleHint":`Mennyi látszik az egyes bejegyzésekből: az oldalsávban, a beállítások oszlopában, a listák eszköztárain és a gyűjtő saját gombjain. Rámutatáskor a csempe megtartja a méretét, a név pedig a mutató alatt jelenik meg.`,"settings.navLabels.both":`Ikon és szöveg`,"settings.navLabels.glyph":`Csak ikon`,"settings.navLabels.text":`Csak szöveg`,"settings.navLabels.hover":`Rámutatáskor`,"settings.bottomBarLabels.title":`Alsó sáv feliratai`,"settings.bottomBarLabels.titleHint":`Mennyit mutat az egyes bejegyzésekből az ablak alján lévő sáv. A sáv csak telefonos elrendezésben váltja fel az oldalsávot, vagyis 768 pixelnél keskenyebb ablakban, így szélesebb képernyőn ez a beállítás semmit sem változtat. A „Mint az oldalsáv” a „Navigációs feliratok” beállítást követi.`,"settings.bottomBarLabels.follow":`Mint az oldalsáv`,"common.show":`Mutasd`,"common.hide":`Elrejt`,"common.showPassword":`Jelszó megjelenítése`,"common.hidePassword":`Jelszó elrejtése`,"common.dismiss":`Bezár`,"columns.name":`Név`,"columns.size":`Méret`,"columns.progress":`Haladás`,"columns.speed":`Sebesség`,"columns.eta":`Hátralévő`,"columns.status":`Állapot`,"columns.availability":`Elérhetőség`,"columns.host":`Tárhely`,"columns.added":`Hozzáadva`,"columns.finished":`Kész`,"columns.comment":`Megjegyzés`,"columns.resolver":`Backend`,"columns.source":`Forrás`,"columns.enabled":`Bekapcsolva`,"columns.menuTitle":`Oszlopok`,"columns.reset":`Oszlopok visszaállítása`,"columns.headerHint":`Kattints egy fejlécre a szerinte való rendezéshez, húzd az oszlop átrendezéséhez, húzd a szélét az átméretezéshez, dupla kattintás a szélén visszaállítja a szélességet. Jobb kattintás a fejlécen az oszloplistához.`,"columns.alwaysShown":`Ez az oszlop mindig látszik.`,"columns.lastVisible":`Egy listának legalább egy oszlop kell.`,"columns.resizeHint":`Húzd a szélesség módosításához, dupla kattintás visszaállít`,"list.sortedView":`Rendezett sorrend`,"list.sortedViewTip":`A rendezés azt a sorrendet változtatja meg, amit látsz, nem azt, amelyben a letöltések futnak. A letöltések továbbra is a sor sorrendjében indulnak. Ha harmadszor is ugyanarra az oszlopfejlécre kattintasz, újra a sor sorrendje látszik.`,"list.dragNeedsQueueOrder":`Húzni csak a sor sorrendjében lehet. A sorok kézi mozgatásához kattints a rendezett oszlop fejlécére, amíg a rendezés ki nem kapcsol.`,"list.dragNotInQueue":`Ez nem mozgatható kézzel: csak a sorban még várakozó linkek, mappa pedig csak akkor, ha a linkjei ugyanazon a prioritáson állnak.`,"list.controls":`Listavezérlők`,"list.actions":`Listaműveletek`,"list.failed":`Ez nem sikerült: {error}`,"task.waiting.slot":`Minden hely foglalt`,"task.waiting.host":`Ennek a tárhelynek a korlátja`,"task.waiting.forced":`Az azonnali indítás helyei betelve`,"task.waiting.disabled":`Kikapcsolva`,"task.waiting.hold":`Kézzel félretéve`,"task.waiting.captcha":`Captchára vár`,"task.waiting.account":`A fiók nem érhető el`,"task.waiting.halted":`A sor le van állítva`,"list.dropChangedPriority":`Áthelyezve: {n} letöltés átvette annak a sornak a prioritását, amelyre ejtetted.`,"list.optionsFailed":`A takarítási bejegyzések nem töltődtek be a kiszolgálóról.`,"task.enable":`Bekapcsolás`,"task.disable":`Kikapcsolás`,"task.switchFailed":`A kapcsolót nem sikerült átállítani.`,"task.uncheckable":`A tárhely nem válaszolt`,"task.expand":`Kibont`,"task.collapse":`Összecsuk`,"search.placeholder":`Keresés ebben a listában…`,"search.in":`Keresés ebben`,"search.any":`Mindenhol`,"search.name":`Név`,"search.host":`Tárhely`,"search.package":`Csomag`,"search.comment":`Megjegyzés`,"search.url":`Link`,"search.clear":`Keresés törlése`,"search.hint":`Válassz egy mezőt a kereséshez, vagy a „Mindenhol” lehetőséget, hogy egyszerre mindben keressen.`,"search.syntax":`Több szónak mindnek illeszkednie kell, az elé tett mínusz kizár egyet. A host:, package: és name: egyetlen mezőben keres, a >500mb és az older:7d a méretre és a korra kérdez rá. Minden más sima szövegként keresendő.`,"search.shown":`{total} közül {n} látszik`,"filter.label":`Gyorsszűrők`,"filter.clear":`Mutasd mindet`,"filter.running":`Letöltés`,"filter.queued":`Sorban`,"filter.paused":`Szüneteltetve`,"filter.finished":`Kész`,"filter.failed":`Hibás`,"filter.online":`Elérhető`,"filter.offline":`Nem elérhető`,"filter.uncheckable":`Nem ellenőrizhető`,"filter.unchecked":`Nincs ellenőrizve`,"filter.disabled":`Kikapcsolva`,"filter.held":`Visszatartva`,"filter.stalled":`Elakadt`,"cleanup.menu":`Takarítás…`,"cleanup.menuLabel":`Takarítási bejegyzések`,"cleanup.finished":`Kész letöltések eltávolítása`,"cleanup.offline":`Nem elérhetők eltávolítása`,"cleanup.disabled":`Kikapcsolt linkek eltávolítása`,"cleanup.duplicates":`Duplikátumok eltávolítása`,"cleanup.incompleteArchives":`Hiányos archívumok eltávolítása`,"cleanup.what.finished":`Minden befejezett letöltés ezen a példányon.`,"cleanup.what.offline":`Minden link ezen a példányon, amelyről a tárhely azt válaszolta, hogy már nincs meg. Azokhoz a linkekhez, amelyeket senki sem tudott ellenőrizni, nem nyúl.`,"cleanup.what.disabled":`Minden kikapcsolt link ezen a példányon.`,"cleanup.what.duplicates":`Egy már listán lévő letöltés második másolatai. A legelőrébb tartó másolat marad meg.`,"cleanup.what.incompleteArchives":`Többkötetes készletek halott résszel. A többit soha nem lehet kicsomagolni.`,"cleanup.finishedKeepsFiles":`A kész letöltések csak lekerülnek a listáról. Ez a bejegyzés soha nem töröl semmit a lemezről.`,"cleanup.localOnly":`A takarítás mindig ezen a példányon fut, nem azon, amit épp nézel. Válts vissza a „Ez a példány” lehetőségre a használatához.`,"cleanup.nothing":`Most semmi nem illik ide: „{what}”, ezért semmi nem lett eltávolítva.`,"cleanup.failed":`Nem derült ki, mit távolítana el ez: {error}`,"remove.title":`A letöltött fájlok is törlődjenek?`,"remove.count":`{n} letöltés kerül le a listáról.`,"remove.fromList":`Levétel a listáról`,"remove.withFiles":`Eltávolítás a fájlokkal együtt`,"remove.filesKept":`A lemezen lévő fájlok ott maradnak, ahol vannak.`,"remove.filesGone":`Ez {files} fájlt is töröl, {bytes} a lemezen. Nem vonható vissza.`,"remove.noFiles":`A lemezre még semmi nem íródott.`,"remove.done":`{n} letöltés eltávolítva.`,"remove.keys":`A Del leveszi a kijelölt sorokat a listáról. A Shift+Del a fájljaikat is törli.`,"remove.undo":`Visszavonás`,"remove.undone":`{n} letöltés vissza a listán.`,"remove.undoTooLate":`Túl késő, azok a sorok végleg elvesztek.`,"menu.label":`Műveletek a kijelölt letöltésekre`,"menu.packageLabel":`Műveletek ezen a csomagon`,"menu.more":`Több`,"menu.enable":`Bekapcsolás`,"menu.disable":`Kikapcsolás`,"menu.hold":`Visszatartás`,"menu.release":`Elengedés`,"menu.unforce":`„Indítás most” visszavonása`,"menu.setFolder":`Letöltési mappa beállítása…`,"menu.collapseAll":`Összes csomag összecsukása`,"menu.expandAll":`Összes csomag kibontása`,"collector.checkAll":`Mind ellenőrzése`,"search.toggle":`Keresés`,"skipped.summary":`{n} link nem lett hozzáadva`,"skipped.info":`Links and files that did not become downloads, each with its reason. A link already in the list, or already among the rejected links, is only noted here: the copy there is the one that stays. Nothing was downloaded for the others: a container or Click'n'Load that gave no links, entries left out of a playlist, an .nzb that TorBox or Premiumize.me gave up on, or a file from the watch folder that could not be taken. Clearing forgets these notes and adds nothing back.`,"skipped.clear":`Törlés`,"skipped.clearFailed":`A listát nem sikerült törölni. Elérhető a kiszolgáló?`,"container.choose":`Fájl kiválasztása`,"container.uploading":`Feltöltés…`,"container.tooBig":`nagyobb mint {max}, márpedig ekkora konténer nincs`,"container.staged":`{n} link előkészítve innen: {file}.`,"container.stagedIn":`{n} link előkészítve innen: {file}, ide: „{pkg}”.`,"container.alsoKnown":`További {n} már a listán volt.`,"container.allKnown":`A(z) {file} mind a(z) {n} linkje már a listán volt.`,"container.handed":`A(z) {file} titkosított. Átadtuk a JDownloader backendnek; a linkjei itt jelennek meg, amint az lehúzta ({n} másodpercen belül).`,"container.failed":`A(z) {file} nem lett elfogadva: {reason}`,"settings.nav.modules":`Modulok`,"settings.nav.collector":`Linkgyűjtő`,"settings.nav.downloads":`Letöltések`,"settings.nav.archives":`Archívumok`,"settings.nav.rules":`Szabályok és kategóriák`,"settings.nav.network":`Hálózat`,"settings.nav.accounts":`Fiókok`,"settings.nav.captcha":`Captcha`,"settings.nav.automation":`Automatizálás`,"settings.nav.look":`Általános`,"settings.nav.appearance":`Megjelenés`,"settings.nav.access":`Távoli elérés`,"settings.nav.advanced":`Haladó`,"settings.railLabel":`Beállítási szakaszok`,"settings.empty":`Itt még nincs mit beállítani.`,"settings.emptyHint":`Az oldal be van jegyezve, hogy a címe továbbra is működjön, és hogy a vezérlők ide kerüljenek, amint az alrendszer megvan.`,"settings.downloads.autoConfirmOff":`„A hozzáadott hivatkozások azonnali indítása” ki van kapcsolva fent, a Linkfogadás alatt, ezért itt nem fut visszaszámlálás.`,"settings.downloads.locationTitle":`Hely`,"settings.downloads.limitsTitle":`Korlátok és viselkedés`,"settings.downloads.watchTitle":`Mappafigyelés`,"settings.downloads.idleTitle":`Üresjárat`,"settings.downloads.idleAction":`Művelet a sor végén`,"settings.downloads.idleActionNone":`Ne tegyen semmit`,"settings.downloads.idleActionPause":`Sor szüneteltetése`,"settings.downloads.idleActionHint":`Mi történik, amikor már semmi sem fut, nem áll sorban és nem vár indulásra. Az általad kikapcsolt link soha nem számít hátralévő munkának, így ezt nem tudja örökre feltartani. A kézzel szüneteltetett vagy visszatartott link viszont beleszámít: mindkettő azt jelenti, hogy „várj egy kicsit”, nem azt, hogy „soha”.`,"settings.downloads.idleCountdown":`Visszaszámlálás (másodperc)`,"settings.downloads.idleCountdownHint":`Mennyi időd van a megszakításra, mielőtt a művelet lefut, ha a sor tényleg kiürül.`,"settings.modules.fixedAtBuild":`A modulok köre a bináris fordításakor dől el. Futó példányba semmit sem lehet telepíteni, tehát ez a lista a teljes készlet.`,"settings.modules.sectionShipped":`Ebben a buildben`,"settings.modules.sectionDesktop":`Csak asztali buildek`,"settings.modules.sectionNotBuilt":`Nincs ebben a buildben`,"settings.modules.off":`Ki`,"settings.modules.notBuilt":`Nincs lefordítva`,"settings.modules.desktopOnly":`Csak asztali`,"settings.modules.configuredOn":`A(z) {page} oldalon állítható be`,"settings.modules.alsoOn":`A(z) {page} oldalon is`,"settings.modules.detail.cnlListening":`Figyel itt: {address}`,"settings.modules.detail.cnlOff":`Kikapcsolva`,"settings.modules.detail.cnlOffByEnv":`Kikapcsolva a KL_CNL=0 beállítással`,"settings.modules.detail.cnlUnavailable":`Nem sikerült megnyitni: {address}. Általában egy futó JDownloader már foglalja a portot.`,"settings.modules.detail.extractionOff":`Ki. A már folyamatban lévő kibontás befejeződik.`,"settings.modules.detail.extractionKeep":`Az archívumok a kibontás után megmaradnak.`,"settings.modules.detail.extractionDelete":`Az archívumok sikeres kibontás után törlődnek.`,"settings.modules.detail.extractionTrash":`Az archívumok sikeres kibontás után ide kerülnek: {folder}.`,"settings.modules.detail.watchFolder":`Figyelt mappa: {folder}`,"settings.modules.detail.watchFolderMissing":`A mappa még nem létezik. A bele tett fájlokat felvesszük, amint létrejön: {folder}`,"settings.modules.detail.watchNone":`Nincs mappa beállítva`,"settings.modules.detail.subscriptions":`{n} feliratkozás`,"settings.modules.detail.subscriptionsOne":`1 feliratkozás`,"settings.modules.detail.targetsSending":`{n} küldő cél`,"settings.modules.detail.targetsSendingOne":`1 küldő cél`,"settings.modules.detail.windows":`{n} időablak`,"settings.modules.detail.windowsOne":`1 időablak`,"settings.modules.detail.reconnectMethod":`Módszer: {method}`,"settings.modules.detail.packagizerOff":`Ki. Az új linkeket nem rendezik a szabályok.`,"settings.modules.detail.linkfilterOff":`Ki. Minden link bekerül.`,"settings.modules.detail.rules":`{n} szabály`,"settings.modules.detail.rulesOne":`1 szabály`,"settings.modules.detail.connectionsOff":`Ki. Az új letöltések ennek a gépnek a saját címén mennek ki.`,"settings.modules.detail.connectionsInUse":`{n} kapcsolat használatban`,"settings.modules.detail.connectionsInUseOne":`1 kapcsolat használatban`,"settings.modules.detail.federationOff":`Ki. A társpéldányok mentve maradnak, de ez a példány nem listázza őket, és nem is veszi fel velük a kapcsolatot.`,"settings.modules.detail.peers":`{n} társpéldány`,"settings.modules.detail.peersOne":`1 társpéldány`,"settings.modules.detail.jdMissing":`A titkosított konténereket elutasítjuk, a tárhelylinkek pedig egy debrid szolgáltatáshoz kerülnek, vagy meghiúsulnak.`,"settings.modules.detail.jdOff":`Ki. A JDownloaderben már lévő letöltések befejeződnek, az új tárhelylinkek pedig várnak, amíg újra be nem kapcsolod.`,"settings.modules.detail.jdReachable":`Elérhető. A titkosított konténerek megnyithatók.`,"settings.modules.detail.ytdlpNotFound":`A yt-dlp nem található (a Feloldók oldalon letöltött másolat, KL_YTDLP vagy „yt-dlp” a PATH-ban). A médiaoldalak ehelyett az oldal saját hibájával hiúsulnak meg.`,"settings.modules.detail.ytdlpOff":`Ki. A futó letöltés befejeződik, a videolinkek pedig várnak, amíg újra be nem kapcsolod.`,"settings.modules.detail.ytdlpQuality":`Minőség: {quality}`,"settings.modules.detail.ytdlpVersion":`yt-dlp {version} ({source}), minőség: {quality}`,"settings.modules.detail.torrentsOff":`Ki. A futó torrentek folytatódnak és tovább seedelnek. Az újak várnak, amíg újra be nem kapcsolod.`,"settings.modules.detail.torrentsUnregistered":`The built-in torrent client is not on the routing table, so magnet links and .torrent uploads are refused as unsupported.`,"settings.modules.detail.torrentsRouted":`Magnet links and uploaded .torrent files go to the built-in torrent client.`,"settings.modules.detail.captchaOff":`Ki. Nem nyílik meg kérdés, és a JDownloader feladja a linket, amint lejár a captchája.`,"settings.modules.detail.challenges":`{n} captcha vár éppen`,"settings.modules.detail.challengesOne":`1 captcha vár éppen`,"settings.modules.detail.downloadclientOff":`Ki. A Sonarr és a Radarr 404-et kap tőle, mint egy nem létező címtől.`,"settings.modules.detail.downloadclientNoToken":`Még nincs API-token, ezért minden hívást elutasítunk. Hozz létre egyet a Távoli elérés oldalon.`,"settings.modules.detail.metricsOff":`Ki. A(z) {path} 404-gyel válaszol, mint egy nem létező cím.`,"settings.modules.detail.metricsNoToken":`Ennek a példánynak van jelszava, de még nincs API-tokenje, így egy felügyeleti rendszernek nincs mivel bejelentkeznie. Hozz létre egyet a Távoli elérés oldalon.`,"settings.modules.detail.metricsReady":`Elérhető itt: {path}. Jelszavas példányon a felügyeleti rendszer a példány egyik API-tokenjét küldi Bearer fejlécként.`,"settings.modules.detail.scriptingOff":`Ki. Egyetlen esemény sem indít szkriptet, a már futó szkript pedig befejeződik.`,"settings.modules.detail.scriptsEnabled":`{n} szkript bekapcsolva`,"settings.modules.detail.scriptsEnabledOne":`1 szkript bekapcsolva`,"settings.modules.reason.cnlSwitch":`A 127.0.0.1:9666 címen figyel, hacsak a KL_CNL nem nevez meg másik portot. Ha itt kikapcsolod, a KL_CNL változatlan marad, így újraindítás után a port úgy nyílik meg, ahogy a környezet mondja.`,"settings.modules.reason.cnlNoListener":`Ez a folyamat nem nyit Click'n'Load portot.`,"settings.modules.reason.jdNotConfigured":`Nincs beállítva JDownloader háttér. Állítsd a KL_JD-t egy olyan JDownloaderre, amelyet ez a példány elér, majd indítsd újra.`,"settings.modules.reason.ytdlpMissing":`Nem található yt-dlp. Tölts le egyet a Feloldók oldalon, vagy állítsd be a KL_YTDLP-t.`,"settings.modules.reason.captchaNoJD":`Captchák csak a JDownloader háttértől jönnek, és egy sincs beállítva (KL_JD).`,"settings.modules.reason.captchaJDOff":`Captchák csak a JDownloadertől jönnek, és az ki van kapcsolva. Előbb kapcsold vissza.`,"settings.modules.reason.tray":`A tálcaikonhoz asztali munkamenet kell, a konténeres buildben pedig nincs ilyen. Ott a böngészőlap címe és ikonja mutatja ugyanezt.`,"settings.modules.reason.windowpolicy":`Hogy mit tesz az ablak bezárása vagy kis méretre állítása, az egy gépen lévő egy telepítéshez tartozik, ezért ez a példány nem szolgálja ki.`,"settings.modules.reason.updaterDesktop":`Megnézi a GitHubon, van-e újabb kiadás, amikor az Általános oldalon rákérdezel, valamint induláskor, ha az „Automatikus ellenőrzés induláskor” be van kapcsolva. Amit talál, csak akkor telepíti magától, ha az „Automatikus telepítés megtaláláskor” be van kapcsolva. Egyébként a telepítés egy lépés, amelyet ott te végzel el.`,"settings.modules.reason.updaterContainer":`Egy konténer nem tudja belülről lecserélni önmagát. Az Általános oldal frissítéskeresése csak annyit mond, hogy van újabb kiadás, és belinkeli. A frissítéshez húzd le az új image-et úgy, ahogy ezt telepítetted (docker pull, Unraid Community Applications, Watchtower és így tovább).`,"settings.modules.switchFailed":`A kapcsolót elutasította: {reason}`,"settings.modules.configureFirst":`Még nincs mit bekapcsolni. Előbb állítsd be a(z) {page} oldalon; utána az itteni kapcsoló leállítja és újraindítja anélkül, hogy a beállított elveszne.`,"settings.modules.setUpBelow":`Még nincs mit bekapcsolni. Állítsd be lent, és a kapcsoló magától bekapcsol.`,"settings.modules.parkedBelow":`Ha újra bekapcsolod, visszatér, ami itt be volt állítva.`,"settings.module.extraction":`Archívumok kicsomagolása`,"settings.module.watch":`Figyelt mappa`,"settings.module.crawler":`Oldalbejáró`,"settings.module.checksums":`Ellenőrzőösszeg-vizsgálat`,"settings.module.scheduler":`Időzítések`,"settings.module.reconnect":`Újracsatlakozás`,"settings.module.packagizer":`Packagizer`,"settings.module.linkfilter":`Hivatkozásszűrő`,"settings.module.connections":`Kimenő kapcsolatok`,"settings.module.cnl":`Click'n'Load`,"settings.module.federation":`Társpéldányok`,"settings.module.jd":`JDownloader háttér`,"settings.module.captcha":`Captcha`,"settings.module.scripting":`Eseményszkriptek`,"settings.module.tray":`Tálcaikon`,"settings.module.windowpolicy":`Ablakviselkedés`,"settings.module.updater":`Alkalmazáson belüli frissítések`,"settings.advanced.search":`Szűrés név vagy érték szerint`,"settings.advanced.allSettings":`Minden beállítás`,"settings.advanced.onlyModified":`Csak ami eltér az alapértéktől`,"settings.advanced.resetTitle":`A kulcs visszaállítása az alapértékére`,"settings.look.updatesTitle":`Frissítések`,"settings.look.updatesAuto":`Automatikus ellenőrzés induláskor`,"settings.look.updatesCheck":`Frissítések keresése`,"settings.look.updatesChecking":`Ellenőrzés…`,"settings.look.updatesFailed":`Nem sikerült ellenőrizni a frissítéseket.`,"settings.look.updatesCurrent":`A {version} a legújabb verzió.`,"settings.look.updatesAvailable":`A {version} elérhető`,"settings.look.updatesAvailableContainer":`Elérhető a(z) {version}: frissítsd a konténerképet úgy, ahogyan telepítetted (docker pull, Unraid Community Applications, ...)`,"settings.look.updatesReleaseNotes":`Kiadási megjegyzések`,"settings.look.updatesContainerHint":`Frissítsd a konténer image-ét úgy, ahogy telepítetted, például docker pull paranccsal vagy az Unraid Community Applications segítségével.`,"settings.look.updatesAutoInstall":`Automatikus telepítés megtaláláskor`,"settings.look.updatesAutoInstallHint":`Letölti, ellenőrzi és telepíti az újabb verziót, amint az automatikus ellenőrzés talál egyet, majd újraindul. A fenti "Automatikus ellenőrzés indításkor" bekapcsolását igényli.`,"settings.look.updatesAutoInstallContainerHint":`Csak az asztali buildben lehetséges: egy konténer nem tudja belülről lecserélni önmagát. Frissítsd inkább úgy, ahogyan telepítetted (docker pull, Unraid Community Applications, Watchtower, ...).`,"settings.look.updatesAutoInstalling":`{version} telepítése…`,"settings.look.updatesInstalling":`Telepítés…`,"settings.look.updatesInstallNow":`Telepítés most`,"settings.look.updatesInstalled":`Telepítve, újraindítás…`,"settings.look.updatesInstallFailed":`A frissítést nem sikerült telepíteni: {error}`,"settings.look.updatesHint":`Összehasonlítja ennek a buildnek a verzióját a GitHubon elérhető legújabb kiadással. A desktop build automatikusan is le tudja tölteni és telepíteni egy újabb verziót; egy konténer helyette úgy frissül, ahogyan telepítve lett (docker pull, Unraid Community Applications, Watchtower, ...).`,"settings.advanced.modified":`megváltozott`,"settings.advanced.noMatch":`Egyetlen kulcs sem illik.`,"settings.advanced.badJson":`Ennek érvényes JSON-nak kell lennie, ezért nem kerül alkalmazásra.`,"settings.advanced.secret":`Tárolt titok soha nem megy ki a böngészőnek. Hagyd a helykitöltőt, ha meg akarod tartani, vagy írj be új értéket a cseréjéhez.`,"settings.advanced.listHint":`Itt JSON-ként szerkeszthető. A saját oldalán van hozzá rendes szerkesztő.`,"settings.advanced.defaultsUnavailable":`A gyári értékeket nem sikerült lekérni, így innen semmit sem lehet visszaállítani.`,"settings.advanced.type.boolean":`igen / nem`,"settings.advanced.type.number":`szám`,"settings.advanced.type.text":`szöveg`,"settings.advanced.type.list":`lista`,"settings.advanced.type.object":`csoport`,"settings.sectionLinkIntake":`Linkfogadás`,"settings.linkIntakeHint":`Ahogyan egy link magától a gyűjtőbe kerül, anélkül hogy ide beillesztenéd.`,"settings.linkIntake.cnlHint":`Fogadja a linkeket, amelyeket egy weboldal Click'n'Load gombja küld, pont úgy, mint a JDownloader. Amit itt átkapcsolsz, az a következő újraindításig érvényes, utána ismét a KL_CNL dönt.`,"settings.linkIntake.watchParked":`Újbóli bekapcsoláskor visszatér a korábban figyelt mappa.`,"settings.linkIntake.watchPickFolder":`Válassz lent egy mappát, és a kapcsoló magától bekapcsol.`,"settings.connections.add":`Kapcsolat hozzáadása`,"settings.connections.import":`Lista importálása`,"settings.connections.empty":`Minden ezen a gépen keresztül megy ki`,"settings.connections.emptyHint":`Nincs beállítva kimenő kapcsolat, így minden letöltés a gép saját vonalát használja. Adj hozzá egy proxyt, amelyen a letöltések átmennek, vagy egy közvetlen sort, hogy bizonyos tárhelyek kimaradjanak belőle.`,"settings.connections.use":`Ez a kapcsolat használatban`,"settings.connections.moveUp":`Fel`,"settings.connections.moveDown":`Le`,"settings.connections.remove":`Kapcsolat eltávolítása`,"settings.connections.edit":`Kapcsolat szerkesztése`,"settings.connections.type":`Típus`,"settings.connections.typeHint":`A „Nincs” és a „Közvetlen” mást jelent. A Nincs tétlen: nem nevez meg kapcsolatot, és soha nem használja semmi, így csak addig marad meg, amíg ki nem töltöd. A Közvetlen valódi választás: a gép saját kapcsolatán megy ki, és az alább megnevezett hosztoknál megkerül minden proxyt. Így veheted ki egy NAS-t az egész alkalmazásra érvényes proxy alól. Az a sor, amelynek szűrője illik a hosztra, legyőzi a szűrő nélküli sort, így a szűrős közvetlen sor mindig nyer a mindent elkapó proxyval szemben.`,"settings.connections.kind.none":`Nincs`,"settings.connections.kind.direct":`Közvetlen`,"settings.connections.warnDirectCatchAll":`Ennek a közvetlen sornak nincs kiszolgálószűrője, így sorra kerül a körforgásban, és véletlenszerűen proxy nélkül küld ki letöltéseket. Nevezd meg, mely kiszolgálókat vigye.`,"settings.connections.stateSocks4":`A SOCKS4 felhasználóazonosítót visz, és egyáltalán nincs jelszómezője, tehát ehhez a sorhoz nem tárolunk jelszót.`,"settings.connections.host":`Kiszolgáló`,"settings.connections.port":`Port`,"settings.connections.username":`Felhasználónév`,"settings.connections.usernameHint":`Magának a proxynak a belépési adatai, nem egy tárhelyfiók. A felhasználónév törlése a tárolt jelszót is törli.`,"settings.connections.password":`Jelszó`,"settings.connections.passwordStored":`tárolva (hagyd üresen, hogy megmaradjon)`,"settings.connections.passwordHint":`Tárolt jelszó soha nem kerül ki erre az oldalra, ezért üres a mező. Hagyd üresen, és a tárolt megmarad. A tárolt jelszó nem követi a sort másik kiszolgálóra, portra vagy típusra: ha ezek közül bármelyiket megváltoztatod, újra meg kell adni.`,"settings.connections.filter":`Kiszolgálószűrő`,"settings.connections.filterHint":`Soronként egy kiszolgáló. A csupasz tartomány mindent lefed alatta, tehát a dl2.example.org-hoz elég az example.org, és a * ? [ ] helyettesítő karakterként működik. Az üres azt jelenti, hogy ez a sor mindent elkap, ami gyengébb, mint egy olyan sor, amelynek szűrője illik a kiszolgálóra.`,"settings.connections.filterAll":`minden kiszolgáló`,"settings.connections.filterCount":`{n} kiszolgáló`,"settings.connections.cap":`Egyszerre letöltés`,"settings.connections.capHint":`Hány letöltés osztozhat egyszerre ezen a kapcsolaton. A 0 az alapértelmezett 2-t jelenti. A lista a letöltések szétosztására való, és ha egyetlen kapcsolat elvinné az egész sort, épp ezt hiúsítaná meg.`,"settings.connections.capDefault":`alapérték`,"settings.connections.test":`Teszt`,"settings.connections.testing":`Tesztelés…`,"settings.connections.testTarget":`Teszt ezzel szemben`,"settings.connections.testTargetHint":`Nem kötelező. Üresen hagyva a teszt csak azt mutatja, hogy a proxy válaszol. Nevezz meg egy kiszolgálót, és a proxyt megkérjük, hogy oda továbbítson - ez az, ami tényleg ellenőrzi a belépési adatokat, és megmutatja, hogy éppen azt a tárhelyet elutasítja-e.`,"settings.connections.testFailed":`A tesztet nem sikerült lefuttatni: {error}`,"settings.connections.importTitle":`Proxylista importálása`,"settings.connections.importLabel":`Proxylista`,"settings.connections.importHint":`Soronként egy, socks5://user:pass@host:port alakban. A https, socks4 és socks4a is jó, és az olvashatatlan sor eldobás helyett lent szerepel az okával.`,"settings.connections.importPlaceholder":`socks5://user:pass@proxy.example.org:1080`,"settings.connections.importRead":`Lista beolvasása`,"settings.connections.importReading":`Beolvasás…`,"settings.connections.importReady":`{n} hozzáadásra kész`,"settings.connections.importAdd":`{n} hozzáadása`,"settings.connections.importRefused":`{n} elutasítva`,"settings.connections.importNothing":`Ebből a listából semmit sem sikerült beolvasni.`,"settings.connections.importLine":`{n}. sor`,"settings.connections.importFailed":`A listát nem sikerült beolvasni: {error}`,"settings.connections.cancel":`Mégse`,"collector.filtered.restore":`Visszaállítás`,"collector.filtered.restoreAll":`Összes visszaállítása`,"collector.filtered.clear":`Törlés`,"collector.filtered.originTitle":`Honnan jött ez a hivatkozás`,"collector.filtered.origin.paste":`beillesztve`,"collector.filtered.origin.crawl":`oldalról begyűjtve`,"collector.filtered.origin.cnl":`Click'n'Load`,"collector.filtered.origin.watch":`figyelt mappa`,"collector.filtered.origin.container":`konténer`,"collector.filtered.restoreFailed":`Ezeket a hivatkozásokat nem sikerült visszaállítani. Elérhető a kiszolgáló?`,"collector.filtered.clearFailed":`Ezeket a hivatkozásokat nem sikerült törölni. Elérhető a kiszolgáló?`,"settings.rules.flavourLabel":`Melyik szabálylista`,"settings.rules.setupTitle":`Szabálykészlet`,"settings.rules.packagizerHint":`Minden linken lefut, amikor előkészítésre kerül, és átírja, amit tud: csomag, mappa, megjegyzés, prioritás, kapcsolatok, automatikus kibontás. Minden illeszkedő szabály hozzátesz, és mezőnként a későbbi szabály nyer.`,"settings.rules.filterHint":`Decides whether a link is taken into the collector at all. A rejected link is not deleted: the collector lists it with the rule and the reason that stopped it, so nothing ever disappears without saying why.`,"settings.rules.setOff":`Ez a lista ki van kapcsolva`,"settings.rules.setSwitchHint":`Az egész lista főkapcsolója. Ha ki van kapcsolva, egyetlen alábbi szabály sem fut, de mindegyik ugyanúgy szerkeszthető és szárazon kipróbálható, így a lista kikapcsolt állapotában is megtalálhatod és kijavíthatod, ami hibás.`,"settings.rules.stopAfterMatch":`Állj meg az első illeszkedő szabálynál`,"settings.rules.stopHint":`Kikapcsolva minden illeszkedő szabály hozzátesz, és mezőnként a későbbi nyer: ezt akarja a Packagizer. Bekapcsolva a kiértékelés az első találatnál véget ér: általában ezt akarja egy szűrő, mert így egy tág elutasítás fölé tett elfogadás valóban megvédi a linket.`,"settings.rules.listTitle":`Szabályok, futási sorrendben`,"settings.rules.add":`Szabály hozzáadása`,"settings.rules.import":`Importálás`,"settings.rules.export":`Exportálás`,"settings.rules.exportTitle":`A lista mentése JSON-fájlként`,"settings.rules.importTitle":`A lista cseréje JSON-fájlból`,"settings.rules.importFailed":`Ez a fájl nem szabálylista: {reason}`,"settings.rules.importedCount":`{n} szabály betöltve. Semmi nem mentődik, amíg nem menti az oldalt.`,"settings.rules.empty":`Még nincsenek szabályok`,"settings.rules.emptyPackagizer":`Minden hivatkozás megtartja a csomagot, a mappát és a beállításokat, amikkel érkezett. Adjon hozzá szabályt, hogy már beérkezéskor rendeződjenek.`,"settings.rules.emptyFilter":`Every link is taken. Add a rule to reject some of them.`,"settings.rules.unnamed":`{n}. szabály`,"settings.rules.duplicate":`A szabály megkettőzése`,"settings.rules.remove":`A szabály eltávolítása`,"settings.rules.moveUp":`Fel`,"settings.rules.moveDown":`Le`,"settings.rules.ruleOn":`Ez a szabály fut`,"settings.rules.ruleOff":`Ez a szabály ki van kapcsolva`,"settings.rules.problemCount":`{n} probléma`,"settings.rules.problemOne":`1 probléma`,"settings.rules.notRunning":`Ez a szabály nincs érvényben. Javítsa a felsoroltakat, és újra működni fog.`,"settings.rules.matchedCount":`{total} közül {n} illeszkedett`,"settings.rules.name":`Név`,"settings.rules.namePlaceholder":`Mire való ez a szabály`,"settings.rules.nameHint":`Only ever shown to you: in this list, on a problem, and on the reason a link was rejected. An unnamed rule is called by its position, which changes when you reorder the list.`,"settings.rules.sectionIf":`Ha mindez igaz`,"settings.rules.ifHint":`Minden feltételnek teljesülnie kell. A vagy-vagy két szabályként írandó, így a lista fentről lefelé olvasható marad. A feltétel nélküli szabály minden linkre illeszkedik. Így írható meg egy mindent felfogó mappa vagy egy általános elutasítás a lista végén.`,"settings.rules.fieldPicker":`Mit nézzen`,"settings.rules.opPicker":`Hogyan hasonlítsa`,"settings.rules.sectionThen":`Akkor`,"settings.rules.thenHintPackagizer":`Az üres mező azt jelenti, „hagyd békén”, sosem azt, hogy „töröld”: az a szabály, amelyik csak a mappát állítja be, nem törölheti a csomagnevet, amit egy korábbi szabály választott.`,"settings.rules.thenHintFilter":`A link a rule rejects is listed in the collector with the rule's reason. A rule that accepts is worth having too: placed above a broad reject, with "Stop at the first matching rule" on, it is how one hoster is let through.`,"settings.rules.addCondition":`Feltétel hozzáadása`,"settings.rules.removeCondition":`A feltétel eltávolítása`,"settings.rules.noConditions":`Nincs feltétel, így ez a szabály minden linkre illeszkedik.`,"settings.rules.value":`Érték`,"settings.rules.min":`Legalább`,"settings.rules.max":`Legfeljebb`,"settings.rules.noUpperBound":`nincs felső határ`,"settings.rules.sizeHint":`A puszta szám bájtot jelent. Mértékegység is megadható (700 MB, 1.5 GiB), és mindkettő 1024-es alapon értendő, ugyanúgy, mint minden méret, amit az alkalmazás többi része kiír.`,"settings.rules.badSize":`Ez nem méret.`,"settings.rules.pattern":`Minta`,"settings.rules.patternHint":`Go reguláris kifejezés, horgony nélkül. Ez az egyetlen művelet, amely nem hagyja figyelmen kívül a kis- és nagybetűket; ha szeretnéd, hogy igen, írj (?i)-t az elejére. Az értelmezhetetlen mintát indoklással elutasítjuk, ahelyett hogy csendben semmire sem illeszkedne.`,"settings.rules.category":`Fájltípus`,"settings.rules.categoryCustom":`Saját minta`,"settings.rules.categoryHint":`Gyorsválasztás, amely kitölti a mintát egy egész kiterjesztéscsaládra. Közönséges mintaként tárolódik, így kiválaszthatsz egyet, majd szerkesztheted. Ezután itt újra „Saját minta” áll, mert a gyorsválasztás már nem mondja meg, mit csinál a szabály.`,"settings.rules.categoryExtensions":`Lefedi: {list}`,"settings.rules.unchanged":`Változatlan`,"settings.rules.yes":`Be`,"settings.rules.no":`Ki`,"settings.rules.reject":`Hivatkozás elutasítása`,"settings.rules.accept":`Hivatkozás elfogadása`,"settings.rules.priorityHint":`A magasabb fut előbb. A tartomány az, amit maga a sor elfogad, tehát egy szabály nem adhat egy feladatnak olyan prioritást, amit nem tud visszavonni. Hagyja üresen, ha semmit nem akar változtatni.`,"settings.rules.chunksHint":`Hány kapcsolattal töltődik le ez az egy fájl. Hagyja üresen a globális beállításhoz. Néhánynál több semmit nem hoz olyan tárhelynél, amely fájlonként korlátoz, és biztos módja annak, hogy megjelöljék a fiókot.`,"settings.rules.emptyMeansUnchanged":`üres = változatlan`,"settings.rules.variables":`Változók`,"settings.rules.variablesTitle":`Változó beszúrása`,"settings.rules.variablesHint":`Mindegyik a linkre oldódik fel úgy, ahogy megérkezett, így a szabályok nem épülnek egymásra: a negyedik szabály mappasablonja a tárhely által adott nevet látja, nem azt, amire a második szabály átnevezte. Hogy egy szabály mit csinál, az magából a szabályból kiolvasható.`,"settings.rules.varParams":`cserélje: {params}`,"settings.rules.field.filename":`Fájlnév`,"settings.rules.field.url":`Hivatkozás címe`,"settings.rules.field.hoster":`Tárhely`,"settings.rules.field.source":`Forrásoldal`,"settings.rules.field.filetype":`Fájltípus`,"settings.rules.field.filesize":`Fájlméret`,"settings.rules.field.package":`Csomag`,"settings.rules.op.contains":`tartalmazza`,"settings.rules.op.contains-not":`nem tartalmazza`,"settings.rules.op.equals":`egyenlő`,"settings.rules.op.equals-not":`nem egyenlő`,"settings.rules.op.matches":`illeszkedik a mintára`,"settings.rules.op.is-between":`e között van`,"settings.rules.action.packageName":`Csomagnév`,"settings.rules.action.downloadDir":`Letöltési mappa`,"settings.rules.action.extractDir":`A kibontott fájlok áthelyezése ide`,"settings.rules.action.comment":`Megjegyzés`,"settings.rules.action.priority":`Prioritás`,"settings.rules.action.autoExtract":`Automatikus kibontás`,"settings.rules.action.chunks":`Kapcsolatok`,"settings.rules.action.reject":`Ítélet`,"settings.rules.action.reason":`Indok`,"settings.rules.action.reasonHint":`Shown next to the rejected link. If you leave it empty, one is written for you, because a rejection nobody can explain is exactly what this list exists to avoid.`,"settings.rules.action.downloadDirHint":`Hová töltődik le egy illeszkedő link. Csak ez a mező és „A kibontott fájlok áthelyezése ide” írhat ki útvonalszinteket. Minden más mezőt egyetlen névre vágunk vissza, mert a perjelet tartalmazó fájlnév kiút a választott mappából.`,"settings.rules.action.extractDirHint":`Hová kerülnek egy illeszkedő link kibontott fájljai, ha a kibontás befejeződött. Ezeknél a linkeknél felülírja az Archívumok oldal „A kibontott fájlok áthelyezése ide” beállítását. Változók itt is működnek.`,"settings.rules.category.video":`Videó`,"settings.rules.category.audio":`Hang`,"settings.rules.category.image":`Képek`,"settings.rules.category.archive":`Archívumok`,"settings.rules.category.document":`Dokumentumok és könyvek`,"settings.rules.category.subtitle":`Feliratok`,"settings.rules.category.disc":`Lemezképek`,"settings.rules.category.program":`Programok és csomagok`,"settings.rules.var.packagename":`A csomag, amelyben a hivatkozás érkezett`,"settings.rules.var.hoster":`A tárhely, www. nélkül`,"settings.rules.var.filename":`A fájlnév úgy, ahogy érkezett`,"settings.rules.var.orgfilename":`A fájlnév úgy, ahogy érkezett`,"settings.rules.var.orgfilenamewithoutext":`A fájlnév kiterjesztés nélkül`,"settings.rules.var.orgfiletype":`A kiterjesztés pont nélkül, üres, ha nincs`,"settings.rules.var.date":`Ma, YYYY-MM-DD alakban`,"settings.rules.var.year":`Az év, YYYY alakban`,"settings.rules.var.month":`A hónap, MM alakban`,"settings.rules.var.day":`A nap, DD alakban`,"settings.rules.var.simpledate":`A dátum az ön által írt mintában, a Java dátumszintaxisával`,"settings.rules.var.source":`A forrásoldal URL-jének N-edik útvonalszakasza, 1-től számolva: a https://site.org/tv/s01/list.html címen az 1 a tv, a 2 az s01. A JDownloader ezen a címkén mást ért; a „Változó beszúrása” melletti (i) elmondja a különbséget.`,"settings.rules.var.match":`E szabály FIELD mezőn futó „illeszkedik a mintára” mintájának N. rögzítőcsoportja. Ez a JDownloader <jd:source:N> címkéje, olyan néven, amely megmondja, melyik mintát olvassa. Az a szabály, amelynek azon a mezőn nincs illeszkedő mintája, mentéskor elutasításra kerül, ahelyett hogy csendben <jd:match:url:1> nevű mappát gyártana.`,"settings.rules.var.append":`Semmi, amikor ez az érték először előfordul, utána _2, _3 és így tovább`,"settings.rules.sourceDivergence":`JDownloader-beállításból másolsz sablont? A <jd:source:N> itt mást jelent: a forrás-URL egy útvonalszakaszát, nem rögzítőcsoportot. A JD-féle jelentés <jd:match:FIELD:N> alakban írandó. A kettő elég gyakran egyezik ahhoz, hogy veszélyes legyen, ezért a másolt sablont mentés előtt érdemes lent szárazon lefuttatni.`,"settings.rules.testTitle":`Próbálja ki egy hivatkozáson`,"settings.rules.testHint":`Itt semmi nem töltődik le, nem tárolódik és nem mentődik. A lista úgy, ahogy ezen az oldalon áll, lefut ezeken a mintákon, ugyanazzal a kóddal, amely a hivatkozások átvételekor fut.`,"settings.rules.testUrl":`Hivatkozás címe`,"settings.rules.testFilename":`Fájlnév`,"settings.rules.testSource":`Forrásoldal`,"settings.rules.testSourceHint":`Az oldal, amelyen egy bejárás megtalálta a hivatkozást. Csak olyan szabálynál érdemes kitölteni, amely a forrásmezőt vizsgálja vagy <jd:source:N>-t használ.`,"settings.rules.testSize":`Méret`,"settings.rules.testPackage":`Csomag`,"settings.rules.testPackageHint":`A csomag, amelybe a link érkezne, mielőtt bármely szabály lefutna. Erre oldódik fel a <jd:packagename>, mert a mappasablon nem látja azt a csomagnevet, amelyet egy szabály ugyanabban a menetben állít be.`,"settings.rules.testAdd":`Minta hozzáadása`,"settings.rules.testRemove":`A minta eltávolítása`,"settings.rules.testEmpty":`Illesszen be egy hivatkozást és egy fájlnevet, hogy lássa, hova kerülne.`,"settings.rules.testRunning":`Ellenőrzés…`,"settings.rules.testFailed":`A száraz futtatás nem volt elérhető: {reason}`,"settings.rules.resultMatched":`Találatok sorrendben`,"settings.rules.resultNone":`Egyetlen szabály sem illeszkedett`,"settings.rules.resultPackage":`Csomag`,"settings.rules.resultFolder":`Mappa`,"settings.rules.resultFilename":`Fájlnév`,"settings.rules.resultRejected":`Rejected`,"settings.rules.resultAccepted":`Elfogadva`,"settings.rules.resultBy":`eszerint: {rule}`,"settings.rules.folderFromSettings":`a letöltési beállításokból`,"settings.rules.folderFromSettingsHint":`Egyik szabály sem nevezett meg mappát, így a link a beállított letöltési mappába kerül, esetleg egy csomagonkénti almappába, ha ez a beállítás be van kapcsolva. Ez az oldal nem találgatja ki a teljes útvonalat. Csak azt tudja biztosan mondani, hogy egyik szabály sem változtatta meg.`,"settings.rules.alsoSets":`Ezt is beállítja`,"settings.reconnect.method":`Módszer`,"settings.reconnect.methodHint":`Ahogy a router megkapja, hogy bontsa a vonalat és új címmel térjen vissza. A „Parancs” elindít egy programot, a „Kérések” újrajátszanak egy rögzített HTTP-beszélgetést, az UPnP a hálózaton keresztül kérdezi meg az átjárót, mindenféle bejelentkezés nélkül, a „Szkript” pedig átad egy fájlt egy értelmezőnek. Csak azok a mezők látszanak, amelyekre a választott módszernek szüksége van; a többi megőrzi, amit beírtál, és visszatér, ha átváltasz rájuk.`,"settings.reconnect.method.command":`Parancs`,"settings.reconnect.method.http":`Kérések`,"settings.reconnect.method.upnp":`UPnP`,"settings.reconnect.method.script":`Szkript`,"settings.reconnect.offState":`Az újracsatlakozás ki van kapcsolva. Semmi nem kér új címet a routertől, a hoster korlátja pedig marad a szokásos újrapróbálkozási várakozáson.`,"settings.reconnect.command":`Program`,"settings.reconnect.commandHint":`A futtatandó program teljes elérési útja. Közvetlenül indul, nem parancsértelmezőn keresztül, így egy csővezeték, egy átirányítás vagy két parancs egymás után a „Szkript” módszerbe való. A %%router%%, %%username%%, %%password%% és %%ip%% az indítás előtt behelyettesítődik.`,"settings.reconnect.args":`Argumentumok`,"settings.reconnect.argsHint":`Soronként egy, hogy a szóközt tartalmazó argumentum egy argumentum maradjon. Ugyanaz a négy változó itt is behelyettesítődik.`,"settings.reconnect.upnpState":`Más nem kell. Az átjárót a hálózat megkérdezésével találja meg, ezért ez az a módszer, amely úgy is működik, hogy semmit sem tudsz a routerről.`,"settings.reconnect.upnpLocation":`Az átjáró leíró URL-je`,"settings.reconnect.upnpLocationHint":`Nem kötelező, és rendesen üres. Csak ott töltsd ki, ahol a multicast keresés ki van szűrve, miközben maga az átjáró tökéletesen elérhető, mert ezt a felderítés önmagában sosem tudja helyrehozni.`,"settings.reconnect.interpreter":`Értelmező`,"settings.reconnect.interpreterHint":`Az a program, amelynek a szkript át lesz adva, teljes elérési úttal: /bin/sh, /bin/bash, /usr/bin/python3.`,"settings.reconnect.interpreterArgs":`Az értelmező argumentumai`,"settings.reconnect.interpreterArgsHint":`Soronként egy, a szkriptfájl elé kerülnek. Általában üres.`,"settings.reconnect.script":`Szkript`,"settings.reconnect.scriptHint":`Egy privát ideiglenes fájlba íródik, és az értelmező ennek az útvonalát kapja meg, így innen soha semmi nem kerül idézőjelek közé egy parancssorba. A változók még a fájl kiírása előtt behelyettesítődnek, vagyis az ide beírt jelszó eljut abba a fájlba: a %%password%% viszont a jelszómezőben tartja.`,"settings.reconnect.router":`A router címe`,"settings.reconnect.routerHint":`A saját hálózatod routere, séma nélkül: 192.168.1.1, nem http://192.168.1.1/. Erre bomlik ki a %%router%%. Ez nem a nyilvános cím, és a kettőt soha nem szabad összekeverni: a nyilvánosra irányított bejelentkezési kérés kiküldi a router jelszavadat az internetre.`,"settings.reconnect.routerFind":`Router keresése`,"settings.reconnect.routerFinding":`Keresés…`,"settings.reconnect.routerFound":`Megvan: {address}.`,"settings.reconnect.routerFoundVia":`Megvan: {address}, a(z) {iface} felől. Érdemes ránézni: konténerben ez sokszor a híd, nem a router.`,"settings.reconnect.routerFailed":`Itt nem sikerült routercímet kiolvasni: {reason}`,"settings.reconnect.username":`Router felhasználóneve`,"settings.reconnect.usernameHint":`A routerbe való belépés, nem egy hoster fiók. Erre bomlik ki a %%username%%.`,"settings.reconnect.password":`Router jelszava`,"settings.reconnect.passwordStored":`elmentve, és soha nem küldjük vissza ide`,"settings.reconnect.passwordHint":`Egy elmentett jelszó soha nem kerül vissza erre az oldalra, ezért üres a mező: hagyd üresen, és az elmentett megmarad. Írj be újat, ha le akarod cserélni. Ha teljesen el akarod távolítani, írj be valamit, majd töröld ki újra a mezőt.`,"settings.reconnect.requests":`Kérések`,"settings.reconnect.requestsHint":`Sorrendben játszódnak le, és a futás megáll az elsőnél, amelyre a router nem válaszol. Ez a JDownloader LiveHeader módszere: általában egy bejelentkezés, majd az újraindítás vagy a bontás. Minden mező elfogadja a változókat.`,"settings.reconnect.requestsEmpty":`Még nincs kérés. Adj hozzá egyet, vagy illessz be egy rögzített szkriptet.`,"settings.reconnect.requestAdd":`Kérés hozzáadása`,"settings.reconnect.requestStep":`{n}. lépés`,"settings.reconnect.requestUp":`Kérés feljebb`,"settings.reconnect.requestDown":`Kérés lejjebb`,"settings.reconnect.requestRemove":`Kérés eltávolítása`,"settings.reconnect.requestMethod":`Metódus`,"settings.reconnect.requestUrl":`URL`,"settings.reconnect.requestUrlHint":`A teljes URL, sémával együtt. A http://%%router%%/login.cgi a szokásos alak.`,"settings.reconnect.requestHeaders":`Fejlécek`,"settings.reconnect.requestHeadersHint":`Soronként egy, Név: érték alakban. A Host fejléc érvényesül és tényleg kimegy a vonalra, márpedig épp erre van szükségük azoknak a router firmware-eknek, amelyek virtuális hostként szolgálják ki az adminfelületet.`,"settings.reconnect.requestBody":`Törzs`,"settings.reconnect.requestBodyHint":`Változtatás nélkül megy ki. A saját tartalomtípus nélküli törzs űrlapküldésként indul, és pontosan ez egy rögzített routeres bejelentkezés.`,"settings.reconnect.import":`Szkript importálása`,"settings.reconnect.importLabel":`LiveHeader vagy curl szkript`,"settings.reconnect.importHint":`Illessz be egy JDownloader újracsatlakozási szkriptet, jelölőkkel együtt. A változói behozatalkor átfordulnak, és a %%%routerip%%% a router címe lesz, nem a nyilvános, mert itt ez két külön dolog.`,"settings.reconnect.importRead":`Szkript beolvasása`,"settings.reconnect.importReading":`Beolvasás…`,"settings.reconnect.importClose":`Bezárás`,"settings.reconnect.importMapped":`{n} átvéve`,"settings.reconnect.importRefusedCount":`{n} elutasítva`,"settings.reconnect.importUse":`A lista cseréje erre: {n}`,"settings.reconnect.importLine":`{n}. sor`,"settings.reconnect.importBlocked":`Olyan szkriptből, amelyben akár egy elutasított sor van, semmit sem veszünk át. A fél routerszkript egy bejelentkezés újraindítás nélkül, és ez csak napokkal később derül ki, olyan cím formájában, ami soha nem változik.`,"settings.reconnect.importFailed":`A szkriptet nem sikerült beolvasni: {reason}`,"settings.reconnect.checkTitle":`A cím ellenőrzése`,"settings.reconnect.checkUrl":`IP-ellenőrző URL`,"settings.reconnect.checkUrlHint":`A módszer futása előtt és után is lekérjük; a futás akkor számít késznek, amikor az általa kiírt cím megváltozott. Nincs alapérték: egy saját üzemeltetésű letöltéskezelőnek nem dolga egy általad soha ki nem választott szolgáltatásnak jelenteni a címedet. Annak a címnek kell megjelennie, amelyet az internet lát, mert egy oldal, amely a saját hálózatodon belüli címet adja vissza, nem tudja megkülönböztetni az újracsatlakozást a hatástalan futástól.`,"settings.reconnect.checkPresets":`Ismert szolgáltatások`,"settings.reconnect.checkPresetsHint":`Rövidítés annak, akinek mindegy, nem alapértelmezés: egyiket sem választjuk ki helyetted, és bármelyik oldal, ami kiírja a nyilvános címedet, ugyanolyan jó.`,"settings.reconnect.interval":`Másodperc két ellenőrzés között (1-60)`,"settings.reconnect.intervalHint":`Mennyit vár két pillantás között az ellenőrző címre, miután a módszer lefutott. Van alsó határ, mert a nélküle futó ciklus célponttá teszi az ellenőrző szolgáltatást.`,"settings.reconnect.timeout":`Ennyi másodpercig ellenőriz (5-900)`,"settings.reconnect.timeoutHint":`How long to keep looking before the run is called a failure. A reconnect still waiting a quarter of an hour later has failed whatever this says. A timeout below the interval is raised to it, or the run would be over before a single check happened. The Command and Script methods give their program the same number of seconds to finish before the checking starts; one still running then is stopped, and the run fails.`,"settings.reconnect.clamped":`Mentve így: {n}.`,"settings.reconnect.runTitle":`Futtatás most`,"settings.reconnect.runNow":`Újracsatlakozás most`,"settings.reconnect.running":`Fut…`,"settings.reconnect.runMoved":`A cím {from} helyett {to} lett.`,"settings.reconnect.runDetail":`{n} ellenőrzés, {secs} mp`,"settings.reconnect.runBusy":`Már fut egy újracsatlakozás, ezért ez nem indult el. Az eredmény azé, aki az elsőt kérte.`,"settings.reconnect.runFailed":`Az újracsatlakozás nem futott végig: {reason}`,"settings.reconnect.stateConfigured":`Beállítva`,"settings.reconnect.stateNotConfigured":`Nincs beállítva`,"settings.reconnect.stateIdle":`Tétlen`,"settings.reconnect.stateBusy":`Most fut`,"settings.reconnect.stateUnreadable":`Az újracsatlakozás állapotát nem sikerült kiolvasni. Elérhető a kiszolgáló?`,"settings.reconnect.notReady":`Nem áll készen: {reason}`,"settings.reconnect.reason.off":`Az újracsatlakozás ki van kapcsolva`,"settings.reconnect.reason.noCommand":`A parancs módszerhez nincs futtatandó program`,"settings.reconnect.reason.noRequests":`A kérés módszerhez nincs egyetlen kérés sem`,"settings.reconnect.reason.requestNoURL":`A(z) {n}. kérésnek nincs URL-je`,"settings.reconnect.reason.noInterpreter":`A szkript módszerhez nincs értelmező, amely futtatná`,"settings.reconnect.reason.noScript":`A szkript módszerhez nincs szkript`,"settings.reconnect.reason.noCheckURL":`Nincs IP-ellenőrző URL`,"settings.reconnect.reason.unknownMethod":`Ismeretlen módszer: „{method}”`,"settings.reconnect.reason.noRouter":`A szkript a %%{var}%% változót használja, de nincs útválasztócím megadva`,"settings.reconnect.runUsesSaved":`A mentett beállítás fut, nem a képernyőn látható. Előbb mentsen.`,"settings.reconnect.policy":`Mikor történik ez magától`,"settings.reconnect.policyHint":`Az automatikus újracsatlakozásokat egyetlen helyen indítjuk, és az nem ez az oldal. Egy akkor indul, amikor egy letöltési backend maga kér újabb próbát egy várakozás után, mert így mondja meg egy hoster, hogy a korlát ehhez a címhez van kötve. Sosem fut, amíg a sor le van állítva, mert a router újraindítása elvágja a még futó letöltéseket. Sosem fut, amíg az újracsatlakozás nincs teljesen beállítva. Egyszerre csak egy fut: a második kérés megvárja az első ítéletét, ahelyett hogy a routerért veszekedne vele. És ha a cím nem mozdul, semmit nem hozunk előre, hanem hagyjuk lejárni a szokásos újrapróbálkozási várakozást.`,"shell.bar":`Sor és állapotsáv`,"shell.scope":`Vezérli`,"shell.scopeHint":`A lenti oldal ezt a társpéldányt mutatja, így a sáv is arra irányul. Egy társpéldánynak saját sora és saját sebességkorlátja van, ezért minden, amit ez a példány nem tud továbbadni, nem elérhetőként jelenik meg ahelyett, hogy erre a gépre vonatkozna.`,"task.moveUp":`Feljebb`,"task.moveDown":`Lejjebb`,"menu.priority":`Prioritás`,"menu.move":`Áthelyezés`,"menu.forceStart":`Indítás most`,"pkg.queueOrder":`Az egész csomag mozgatása`,"priority.highest":`Legmagasabb`,"priority.higher":`Magasabb`,"priority.high":`Magas`,"priority.default":`Alapérték`,"priority.low":`Alacsony`,"priority.lower":`Alacsonyabb`,"priority.lowest":`Legalacsonyabb`,"settings.chunks":`Kapcsolatok letöltésenként (0 = automatikus)`,"settings.chunksHint":`Hány kapcsolatot nyit egy letöltés, ha semmi pontosabb nem érvényes. Egy szabály vagy egyetlen letöltés megadhatja a saját számát, és az ezt felülírja. Az a tárhely, amelyik kevesebbet visel el, akkor is kevesebbet kap: a tárhely korlátja csak csökkenteni tudja a számot, növelni soha. 0 esetén az alkalmazás dönt. Egy maréknyinál több kapcsolat semmit sem hoz olyan tárhelyen, amelyik fájlonként korlátoz, viszont biztos módja annak, hogy egy fiókot megjelöljenek.`,"task.chunks":`Kapcsolatok (0 = a globális beállítás)`,"task.chunksHint":`Hány kapcsolatot nyit ez az egy letöltés. Felülírja a globális beállítást és minden szabályt, amelyik beállította, de a tárhelyet soha: az a tárhely, amelyik kevesebbet visel el, akkor is kevesebbet kap. 0 esetén a kivétel megszűnik, és a szám megint máshol dől el.`,"columns.connection":`Kapcsolat`,"props.title":`Tulajdonságok`,"props.mixed":`Több érték`,"props.mixedHint":`Ezek a sorok nem egyeznek, ezért a mező üres. Ha nem nyúlsz hozzá, semmi sem változik; írj bele, és minden kijelölt sor azt kapja, amit beírtál.`,"props.name":`Név`,"props.nameHint":`Egyetlen fájlnév, sosem elérési út: a / vagy \\ jelet tartalmazó név elutasításra kerül. A befejezett letöltés a lemezen is átnevezésre kerül, hogy a lista és a mappa ne térhessen el. A futó letöltés megtartja a fájlt, amelyet a háttérrendszere megnyitott, és a befejezéskor kapja meg az új nevet. A még el nem indult azonnal megkapja. Egy név egy fájlhoz tartozik, ezért ez a mező csak egy sorhoz jelenik meg.`,"props.comment":`Megjegyzés`,"props.commentHint":`A saját megjegyzésed ehhez a linkhez. Elmentődik és megjelenik a listában; az alkalmazásban semmi nem igazodik hozzá.`,"props.priority":`Prioritás`,"props.priorityHint":`A magasabb fut előbb. Azt rendezi át, ami még vár; a már futó letöltést nem küldi vissza a sorba.`,"props.autoExtract":`Archívumok kibontása`,"props.autoExtractHint":`Kicsomagolódik-e egy archívum, ha a letöltés befejeződött. Az „Öröklés” a döntést az archívumok beállítási oldalára bízza, ami nem ugyanaz, mint a ki. A kapcsolót a kicsomagolás pillanatában olvassuk, így ha most kapcsolod be, kicsomagolódik olyasmi is, ami korábban készült el.`,"props.inherit":`Öröklés`,"props.on":`Be`,"props.off":`Ki`,"strip.label":`Letöltési összesítők`,"strip.of":`/`,"strip.hint":`A letöltött bájtok a még hátralévőkhöz mérve. A kész, a sikertelen és a csak begyűjtött linkek kimaradnak az összesítésből, és kimarad minden, aminek a méretét a tárhely még nem közölte, mert ott egy becslés olyan szám lenne, amivel senki sem tud mit kezdeni.`,"strip.scope":`Mire vonatkoznak a számok`,"strip.total":`Összesen`,"strip.visible":`Látható`,"strip.selected":`Kijelölt`,"strip.includeDisabled":`A kikapcsoltak is számítsanak`,"strip.includeDisabledHint":`Beszámítja a kikapcsolt linkek bájtjait. A hátralévő időből így is, úgy is kimaradnak: senki sem hozza le őket, tehát semmilyen várakozás nem dolgozza le őket.`,"quick.title":`Gyorsbeállítások`,"quick.reconnectHint":`Új nyilvános címet kér a routertől úgy, ahogy a Hálózat oldalon be van állítva.`,"quick.reconnectOff":`Az újracsatlakozás ki van kapcsolva a Modulok oldalon.`,"quick.reconnectUnset":`Még nincs beállítva újracsatlakozás. Előbb válassz módszert a Hálózat oldalon.`,"quick.schedulesOff":`Az „Időzítések” ki van kapcsolva a Modulok oldalon.`,"quick.autoStartHint":`A hozzáadott linkek letöltése elindul anélkül, hogy a gyűjtőben meg kellene erősítened őket. Hogy előtte mennyit várnak, azt a(z) {page} oldalon állíthatod be.`,"quick.idleCommandSetup":`Parancs beállítása az Automatizálás oldalon`,"quick.openPage":`{page} megnyitása`,"folders.title":`Válasszon mappát`,"folders.browse":`Mappák tallózása`,"folders.path":`Útvonal`,"folders.up":`Egy szinttel feljebb`,"folders.use":`Ezt a mappát használom`,"folders.empty":`Itt nincsenek almappák.`,"folders.new":`Ez a mappa még nem létezik. Akkor jön létre, amikor az első letöltés beleérkezik.`,"folders.newWatch":`Ez a mappa még nem létezik, és magától semmi sem hozza létre. A bele tett fájlokat felvesszük, amint létrejön. Az „Új mappa” azonnal létrehozza.`,"folders.tail":`Megmarad`,"folders.tailHint":`A tallózás csak a mappa rögzített részét cseréli le. A változók visszakerülnek a végére, így a névadási rendje nem vész el.`,"folders.roots":`Gyökerek`,"folders.truncated":`Csak az első {n} mappa látszik. Írjon be egy útvonalat, hogy egyenesen odajusson.`,"folders.newFolder":`Új mappa`,"folders.newFolderHint":`Üres mappát hoz létre a fent látható mappában, azon a gépen, amelyen a KnightLoader fut.`,"folders.newName":`Az új mappa neve`,"folders.create":`Létrehozás`,"folders.error.exists":`Itt már van valami „{name}” néven.`,"folders.error.denied":`A KnightLoader nem írhat ide. Nézd meg, kié ez a mappa, és milyen jogosultságai vannak.`,"folders.error.outside":`Ez a mappa kívül esik azokon a gyökereken, amelyeket ez a példány használhat.`,"folders.error.missing":`Ez a mappa már nincs meg. Lépj egy szinttel feljebb, és próbáld újra.`,"folders.error.separator":`A név nem tartalmazhat / vagy \\ jelet. Egyszerre egy szintet hozz létre.`,"folders.error.dots":`A „.” és a „..” nem lehet mappanév.`,"folders.error.character":`A név nem tartalmazhat < > : " | ? * jelet vagy vezérlőkaraktert.`,"folders.error.trailing":`A név nem végződhet ponttal vagy szóközzel.`,"folders.error.reserved":`A(z) „{name}” név foglalt Windowson, és nem lehet mappanév.`,"folders.error.tooLong":`Ez a név túl hosszú. A korlát 255 bájt.`,"folders.error.relative":`Írj be egy teljes, a legfelső szintről induló útvonalat, például / vagy C:\\.`,"folders.error.unreachable":`Ezen az útvonalon és felette nincs olyan mappa, amelyet a KnightLoader meg tud nyitni.`,"folders.error.unreadable":`A KnightLoader nem nyithatja meg ezt a mappát. Nézd meg, kié, és milyen jogosultságai vannak.`,"folders.error.roots":`A KL_BROWSE_ROOTS be van állítva, de nem nevez meg abszolút mappát, így nincs mit tallózni. Javítsd a változót, és indítsd újra.`,"archive.menu":`Archívum`,"archive.unpackNow":`Kibontás most`,"archive.stop":`Kibontás leállítása`,"archive.queued":`Kibontásra vár`,"archive.failed":`Nincs kibontva`,"archive.volumes":`{volumes} kötet`,"archive.needsPassword":`Jelszó kell hozzá`,"settings.archives.handles":`Megnyitja`,"settings.archives.destination":`Kibontás ide`,"settings.archives.destinationHint":`Hová érkeznek a kibontott fájlok. Hagyja üresen, és az archívum mellé kerülnek.`,"settings.archives.besideArchive":`Az archívum mellé`,"settings.archives.subfolder":`Csomagonként egy mappa`,"settings.archives.subfolderHint":`Minden csomagot saját mappába tesz a célon belül. Semmit sem tesz addig, amíg a fájlok az archívum mellé érkeznek, ahol a csomag mappája már úgyis a céljuk.`,"settings.archives.collision":`Ha már van ott fájl`,"settings.archives.collisionHint":`Mit tesz a kibontó, ha a mappában már van ilyen nevű fájl. Egyedül dönt, és az egész mappára: a kibontás közepén nincs kit megkérdezni.`,"settings.archives.collision.overwrite":`Felülírás`,"settings.archives.collision.rename":`Mindkettő megtartása`,"settings.archives.collision.skip":`Kihagyás`,"settings.archives.afterwards":`Utána`,"settings.archives.disposal":`Maga az archívum`,"settings.archives.disposalHint":`Mi lesz az archívummal, ha egyszer kibontották. Egy konténerben nincs kuka, ezért a középső válasz egy áthelyezés a fájlok melletti {folder} mappába, amelyet később kor szerint söpör ki a takarítás.`,"settings.archives.disposal.keep":`Megtartás`,"settings.archives.disposal.trash":`Kukába`,"settings.archives.disposal.delete":`Törlés`,"settings.archives.retention":`Kuka ürítése ennyi után (nap)`,"settings.archives.retentionHint":`Meddig marad egy archívum a(z) {folder} mappában, mielőtt a takarítás elviszi. A 0 semmit sem söpör ki, a mappát tehát kézzel kell üríteni.`,"settings.archives.infoFiles":`A mellette lévő jegyzeteket is vigye`,"settings.archives.infoFilesHint":`Az archívummal együtt érkezett, nem belőle kikerült fájlok, például .nfo, .sfv és .txt. Csak a csomag saját fájljaihoz nyúl, sosem az egész mappához: az alapértelmezett elrendezésben egy mappában több kiadás is van, és egy olyan takarítás, amely a mappát olvassa, elvinné a szomszédok jegyzeteit.`,"settings.archives.optionsFailed":`A kibontó saját listáit nem sikerült lekérni, ezért az onnan származó választási lehetőségek nem látszanak.`,"accounts.accountLabel":`Fiók neve`,"accounts.accountLabelHint":`Ennek a szolgáltatásnak már van alapértelmezett fiókja. Nevezd el ezt, hogy egy második bejelentkezést adj hozzá mellé.`,"accounts.accountLabelPlaceholder":`pl. munka`,"accounts.buyPremium":`Prémium vásárlása`,"accounts.changeAccount":`Másik fiók választása`,"accounts.col.enabled":`Engedélyezve`,"accounts.col.expiry":`Lejárat`,"accounts.col.label":`Címke`,"accounts.col.service":`Szolgáltatás`,"accounts.col.status":`Állapot`,"accounts.col.tier":`Csomag`,"accounts.col.traffic":`Hátralévő forgalom`,"accounts.tier.premium":`Prémium`,"accounts.tier.free":`Ingyenes`,"accounts.trafficLeftOf":`{total} keretből {left} maradt`,"accounts.trafficLeftPercent":`{n}% maradt`,"accounts.trafficUsedTotal":`{used} letöltve`,"accounts.trafficUnknown":`Ez a szolgáltatás nem közöl keretet.`,"accounts.credentialFromEnv":`A konténer {env} környezeti változója állítja be. Ott távolítsd el, hogy ezt megváltoztasd.`,"accounts.debrid.empty":`Még nincs debrid fiók`,"accounts.debrid.emptyHint":`Adj hozzá egy fiókot valamelyik támogatott debrid szolgáltatásnál, hogy a tárhelyek linkjei automatikusan feloldódjanak.`,"accounts.debrid.title":`Debrid-fiókok`,"accounts.debrid.viaJD":`JDownloaderen keresztül`,"accounts.debrid.hint":`A debrid szolgáltatás egyetlen fizetős fiók, amely egyszerre sok fájltárhelyet old fel. A KnightLoader elküldi neki a linket, és letölti a visszakapott közvetlen linket, teljes sebességgel, várakozás és captcha nélkül. Ez az ajánlott út, mert a másik lehetőség minden egyes tárhelyen külön prémium fiók. Néhány szolgáltatás csak a beépített JDownloaderen keresztül érhető el, ilyenkor az végzi a bejelentkezést. Ezt a soruk jelzi.`,"accounts.edit":`Hitelesítő adat szerkesztése`,"accounts.editCredentialTitle":`A(z) {service} hitelesítő adatának szerkesztése`,"accounts.enableAccount":`{account} engedélyezése`,"accounts.hoster.empty":`Még nincs tárhelyfiók`,"accounts.hoster.title":`Tárhelyfiókok`,"accounts.hoster.hint":`A saját prémium fiókod egyetlen tárhelynél. A belépési adatokat a beépített JDownloader kapja meg, és ő jelentkezik be. Olyan tárhelyhez használd, amit egyik debrid szolgáltatásod sem fed le. Kapcsolj ki egy sort, és a belépés mentve marad, de nem lesz használva.`,"accounts.newAccount":`Fiók hozzáadása`,"accounts.addAccountTitle":`Saját {service}-fiók hozzáadása`,"accounts.noServicesFound":`Egyetlen szolgáltatás sem felel meg a keresésnek.`,"accounts.passwordField":`Jelszó`,"accounts.pickDebridAccount":`Debrid fiók választása`,"accounts.refresh":`Frissítés`,"accounts.refreshing":`Frissítés…`,"accounts.remove":`Eltávolítás`,"accounts.removeConfirm":`A(z) {name} mentett bejelentkezési adatai törlődnek erről a példányról, és nem állíthatók vissza, ezért újra meg kellene adni őket.`,"accounts.removed":`Eltávolítva.`,"accounts.rename":`Átnevezés`,"accounts.renew":`Megújítás`,"accounts.rowActions":`Fiókműveletek`,"accounts.save":`Mentés`,"accounts.saveAnyway":`Mentés mindenképp`,"accounts.saving":`Mentés…`,"accounts.usernameField":`Felhasználónév`,"accounts.field.email":`E-mail-cím`,"accounts.field.customerId":`Ügyfélazonosító`,"accounts.field.apiKey":`API-kulcs`,"accounts.field.apiUser":`API-felhasználónév`,"accounts.verifyFailed":`Nem sikerült ellenőrizni: {detail}`,"accounts.verifying":`Ellenőrzés…`,"accounts.whereToFind":`Honnan szerezhetem be?`,"accounts.hostsRefreshed":`Hosterlista frissítve: {when}`,"accounts.routing.priorityTitle":`Prioritási sorrend`,"accounts.routing.orderHint":`Which backend is asked first when more than one can fetch the same link. Drag a row to move it.

The order only decides between backends that can take the link at all. A filehoster link never goes to Direct download or the plain HTTP fallback, wherever they stand, since either would only save the hoster’s page.`,"accounts.routing.priorityEmpty":`No backends are registered yet.`,"accounts.routing.moveUp":`Mozgatás felfelé`,"accounts.routing.moveDown":`Mozgatás lefelé`,"accounts.routing.priorityAuto":`Automatikus`,"accounts.routing.priorityAutoHint":`Eldobja a sorrendedet, és visszaáll az automatikusra. Az automatikus sorrend követi a változásokat, például egy új debrid kulcsot vagy egy prémiumra váltó fiókot, a tiéd viszont pontosan úgy marad, ahogy hagytad.`,"accounts.routing.dragHandle":`{name} áthelyezése`,"accounts.routing.jdHint":`The embedded, invisible JDownloader that opens encrypted containers and covers hosters no other backend does.`,"accounts.routing.jdNotConfigured":`Nincs beállítva`,"accounts.routing.jdReachable":`Elérhető, {version} revízió`,"accounts.routing.jdUnreachable":`Nem elérhető`,"resolver.direct":`Közvetlen letöltés`,"resolver.http":`Egyszerű HTTP tartalék`,"resolver.torrent":`Built-in torrent client`,"accounts.routing.tip.jd":`Fetches filehoster links without an account, with the wait and the captcha, and takes any link no other backend can open.`,"accounts.routing.tip.ytdlp":`Videót és hangot tölt le olyan oldalakról, mint a YouTube, a választott minőségben.`,"accounts.routing.tip.direct":`Letölt egy linket, amely közvetlenül egy fájlra mutat. Fájltárhely-linkek soha nem kerülnek ide, és videooldalak sem, amíg a yt-dlp fut, bárhová is teszed ezt a sort.`,"accounts.routing.tip.login":`A saját fiókod ennél a tárhelynél. A JDownloader ezzel jelentkezik be.`,"accounts.hoster.col.host":`Hoster`,"accounts.hoster.col.username":`Felhasználónév`,"accounts.hoster.status.active":`Aktív`,"accounts.hoster.detail.adding":`Arra vár, hogy a JDownloader elfogadja ezt a bejelentkezést.`,"accounts.hoster.detail.checking":`A JDownloader még ellenőrzi ezt a bejelentkezést.`,"accounts.hoster.detail.invalid":`A JDownloader nem tudta megerősíteni ezt a bejelentkezést. Ellenőrizd a felhasználónevet és a jelszót.`,"accounts.hoster.detail.off":`Kikapcsolva, így a JDownloader nem használja ezt a bejelentkezést.`,"accounts.hoster.detail.waiting":`A következő ellenőrzésre vár.`,"accounts.hoster.enableLogin":`A(z) {host} bejelentkezés használata`,"accounts.hoster.status.off":`Ki`,"accounts.hoster.status.queued":`Sorban`,"accounts.hoster.status.rejected":`Elutasítva`,"accounts.hoster.removed":`Eltávolítva.`,"accounts.hoster.pickAccount":`Tárhelyfiók választása`,"accounts.hoster.searchHosts":`Hosterek keresése…`,"accounts.hoster.passwordCustody":`A jelszó a JDownloader háttérhez kerül, amely tárolja, és elvégzi a tényleges bejelentkezést. Maga a KnightLoader nem őrzi meg.`,"captcha.title":`Captcha szükséges`,"captcha.titleMore":`Captcha szükséges (még {n} vár)`,"captcha.forHost":`A(z) {host} captchát kér, mielőtt ez a letöltés folytatódhatna.`,"captcha.answerLabel":`Válasz`,"captcha.answerPlaceholder":`Írd be, amit látsz…`,"captcha.clickHint":`Kattints minden pontra, amit a kép kér, majd nyomd meg a Folytatás gombot.`,"captcha.clickCount":`Megjelölt pontok: {n}`,"captcha.clickClear":`Pontok törlése`,"captcha.widgetHint":`Oldd meg az alábbi feladványt. Ha megvan, magától folytatódik.`,"captcha.widgetScoreHint":`Semmire nem kell kattintanod. A captcha-szolgáltatás ellenőrzi ezt a böngészőt, és magától átadja a válaszát.`,"captcha.widgetUnavailable":`Ezt a kihívást nem sikerült betölteni.`,"captcha.widgetUnreachable":`A böngésződ nem érte el a captcha-szolgáltatást. Lehet, hogy egy reklámblokkoló vagy egy hálózati szűrő blokkolja. A Frissítés újra megpróbálja.`,"captcha.widgetRefused":`A captcha-szolgáltatás itt megtagadta a futást, és ezt jelentette: {code}. Sok tárhely a saját weboldalához köti a captcháját, így lehet, hogy a KnightLoaderben egyáltalán nem töltődik be. A Frissítés újra megpróbálja, a Mégse pedig kihagyja ezt a captchát.`,"captcha.unsupported":`A KnightLoader nem tudja megjeleníteni ezt a fajta kihívást ({vendor} néven jelentve).`,"captcha.unsolvable":`A KnightLoader nem tudja megoldani ezt a captchát.`,"captcha.unsolvableVendor":`A JDownloader nem árulta el, melyik captcha-szolgáltatásról van szó, a KnightLoader pedig nem találgat. A Mégse kihagyja ezt a captchát.`,"captcha.unsolvableAction":`Ez egy reCAPTCHA v3 ellenőrzés, és a JDownloader nem adta tovább a műveletet, amelyet a tárhely kér. Nélküle a választ elutasítanák. A Mégse kihagyja ezt a captchát.`,"captcha.unsupportedHint":`Használd a Mégse gombot alább, vagy tiltsd le ennek a hosternek a captcháit erre a munkamenetre.`,"captcha.continue":`Folytatás`,"captcha.cancel":`Mégse`,"captcha.refresh":`Frissítés`,"captcha.moreOptions":`További lehetőségek`,"captcha.blockHoster":`Ebben a munkamenetben {host} esetén se kérdezz többé`,"captcha.blockEverywhere":`Ebben a munkamenetben egyik hoster esetén se kérdezz többé`,"captcha.tooLate":`Ez a válasz túl későn érkezett.`,"captcha.networkError":`Nem sikerült elérni a szervert. Próbáld újra.`,"captcha.timedOut":`A(z) {host} captchája lejárt.`,"captcha.resolvedElsewhere":`A(z) {host} captcháját máshol oldották meg.`,"settings.captcha.title":`Captcha`,"settings.captcha.orderTitle":`Megfejtők sorrendje`,"settings.captcha.orderHint":`Minden alább engedélyezett megfejtőt a mutatott sorrendben próbál ki a rendszer, felülről lefelé. Ha egy sincs engedélyezve, vagy mind hibázik vagy elutasítja, közvetlenül téged kérdez meg.`,"settings.captcha.orderEmpty":`Egyetlen megoldó sincs bekapcsolva, így minden captcha egyenesen hozzád kerül.`,"settings.captcha.enableSolver":`{service} automatikus kipróbálása`,"settings.captcha.moveUp":`Fel`,"settings.captcha.moveDown":`Le`,"settings.captcha.set":`Kulcs beállítva`,"settings.captcha.notSet":`Nincs beállítva kulcs`,"settings.captcha.setKey":`Kulcs beállítása`,"settings.captcha.change":`Módosítás`,"settings.captcha.remove":`Eltávolítás`,"settings.captcha.cancel":`Mégse`,"settings.captcha.save":`Mentés`,"settings.captcha.saving":`Mentés…`,"settings.captcha.placeholder":`Illeszd be az API-kulcsot`,"settings.captcha.saved":`Az API-kulcs mentve.`,"settings.captcha.removed":`Az API-kulcs eltávolítva.`,"settings.captcha.saveFailed":`A kulcsot nem sikerült menteni: {error}`,"collector.options":`Lehetőségek`,"collector.destination":`Célmappa`,"collector.destinationRecent":`Nemrég használt`,"collector.archivePasswordHint":`A Beállításokban mentett lista előtt próbálja ki, ha a tétel egyik archívuma titkosított.`,"collector.linkPassword":`Hivatkozás jelszava`,"collector.linkPasswordHint":`Az a jelszó, amelyet maga a tárhely oldala kér, mielőtt kiadja a fájlt. A fenti archívumjelszó egy másik.`,"collector.overrule":`Illeszkedő Packagizer-szabály felülbírálása`,"collector.overruleHint":`Kikapcsolva egy illeszkedő Packagizer-szabály nyer a fenti prioritással, kibontással és megjegyzéssel szemben. Bekapcsolva helyette ezek az értékek nyernek. A célmappa ebben soha nem játszik szerepet: mindig úgy érvényes, ahogy beírtad.`,"collector.facets.title":`Szűrők`,"collector.facets.hint":`Szűkíti az összegyűjtött listát aszerint, hova mutat a hivatkozás, milyen típusú fájl, vagy melyik csomagba került.`,"collector.facets.fileType":`Fájltípus`,"collector.facets.clearAll":`Törlés`,"collector.facets.unknownHost":`Ismeretlen tárhely`,"collector.facets.type.archive":`Archívumok`,"collector.facets.type.video":`Videó`,"collector.facets.type.audio":`Hang`,"collector.facets.type.image":`Képek`,"collector.facets.type.document":`Dokumentumok`,"collector.facets.type.other":`Egyéb`,"collector.stats.label":`Gyűjtő összesítése`,"collector.stats.packages":`Csomagok`,"collector.stats.links":`Hivatkozások`,"collector.stats.totalSize":`Teljes méret`,"collector.stats.hosts":`Tárhelyek`,"settings.preParser":`Beillesztett vagy ráejtett szöveg átvizsgálása hivatkozásokért`,"settings.preParserHint":`Bárhol megtalálja a linkeket abban, amit beillesztesz vagy ráhúzol, nem csak soronként egy tiszta URL-t. Újra összefűzi a linket, amelyet egy levelezőprogram sortöréssel kettévágott, és a http:// nélküli csupasz hosztnevet útvonallal együtt is linknek olvassa. Kikapcsolva minden sort pontosan úgy vesz, ahogy beírták, ahogy eddig is mindig működött.`,"intake.pasteButton":`Beillesztés a vágólapról`,"intake.clipboardWatch":`Vágólap figyelése`,"intake.clipboardWatchHint":`Minden link, amit bárhol kimásolsz, egyenesen a gyűjtőbe kerül, amíg ez a lap nyitva van és előtérben. A Ctrl+V a KnightLoaderen belül mindig működik, és ehhez nincs szüksége semmire.`,"intake.clipboardWatchUnavailable":`Itt nem érhető el: a böngésző csak HTTPS-en vagy localhoston engedi egy oldalnak a vágólap olvasását. A Ctrl+V a KnightLoaderen belül így is működik.`,"intake.clipboardWatchDenied":`A vágólap figyelése kikapcsolva: {reason}`,"collector.hosterPresetHint":`A(z) {host} linkjeinek mely változatait mutatja a gyűjtő, és milyen formátummal és minőséggel indulnak az új linkek. Ha egy link ellenőrizve van, átvált a saját sávjára, amelyik a legközelebb áll ehhez. Az a link, amelynek nincs ilyen videoformátuma, a legjobb videóját kapja eddig a minőségig, amelyiknek pedig nincs ilyen hangformátuma, annak a hangját átalakítjuk.`,"activity.crawl":`Oldalak átvizsgálása`,"activity.linkcheck":`Hivatkozások ellenőrzése`,"activity.captcha":`Captcha`,"activity.autoconfirm":`Automatikus megerősítés`,"activity.container":`Konténerek`,"activity.pending":`{n} vár`,"activity.ofTotal":`{total} közül {n}`,"activity.tooltipHint":`Ebben a menetben {total} közül {active} aktív`,"activity.stop":`Futás leállítása`,"activity.autoconfirmStop":`Visszaszámlálás leállítása`,"activity.autoconfirmCountdown":`Ezek a linkek a letöltési listára kerülnek, amikor lejár a visszaszámlálás. Ha leállítod, a gyűjtőben maradnak.`,"notifications.quiet":`Csendes mód`,"notifications.quietHint":`Elrejti a sikeres és tájékoztató értesítéseket. Egy hiba, egy Önre váró captcha vagy egy felfüggesztett fiók továbbra is megjelenik.`,"task.tooltip.url":`URL`,"task.tooltip.changed":`Utoljára módosítva`,"task.tooltip.infoHash":`Hash`,"task.tooltip.trackers":`Trackerek`,"task.tooltip.swarm":`Peerek / seedek / arány`,"task.tooltip.swarmDetail":`{peers} peer, {seeds} seed, arány {ratio}`,"task.tooltip.uploaded":`Feltöltve`,"task.tooltip.seeding":`Még mindig seedel`,"columns.peers":`Peerek`,"columns.seeds":`Seedek`,"columns.ratio":`Arány`,"columns.variant":`Változat`,"columns.variant.video":`Videó`,"columns.variant.audio":`Hang`,"columns.variant.thumbnail":`Bélyegkép`,"columns.variant.subtitle":`Feliratok`,"columns.variant.description":`Leírás`,"columns.variant.auto":`Automatikus`,"columns.variant.kbps":`{kbps} kbit/s`,"file.open":`Megnyitás`,"file.openNatively":`Megnyitás az alapértelmezett alkalmazással`,"file.revealInFolder":`Megjelenítés a mappában`,"file.desktopOnly":`Csak asztali alkalmazásban`,"settings.schedule.subtitle":`A letöltési sebesség szüneteltetése, folytatása vagy korlátozása időzítés szerint.`,"settings.schedule.statusTitle":`Időzítések állapota`,"settings.schedule.orderHint":`Az időzítések sorrendben, fentről lefelé érvényesülnek, és ahol kettő átfedi egymást, az alsó nyer. Egy tág „szüneteltetés minden éjjel” egy szűk kivétel fölött tehát érvényben hagyja a kivételt, ugyanez a kettő fordítva viszont nem.`,"settings.schedule.add":`Időzítés létrehozása`,"settings.schedule.empty":`Még nincs időzítés`,"settings.schedule.emptyHint":`Semmi sem szünetelteti vagy korlátozza a sort az óra szerint. Hozz létre egy időzítést, ha éjszakára vissza szeretnéd tartani a letöltéseket, vagy korlátoznád a sebességet, amíg te magad használod a kapcsolatot.`,"settings.schedule.use":`Ezen időzítés használata`,"settings.schedule.moveUp":`Feljebb`,"settings.schedule.moveDown":`Lejjebb`,"settings.schedule.remove":`Ezen időzítés eltávolítása`,"settings.schedule.edit":`Ezen időzítés szerkesztése`,"settings.schedule.name":`Név`,"settings.schedule.namePlaceholder":`pl. Éjszakai szünet`,"settings.schedule.days":`Napok`,"settings.schedule.daysHint":`A hét napjai, amelyeken ez az időzítés kezdődik. Éjfélen átnyúló időzítésnél azt a napot jelöld be, amikor kezdődik: a „P 22:00-06:00” szombat reggel ér véget anélkül, hogy a szombat be lenne jelölve.`,"settings.schedule.preset.every":`Minden nap`,"settings.schedule.preset.weekdays":`Hétköznapok`,"settings.schedule.preset.weekends":`Hétvégék`,"settings.schedule.preset.custom":`Egyéni`,"settings.schedule.start":`Kezdés`,"settings.schedule.end":`Vége`,"settings.schedule.endHint":`Ha a befejezés a kezdés előtt van, az időzítés átnyúlik éjfélen, és másnap reggel ér véget. A kezdéssel megegyező befejezési időt nem fogadjuk el, mert jelenthetne egy egész napot vagy egyáltalán semmi időt.`,"settings.schedule.action":`Művelet`,"settings.schedule.action.pause":`Szüneteltetés`,"settings.schedule.action.resume":`Folytatás`,"settings.schedule.action.limit":`Sebesség korlátozása`,"settings.schedule.limit":`Sebességkorlát`,"settings.schedule.disabledOff":`Ez az időzítés ki van kapcsolva, és soha nem lép működésbe. A sor úgy viselkedik, mintha nem is létezne.`,"settings.schedule.activeNow":`Most aktív, eddig: {time}`,"settings.schedule.next":`Következő: {when}`,"settings.schedule.never":`A jelenlegi beállítás szerint soha nem lép működésbe`,"settings.schedule.stateNow.paused":`Egy időzítés éppen szünetelteti a sort.`,"settings.schedule.stateNow.limited":`Egy időzítés éppen {rate} értékre korlátozza a sort.`,"settings.schedule.stateNow.running":`Jelenleg egyetlen időzítés sincs érvényben.`,"settings.schedule.nextChange":`Következő változás: {when}`,"settings.schedule.noNextChange":`Ahogy most be vannak állítva, egyik időzítés sem fogja soha megváltoztatni a sort.`,"settings.schedule.stateNow.suspendedUntil":`Az időzítések felfüggesztése eddig tart: {when}.`,"settings.schedule.stateNow.suspendedOpen":`Az időzítések fel vannak függesztve, amíg vissza nem kapcsolod őket.`,"settings.schedule.suspend":`Időzítések felfüggesztése`,"settings.schedule.suspendHint":`Egy időre félreteszi az összes időzítést, anélkül hogy bármelyiket megváltoztatná. Közben a sor a saját beállításaid szerint fut, és ha lejár az idő, az időzítések maguktól újra érvényesek. Egy újraindítás nem vet véget a felfüggesztésnek.`,"settings.schedule.suspend.off":`Nincs felfüggesztve`,"settings.schedule.suspend.hour":`Egy órára`,"settings.schedule.suspend.threeHours":`Három órára`,"settings.schedule.suspend.midnight":`Éjfélig`,"settings.schedule.suspend.open":`Amíg vissza nem kapcsolod őket`,"settings.schedule.suspend.until":`Eddig: {when}`,"settings.schedule.suspendNone":`Még nincs beállítva időzítés, így nincs mit felfüggeszteni.`,"settings.schedule.suspendParked":`A lenti „Időzítések” kapcsoló ki van kapcsolva, így nincs mit felfüggeszteni.`,"settings.schedule.saveFailed":`Az időzítéseket nem sikerült menteni: {error}`,"settings.schedule.rowError":`{row}. sor: {error}`,"idleAction.title":`A sor üresjáratban van`,"idleAction.action.pause":`Szüneteltetés folyamatban`,"idleAction.actionFallback":`„{action}” folyamatban`,"idleAction.in":`{countdown} múlva`,"idleAction.cancel":`Mégse`,"idleAction.cancelling":`Megszakítás…`,"idleAction.cancelFailed":`Nem sikerült megszakítani: a kiszolgáló nem válaszolt.`,"settings.nav.diagnostics":`Diagnosztika`,"settings.diagnostics.subtitle":`Mi ez a build, min fut, és mit naplózott legutóbb, hogy hibajelentéshez csatolhasd.`,"settings.diagnostics.version":`Verzió`,"settings.diagnostics.deployment":`Build`,"settings.diagnostics.deployment.container":`Konténer`,"settings.diagnostics.deployment.desktop":`Asztali`,"settings.diagnostics.goVersion":`Go`,"settings.diagnostics.platform":`Platform`,"settings.diagnostics.goroutines":`Goroutine-ok`,"settings.diagnostics.download":`Diagnosztikai csomag letöltése`,"settings.diagnostics.downloading":`Előkészítés…`,"settings.diagnostics.downloadHint":`Egy JSON-fájl a fenti mezőkkel, az Ön beállításaival minden jelszó eltávolítva, és az alábbi naplósorokkal.`,"settings.diagnostics.downloadFailed":`Nem sikerült létrehozni a csomagot: {error}`,"settings.diagnostics.logTitle":`Legutóbbi naplósorok`,"settings.diagnostics.logHint":`Az ezen folyamat által naplózott utolsó {n} sor, a legrégebbi elöl. Itt semmi sem kerül lemezre írásra.`,"settings.diagnostics.logEmpty":`Még nincs semmi naplózva.`,"settings.diagnostics.refresh":`Frissítés`,"settings.diagnostics.loadFailed":`Nem sikerült betölteni a diagnosztikát. Elérhető a kiszolgáló?`,"settings.nav.help":`Súgó`,"settings.help.intake.title":`Letöltések hozzáadása`,"settings.help.intake.body":`Illeszd be a linkeket a gyűjtőbe, soronként egyet vagy rendezetlen szövegként. A keresés bárhol megtalálja a linkeket: egy mondat közepén, soronként többet is, vagy ha egy levelezőprogram két sorba tördelte őket.`,"settings.help.intake.b1":`Húzzon be egy hivatkozás-konténer fájlt (.dlc, .ccf, .rsdf) vagy egy egyszerű hivatkozáslistát.`,"settings.help.intake.b2":`A tárhely- és fórumoldalak Click'n'Load gombjai változatlanul működnek. A KnightLoader a 127.0.0.1:9666 címen válaszol, ugyanazon a porton, amelyet minden más letöltéskezelő is használ.`,"settings.help.intake.b3":`Illesszen be egy oldal URL-t egy fájlhivatkozás helyett, és kapcsolja be a Bejárást, hogy minden hivatkozott fájlt kinyerjen, ahelyett hogy magát az oldalt töltené le.`,"settings.help.intake.link1":`Linkgyűjtő beállításainak megnyitása`,"settings.help.collector.title":`A gyűjtő, mielőtt bármi is letöltődne`,"settings.help.collector.body":`Az új hivatkozások először a Gyűjtőbe érkeznek, nem a sorba: egy átmeneti terület a nevek, méretek és duplikátum-figyelmeztetések ellenőrzésére, mielőtt bármi elindulna. Az automatikus megerősítés kihagyhatja ezt a lépést, opcionális késleltetéssel; megerősítés után egy hivatkozás vagy azonnal elindul, vagy a sorban vár, az automatikus indítástól függően.`,"settings.help.collector.link":`Linkgyűjtő beállításainak megnyitása`,"settings.help.rules.title":`Szabályok: csomagok, mappák és ami megmarad`,"settings.help.rules.body":`A Packagizer érkezéskor átnevezi a linket, kiválasztja a mappáját és beállítja a letöltési beállításait, az általad írt feltételek alapján. A Hivatkozásszűrő dönti el, hogy egy link egyáltalán megmarad-e. Az elutasítás mindig megnevezi az okozó szabályt és az okát.`,"settings.help.rules.link":`Szabályok megnyitása`,"settings.help.queue.title":`A sor kezelése`,"settings.help.queue.body":`Bármelyik linket szüneteltetheted, folytathatod vagy átrendezheted, egyenként vagy egész csomagként. A sort kétféleképpen lehet leállítani. A megállítás érintetlenül hagyja azt, ami már fut, így az magától befejeződik. Az összes átvitel azonnali leállítása előbb megmutatja, mi veszne el, és csak a megerősítésed után lép. A figyelmeztetés azoknak az átviteleknek szól, amelyek nem tudják ott folytatni, ahol abbahagyták.`,"settings.help.queue.b1":`Egyetlen hivatkozás felülbírálhatja a globális kapcsolatszámot vagy a letöltés utáni kicsomagolás kapcsolóját.`,"settings.help.queue.b2":`Egy már a listán szereplő hivatkozás duplikátuma mindig elutasításra kerül, mielőtt egyáltalán elérné a gyűjtőt.`,"settings.help.limits.title":`A hoszterkorlátok megkerülése`,"settings.help.limits.body":`Három független módszer, hogy egy ingyenes korlát ne legyen a plafon:`,"settings.help.limits.b1":`Kapcsolatok: oszd el a letöltéseket több kimenő útvonal között (egy második vonal, egy proxy, SOCKS), ahelyett hogy mindig a gép saját címén menjenek ki.`,"settings.help.limits.b2":`Újracsatlakozás: kérj új nyilvános címet a routertől; csak ez oldja fel a magához a címhez kötött korlátot. Működik UPnP-vel, külső programmal, szkripttel, vagy HTTP-kérések visszajátszásával a router adminoldalán. A meglévő JDownloader LiveHeader/curl szkriptek változatlanul működnek.`,"settings.help.limits.b3":`Fiókok: tárold a prémium vagy debrid belépési adataidat (Real-Debrid, AllDebrid, TorBox és mások), hogy a jogosult link teljes sebességgel töltődjön le az ingyenes korlát helyett.`,"settings.help.limits.link1":`Hálózat megnyitása`,"settings.help.limits.link3":`Fiókok megnyitása`,"settings.help.captcha.title":`Captcha`,"settings.help.captcha.body":`Amikor egy tárhely captchát kér, előbb az általad beállított automatikus megoldókat próbáljuk, az általad megadott sorrendben. Ha egy sincs beállítva, vagy egyik sem tudja megoldani, a captcha eléd kerül, ahelyett hogy csendben meghiúsulna.`,"settings.help.captcha.link":`Captcha beállításainak megnyitása`,"settings.help.after.title":`Letöltés után`,"settings.help.after.body":`Az archívumokat automatikusan kibontjuk: zip (titkosítva is, WinZip AES és a régi ZipCrypto egyaránt), rar többkötetes készletekkel, 7z, tar, valamint gzip/bzip2/xz/zstd, akár tar van bennük, akár nem. A kibontás tiszta Go, nem kell hozzá külső unrar vagy 7z program. Titkosított archívumnál egy jelszólistát próbálunk végig sorban. A kész fájlt összevetjük a vele érkezett ellenőrzőösszeggel, legyen az .sfv lista, md5/sha1/sha256sum fájl, vagy a kiadás nevében szereplő CRC32.`,"settings.help.after.link1":`Archívumok beállításainak megnyitása`,"settings.help.after.link2":`Letöltések beállításainak megnyitása`,"settings.help.schedule.title":`Felügyelet nélküli működés`,"settings.help.schedule.body":`Egy heti időbeosztás az óra szerint szünetelteti vagy lassítja a sort, például egy éjszakai idősávban, és az óraátállításkor is helyes marad. Ugyanaz az elgondolás, mint a JDownloader Schedulere.`,"settings.help.schedule.link":`Automatizálás megnyitása`,"settings.help.instances.title":`Több példány futtatása`,"settings.help.instances.body":`Adj hozzá egy másik KnightLoadert társként, és a sora ezen a vezérlőpulton is megjelenik. Ugyanazon a hálózaton ez közvetlen hívás a másik példány saját API-jára, ahogy egy böngésző is tenné. Hálózatok között tizenkét szó párosítja a kettőt egy relén keresztül, amelyet magad is üzemeltethetsz.`,"settings.help.instances.link":`Példányok megnyitása`,"settings.help.access.title":`Hozzáférés és hibaelhárítás`,"settings.help.access.body":`Egy jelszó az egész felületet lezárja, és onnantól csak munkamenet-sütivel lehet belépni. A Távoli elérés oldal azt is felsorolja, milyen fogadóportjai és hozzáférési módjai vannak ennek a buildnek, és miért létezik mindegyik, így bármelyik váratlanul nyitott portnak utánanézhetsz. A Diagnosztika oldal egy hibajelentéshez csatolható fájlt készít: verzió- és buildadatok, a jelenlegi beállítások minden jelszó nélkül, ennek a folyamatnak a saját legutóbbi naplósorai, és hogy hány goroutine fut.`,"settings.help.access.link1":`Távoli elérés megnyitása`,"settings.help.access.link2":`Diagnosztika megnyitása`,"settings.help.advanced.title":`Minden más`,"settings.help.advanced.body":`Ennek a buildnek minden beállítása kiolvasható és módosítható a nyers nevén a Haladó oldalon. Olyanok is, amelyeknek máshol még nincs saját kezelőeleme, például hogy mi legyen egy már letöltött fájl tükrével, és mi történjen, ha egy letöltés már foglalt névre kerülne.`,"settings.help.advanced.link":`Haladó beállítások megnyitása`,"task.mode.free":`Ingyenes`,"task.mode.premium":`Prémium`,"settings.about.title":`A KnightLoaderről`,"settings.about.body":`Egy lovag, egy hadjárat: igényes nyílt forráskódú eszközök, amelyek abban a formában, ahogy én akartam, nem léteztek, addig építve, amíg semmi nem hiányzik. Minden ingyenes, fiókok, telemetria, hirdetések és fizetős szintek nélkül. Sehol egyetlen csillag sem. Semmi olvasható nem hagyja el a saját falaidat. Esténként és hétvégenként kovácsolva, szívvel és makacssággal.`,"settings.about.coffeeButton":`Hívj meg egy kávéra`,"settings.about.crypto":`Kripto`,"settings.about.paypal":`PayPal`,"settings.about.cryptoTitle":`Támogatás kriptóval`,"settings.about.donateAppeal":`Dobj egy érmét a lovagodnak: fedezi a költségek egy részét, és életben tartja a projektet. Minden, amit készítek, ingyenes és reklámmentes.`,"settings.about.cryptoIntro":`Válassz pénznemet és hálózatot, majd olvasd be a kódot vagy másold ki a címet.`,"settings.about.cryptoNetworks":`Hálózatok`,"settings.about.cryptoNoTag":`Nem kell sem destination tag, sem memo.`,"settings.about.coffeeIntro":`A fizetés a Buy Me a Coffee-n keresztül történik. Nincs szükséged fiókra.`,"settings.about.paypalIntro":`A fizetés a PayPalon keresztül történik, a PayPal-fiókoddal vagy fiók nélkül, kártyával.`,"settings.about.paypalFrequency":`Milyen gyakran`,"settings.about.paypalOnce":`Egyszeri`,"settings.about.paypalMonthly":`Havonta`,"settings.about.paypalYearly":`Évente`,"settings.about.paypalAmount":`Összeg`,"settings.about.paypalOtherAmount":`Más összeg`,"settings.about.paypalLoading":`PayPal betöltése…`,"settings.about.paypalThanks":`Köszönöm, az adományod megérkezett.`,"settings.about.paypalFailed":`A PayPal most nem érhető el. Próbáld újra később, vagy válassz másik módot.`,"common.copy":`Másolás`,"common.copied":`Másolva`,"settings.about.coffee":`Ha a KnightLoader kiérdemelte a helyét a szervereden vagy a gépeden, dobj egy érmét a lovagodnak: segít fedezni a költségeket, és életben tartja a projektet. És ettől ennek a lovagnak a szíve kicsit gyorsabban ver. Lent három út van, válaszd, amelyik kézre esik.`,"settings.about.report":`Probléma, kívánság vagy javaslat? Nyiss egy hibajegyet a GitHubon, vagy írj egy e-mailt.`,"settings.about.version":`Verzió`,"settings.about.github":`GitHub`,"settings.about.mail":`E-mail`,"settings.about.mailSubject":`Visszajelzés`,"settings.scripts.add":`Szkript hozzáadása`,"settings.scripts.empty":`Még nincsenek szkriptek`,"settings.scripts.emptyHint":`Egy szkript a saját JavaScriptedet futtatja, amikor valami történik, például befejeződik egy letöltés, meghiúsul egy letöltés vagy a sor tétlenné válik. Kérésre is futtathatod, itt a „Tesztfuttatás” gombbal vagy a letöltési lista jobbklikkes menüjének „Szkript futtatása” elemével. Adj hozzá egyet a kezdéshez.`,"settings.scripts.loadFailed":`A szkripteket nem sikerült betölteni. Ha ez a build még nem tartalmazza az automatizálási motort, ezen az oldalon nincs mit mutatni. Próbáld újra, ha már tartalmazza.`,"settings.scripts.name":`Név`,"settings.scripts.namePlaceholder":`pl. Értesítés hiba esetén`,"settings.scripts.unnamed":`Névtelen szkript {n}`,"settings.scripts.trigger":`Fut, amikor`,"settings.scripts.triggerHint":`Mi indítja ezt a szkriptet. Kézi beállítással csak akkor fut, ha kéred: a lenti „Tesztfuttatás” gombbal vagy a letöltési lista jobbklikkes menüjének „Szkript futtatása” elemével.`,"settings.scripts.trigger.manual":`Kézi (csak igény szerint)`,"settings.scripts.trigger.taskDone":`Egy letöltés befejeződik`,"settings.scripts.trigger.taskFailed":`Egy letöltés meghiúsul`,"settings.scripts.trigger.queueIdle":`A sor tétlenné válik`,"settings.scripts.use":`Szkript engedélyezése`,"settings.scripts.code":`Kód`,"settings.scripts.starter":`// Ez a szkript a fent kiválasztott eseménynél fut.
// A log(...) egy sort ír a Kimenetbe, a notify(message) értesítést küld.
// A trigger és a queue mindig elérhető; a task, pkg, extraction, reconnect,
// account és captcha csak akkor, ha az esemény hoz ilyet.
`,"settings.scripts.timeout":`Időkorlát`,"settings.scripts.timeoutHint":`Meddig futhat ez a szkript leállítás előtt. 100 ms és 30 s között; a 0 az alapértelmezett 5000 ms-ot használja.`,"settings.scripts.timeoutUnit":`ms`,"settings.scripts.saveFailed":`Nem sikerült menteni: {error}`,"settings.scripts.remove":`Eltávolítás`,"settings.scripts.removeNew":`Mégse`,"settings.scripts.removeFailed":`Nem sikerült eltávolítani: {error}`,"settings.scripts.unsaved":`Mentetlen`,"settings.scripts.run":`Tesztfuttatás`,"settings.scripts.running":`Fut…`,"settings.scripts.runNeedsSaveHint":`Adj neki nevet vagy egy kis kódot a létrehozáshoz, majd teszteld itt.`,"settings.scripts.runDirtyHint":`A módosításaid még mentés alatt vannak. A tesztfuttatás mindjárt ezeket használja.`,"settings.scripts.ranIn":`Sikeresen lefutott, {duration} alatt`,"settings.scripts.runTimedOut":`Leállítva: tovább futott, mint az időkorlátja`,"settings.scripts.runFailed":`Sikertelen: {error}`,"settings.scripts.output":`Kimenet`,"task.runScript":`Szkript futtatása`,"task.runScriptUnnamed":`Névtelen szkript`,"task.runScriptDone":`„{name}” lefutott`,"task.runScriptFailed":`„{name}” sikertelen: {error}`,"settings.access.relay.title":`A projekt továbbítója`,"settings.access.relay.body":`A relay egy közvetítő, amivel minden példányod elérhető az otthoni hálózaton kívülről is, tehát bárhonnan. Ezt a projekt ingyen biztosítja.`,"settings.access.relay.use":`A projekt továbbítójának használata`,"settings.access.relay.leadProject":`Beállítás nélkül működik. Minden, amit a példányaid egymásnak mondanak, titkosított, és a kulcs csak nálad van.`,"settings.access.relay.seesButton":`Mit lát?`,"settings.access.relay.seesTip":`A relé nem látja: a linkjeidet, a letöltéseidet, a fájljaidat és a hozzáférési tokenedet.

A relé látja: a példányaid IP-címeit és azt, mikor küldenek valamit.

Ezt nem lehet elrejteni titkosítással. Ha zavar, üzemeltess saját relét.`,"settings.access.relay.seesAddress":`A projekt továbbítója itt fut: {address}.`,"settings.access.relay.none":`Nincs továbbító`,"settings.access.relay.noneHint":`Nincs aktív relay. Ugyanazon a hálózaton, tehát otthon, a példányok továbbra is maguktól megtalálják egymást. Különböző hálózatok között nem érik el egymást, így nincs távoli elérés.`,"settings.access.relay.own":`Saját továbbító`,"settings.access.relay.project":`A projekt továbbítója`,"settings.access.relay.whichHint":`A {address} címen megy`,"settings.access.relay.savedProject":`A projekt továbbítója aktív`,"settings.access.relay.savedOwn":`A saját továbbítód aktív`,"settings.access.relay.savedOff":`Továbbító kikapcsolva`,"settings.access.ownRelay.title":`Saját továbbító`,"settings.access.ownRelay.body":`Üzemeltess saját relayt a projekté helyett.`,"settings.access.ownRelay.use":`A saját továbbítóm használata`,"settings.access.ownRelay.lead":`Két út: ez a példány veszi át a továbbítót, vagy megadsz egy címet.`,"settings.access.ownRelay.serveLabel":`Ez a példány legyen a relay`,"settings.access.ownRelay.serveHint":`Csak akkor működik, ha ez a példány kívülről elérhető, például Nginx Proxy Manageren és saját domainen keresztül.`,"settings.access.ownRelay.serveClients":`Most {count} kapcsolódik.`,"settings.access.ownRelay.addressLabel":`Cím`,"settings.access.ownRelay.addressPlaceholder":`pl. https://relay.sajatdomain.hu`,"settings.access.ownRelay.save":`Mentés`,"settings.access.ownRelay.everyInstance":`Ez a cím csak erre a példányra vonatkozik. Add meg mindegyiken.`,"settings.access.ownRelay.containerLabel":`Saját konténerként`,"settings.access.ownRelay.containerHint":`Ha egyik példányod sem érhető el kívülről, a relaynek máshol kell állnia: a szervereden vagy egy kis VPS-en. Telepítsd a konténert az Unraid Community Applications közül, vagy az alábbi paranccsal.

A konténert nem kell beállítani: indítsd el, írd be a címét fentre, kész. Semmit nem tárol, így nincs mit menteni.`,"settings.access.tokens.title":`API tokenek`,"settings.access.tokens.intro":`Named credentials for Sonarr, Radarr, a monitoring system or a script. Each one can be revoked on its own, without changing the shared password every other client uses.`,"settings.access.tokens.empty":`Még nincs kiadott token.`,"settings.access.tokens.new":`Új token`,"settings.access.tokens.namePlaceholder":`e.g. Sonarr`,"settings.access.tokens.cancel":`Mégse`,"settings.access.tokens.create":`Létrehozás`,"settings.access.tokens.creating":`Létrehozás…`,"settings.access.tokens.created":`Létrehozva`,"settings.access.tokens.lastUsed":`Utoljára használva`,"settings.access.tokens.neverUsed":`soha`,"settings.access.tokens.revoke":`Visszavonás`,"settings.access.tokens.secretTitle":`Másolja ki ezt a tokent most`,"settings.access.tokens.secretWarning":`Ez az egyetlen alkalom, amikor ez a token megjelenik. Egyirányú hasként van tárolva ezen a példányon, tehát ha elvész, nincs mód újra elolvasni - csak visszavonni és újat létrehozni.`,"settings.access.tokens.copy":`Másolás`,"settings.access.tokens.copied":`Másolva`,"settings.access.tokens.done":`Kész`,"settings.access.tokens.howToUse":`Paste it into Sonarr or Radarr as the SABnzbd API key or the qBittorrent password. A script sends it as a header: Authorization: Bearer <token>`,"settings.access.tokens.createFailed":`Nem sikerült létrehozni a tokent: {error}`,"settings.access.identity.title":`Ennek a példánynak az azonosítója`,"settings.access.identity.nameLabel":`Név`,"settings.access.identity.namePlaceholder":`pl. Otthoni szerver`,"settings.access.identity.nameHint":`Párosításkor és az alábbi QR-kódban ezt kínáljuk fel először, ahelyett a név helyett, amelyet az operációs rendszer vagy a konténer-futtatókörnyezet éppen ad ennek a gépnek. Nem kötelező: ha üresen hagyod, marad az a név.`,"settings.access.identity.domainsLabel":`Ismert domainek`,"settings.access.identity.domainsHint":`Minden domaint automatikusan megjegyzünk, amikor először érkezik rajta kérés, és akkor is itt marad a listán, ha a későbbi kérések a LAN IP-címen jönnek. Kézzel akkor adj hozzá egy domaint, ha már be van állítva, de még nem érkezett rajta kérés. Soronként egy teljes cím, pl. https://kl.example.com.`,"settings.access.cardTitle":`Példányok összekapcsolása és távoli elérés`,"settings.access.phrase.body":`Egyetlen kifejezés összeköti az összes KnightLoaderedet. Hozd létre itt, majd illeszd be a többi példányodba. Nem kell hozzá fiók vagy bejelentkezés, és nincs mit beállítani.`,"settings.access.phrase.noPasswordWarning":`Ennek a példánynak nincs jelszava. A kifejezés minden vele összekötött példányt megnyit, így aki itt elolvassa, mindegyikhez hozzáfér, nem csak ehhez. Jobb előbb fent jelszót beállítani.`,"settings.access.phrase.activate":`Kifejezés létrehozása`,"settings.access.phrase.howStep1":`Ezen a példányon nyomd meg a(z) „{button}” gombot. Megjelenik tizenkét szó.`,"settings.access.phrase.howStep2":`Nyisd meg a KnightLoadert a másik gépen, gyere erre az oldalra, nyomd meg a(z) „{button}” gombot, és írd be a tizenkét szót.`,"settings.access.phrase.howStep3":`Kész! Mindegyik példány megjelenik a másiknál a „Példányok” alatt, és bármelyiket vezérelheted bármelyikről. Bekapcsolt relével a példányaid a hálózatodon kívülről is elérhetők.`,"settings.access.phrase.howWhat":`A szavak titok, nem cím. Minden példány két kulcsot számol belőlük: egyet a többiek megtalálásához, egyet a titkosításhoz.

Hogy egymásra találjanak, minden példány magától hívja ugyanazt a találkozási pontot az interneten. Aki ugyanazt a kulcsot mutatja, azt összekötik. Ezért egyik példányodnak sem kell kívülről elérhetőnek lennie.

A találkozási pont nem tud beleolvasni. A szavaidat sosem látja, és minden, ami átmegy rajta, a második kulccsal titkosított.`,"settings.access.phrase.statusDisconnected":`Nincs csatlakozva`,"settings.access.phrase.statusHintProject":`Csatlakozva a projekt relayéhez. A távoli elérés be van állítva.`,"settings.access.phrase.statusHintOwn":`Csatlakozva a saját relayedhez. A távoli elérés be van állítva.`,"settings.access.phrase.statusHintOff":`Nincs aktív relay. A példányaid csak a helyi hálózaton érhetők el.`,"settings.access.phrase.statusHintLost":`Nincs kapcsolat a relayjel. A KnightLoader tovább próbálkozik. Addig a példányaid csak a helyi hálózaton találják meg egymást.`,"settings.access.phrase.statusConnected":`Csatlakozva`,"settings.access.phrase.howButton":`Hogyan működik ez?`,"settings.access.phrase.joinButton":`Kifejezés megadása`,"settings.access.phrase.joinPlaceholder":`Illessze be a másik példány tizenkét szavát`,"settings.access.phrase.joinConfirm":`Összekötés`,"settings.access.phrase.errChecksum":`Ez a kifejezés érvénytelen. Nézd meg, nincs-e benne elgépelt vagy felcserélt szó.`,"settings.access.phrase.errUnknownWord":`A(z) {position}. szó („{word}”) nincs a megengedett szavak között.`,"settings.access.phrase.errWordCount":`Ez {count} szó. Egy kifejezéshez {need} kell.`,"settings.access.phrase.errExists":`Ennek a példánynak már van kifejezése. Egy új indításához előbb lépj ki a csoportból.`,"settings.access.phrase.yourPhrase":`Az Ön összekötő kifejezése`,"settings.access.phrase.pasteHint":`Illessze be ezt a tizenkét szót minden további példányba, amelyet össze akar kötni.`,"settings.access.phrase.qrHint":`Vagy olvasd be ezt a másik eszközzel gépelés helyett.`,"settings.access.phrase.revealWhy":`A kifejezés újbóli megjelenítéséhez adja meg ennek a példánynak a jelszavát. A csoport minden példányát megnyitja, nem csak ezt.`,"settings.access.phrase.revealConfirm":`Megjelenítés`,"settings.access.phrase.showAgain":`Kifejezés megjelenítése`,"settings.access.phrase.hide":`Kifejezés elrejtése`,"settings.access.phrase.leave":`Kilépés a csoportból`,"settings.browsertools.phoneTitle":`Telefonos alkalmazás`,"settings.browsertools.phoneHint":`A KnightLoader alkalmazás Android telefonokra. Megmutatja és irányítja a példányaidon futó letöltéseket, és linkeket küld nekik. Az APK a sarokban látható verzió.`,"settings.browsertools.storeAndroid":`Google Play`,"settings.browsertools.soon":`Hamarosan`,"settings.browsertools.download":`Letöltés`,"settings.browsertools.qrCode":`QR-kód`,"settings.browsertools.desktopTitle":`Asztali alkalmazás`,"settings.browsertools.desktopHint":`A KnightLoader programként a számítógépeden, ez a felület egy saját ablakban. Minden letöltés a legújabb kiadás.`,"settings.browsertools.serverTitle":`Kiszolgálón`,"settings.browsertools.serverHint":`Kiszolgálón a KnightLoader akkor is tovább tölt le, amikor ez a számítógép ki van kapcsolva. Telepítsd az Unraid Community Applications kínálatából, futtasd Docker-konténerként, vagy fordítsd le a forráskódból.`,"settings.browsertools.dockerHint":`Egy kattintás kimásolja a konténert indító parancsot:`,"settings.browsertools.sourceZip":`Forráskód.zip`,"settings.browsertools.installPwaLabel":`Vagy telepítsd ezt az oldalt alkalmazásként`,"settings.browsertools.install":`Telepítés`,"settings.browsertools.installIOS":`iPhone-on vagy iPad-en: nyissa meg ezt az oldalt Safariban, koppintson a Megosztásra, majd „Kezdőképernyőhöz adás”.`,"settings.nav.browsertools":`Alkalmazás`,"settings.browsertools.bookmarkletStep1":`Húzd az alábbi gombot a böngésződ könyvjelzősávjára. Úgy mentődik, mint bármelyik könyvjelző, és semmi sem települ.`,"settings.browsertools.bookmarkletStep2":`Bármelyik oldalon kattints rá (előbb jelölj ki szöveget, ha csak azt szeretnéd). Megnyílik egy kis KnightLoader-lap, amelyben már ki van töltve az oldal linkje vagy a kijelölt szöveg. Nézd át, és onnan add hozzá letöltésként.`,"settings.browsertools.installLabel":`Így telepítheted`,"settings.browsertools.installChromiumStep1":`Csomagold ki a letöltött fájlt.`,"settings.browsertools.installChromiumStep2":`Nyisd meg: chrome://extensions (vagy edge://extensions, brave://extensions).`,"settings.browsertools.installChromiumStep3":`Kapcsold be a fejlesztői módot.`,"settings.browsertools.installChromiumStep4":`Válaszd a „Kicsomagolt elem betöltése” lehetőséget, és jelöld ki a kicsomagolt mappát.`,"settings.browsertools.installChromiumStep5":`Kattints a címsor melletti kirakósdarab ikonra, és rögzítsd a KnightLoadert, a Chrome magától nem teszi ki az új bővítményeket az eszköztárra.`,"settings.browsertools.installFirefoxStep1":`A végleges telepítéshez: nyisd meg az about:addons oldalt, és kattints a jobb felső fogaskerék ikonra.`,"settings.browsertools.installFirefoxStep2":`Válaszd a „Kiegészítő telepítése fájlból…” lehetőséget, és válaszd ki ezt a fájlt.`,"settings.browsertools.installFirefoxStep3":`Gyors kipróbáláshoz nyisd meg inkább az about:debugging#/runtime/this-firefox oldalt, és válaszd az „Ideiglenes kiegészítő betöltése” lehetőséget. A kiegészítő a Firefox újraindításakor eltűnik.`,"settings.browsertools.bookmarkletTitle":`Bookmarklet`,"settings.browsertools.bookmarkletLink":`Hozzáadás a KnightLoaderhez`,"settings.browsertools.copyCode":`Inkább a kód másolása`,"settings.browsertools.copied":`Másolva.`,"settings.browsertools.extensionTitle":`Böngészőbővítmény`,"quickadd.title":`Hozzáadás a KnightLoaderhez`,"quickadd.manualLabel":`Link (vagy illesszen be többet, soronként egyet)`,"quickadd.manualHint":`Illessz be ide kézzel egy linket, vagy nyisd meg ezt az oldalt a bookmarkletből vagy az eszközöd Megosztás menüjéből.`,"quickadd.manualPlaceholder":`https://example.com/file.zip`,"quickadd.add":`Hozzáadás`,"quickadd.adding":`Hozzáadás…`,"quickadd.staged":`Hozzáadva a gyűjtőhöz.`,"quickadd.stagedNamed":`„{name}” hozzáadva a gyűjtőhöz.`,"quickadd.stagedCount":`{n} link hozzáadva a gyűjtőhöz.`,"quickadd.none":`Semmi sem lett hozzáadva. Minden itteni link már a gyűjtőben volt.`,"quickadd.failed":`Ezt nem sikerült hozzáadni: {error}`,"quickadd.undo":`Visszavonás`,"quickadd.undone":`Eltávolítva.`,"quickadd.openCollector":`Gyűjtő megnyitása`,"quickadd.toPeer":`Küldés ide: „{name}”.`,"quickadd.undoFailed":`Ezt nem sikerült visszavonni. Még mindig ott van. ({error})`,"quickadd.close":`Ablak bezárása`,"settings.system.lifecycleTitle":`Kilépés és újraindítás`,"settings.system.quit":`Kilépés`,"settings.system.restart":`Újraindítás`,"settings.system.quitConfirmTitle":`Kilép a KnightLoaderből?`,"settings.system.restartConfirmTitle":`Újraindítja a KnightLoadert?`,"settings.system.quitConfirmBody":`A folyamatban lévő munka előbb lefut, majd a folyamat kilép. {note}`,"settings.system.confirmCancel":`Mégse`,"settings.system.confirmProceed":`Megerősítés`,"settings.system.unavailable":`Ennek a buildnek nincs módja erre a böngészőből.`,"settings.system.lifecycleNoteContainer":`Ez egy konténeres build. A Kilépés és az Újraindítás itt ugyanazt csinálja: hogy a folyamat újra elindul-e, azt kizárólag a konténered saját újraindítási szabálya dönti el.`,"settings.system.lifecycleNoteDesktop":`Ez a desktop build; a kilépés és az újraindítás ugyanúgy zárul le, mint az ablak bezárása.`,"settings.system.acting":`Folyamatban…`,"settings.system.shuttingDownTitle":`Leállítás`,"settings.system.shuttingDown":`Leállítás. Ha ez a példány magától visszatér, az oldal akkor újracsatlakozik; egyébként zárja be ezt a lapot.`,"settings.system.actionFailed":`Ezt nem sikerült megtenni: {error}`,"settings.system.backupButton":`Biztonsági mentés letöltése`,"settings.system.restoreButton":`Biztonsági mentés feltöltése`,"settings.system.restoreConfirmTitle":`Visszaállítás biztonsági mentésből?`,"settings.system.restoreConfirmBody":`Ez lecseréli a jelenlegi adatbázist és beállításokat a „{name}” tartalmára. Ez nem vonható vissza.`,"settings.system.restoring":`Ellenőrzés és előkészítés…`,"settings.system.restoreFailed":`Nem sikerült visszaállítani: {error}`,"settings.system.restoreStaged":`{status}`,"settings.system.loadFailed":`Nem sikerült betölteni. Elérhető a kiszolgáló?`,"settings.nav.resolvers":`Feloldók`,"settings.module.ytdlp":`yt-dlp`,"settings.resolvers.moduleUnavailable":`A modul nem érhető el`,"settings.resolvers.moduleUnavailableHint":`Minden alábbi beállítás így is elmentődik, és abban a pillanatban életbe lép, amikor a yt-dlp elérhetővé válik. Semmi sem vész el abból, amit most szerkesztesz.`,"settings.resolvers.about":`A yt-dlp háttér beállításai. Ez tölti le azokat a média- és streamingoldalakat, amelyeket maga a yt-dlp támogat. Hogy egy adott linket egyáltalán melyik szolgáltatás kezel (a yt-dlp, egy debrid fiók vagy a JDownloader háttér), azt a Fiókok oldal prioritási sorrendje dönti el. Ezen az oldalon azt állíthatod be, mit tegyen a yt-dlp, ha egy link hozzá került.`,"settings.resolvers.quality":`Minőség`,"settings.resolvers.videoFormat":`Videoformátum`,"settings.resolvers.qualityHint":`Melyik -f szelektorral indul el a yt-dlp. A legjobb elérhető a yt-dlp saját alapértelmezése, és ezt használta minden letöltés, mielőtt ez a beállítás létezett volna.`,"settings.resolvers.quality.best":`Legjobb elérhető`,"settings.resolvers.quality.2160p":`Legfeljebb 2160p (4K)`,"settings.resolvers.quality.1440p":`Legfeljebb 1440p`,"settings.resolvers.quality.1080p":`Legfeljebb 1080p`,"settings.resolvers.quality.720p":`Legfeljebb 720p`,"settings.resolvers.quality.480p":`Legfeljebb 480p`,"settings.resolvers.quality.360p":`Legfeljebb 360p`,"settings.resolvers.quality.custom":`Egyéni formátumsztring`,"settings.resolvers.customFormat":`Egyéni formátum`,"settings.resolvers.customFormatHint":`A yt-dlp saját -f értéke, pl. bestvideo[height<=720]+bestaudio/best. Ellenőrzés nélkül kerül átadásra; egy olyan érték, amelyet a yt-dlp elutasít, a saját hibájával hiúsul meg a feladatnál.`,"settings.resolvers.playlist":`A teljes lejátszási lista letöltése, ha egy link egy ilyenre mutat`,"settings.resolvers.subtitles":`Feliratok`,"settings.resolvers.subtitleLangs":`Nyelvek`,"settings.resolvers.subtitleLangsHint":`A yt-dlp saját --sub-langs értéke, pl. en,de. Üresen alapértelmezés szerint en.`,"settings.resolvers.subtitleAuto":`Az automatikusan generált feliratok lekérése is, ha nincs kézi felirat`,"settings.resolvers.outputTitle":`Kimeneti fájlnév`,"settings.resolvers.outputHint":`A yt-dlp saját -o sablonja. Üresen a beépített %(title)s.%(ext)s-t használja. Tartalmazhat alkönyvtárakat is, pl. %(uploader)s/%(title)s.%(ext)s.`,"settings.nav.torrents":`Torrentek`,"settings.module.torrents":`Built-in torrent client`,"settings.torrents.title":`Torrentek`,"settings.torrents.seedingTitle":`Seedelés`,"settings.torrents.seedRatio":`Cél seedelési arány`,"settings.torrents.seedRatioHint":`Egy befejezett torrentet addig seedel tovább, amíg a saját méretéhez képest ennyi nem kerül vissza a rajhoz. 0 = nincs arány cél.`,"settings.torrents.seedDuration":`Cél seedelési időtartam`,"settings.torrents.seedDurationHint":`Egy befejezett torrentet a befejezés után ennyi ideig seedel tovább. 0 = nincs időkorlát. A fenti két cél közül amelyik előbb teljesül, az állítja le a seedelést.`,"settings.torrents.seedDurationUnit":`óra`,"settings.torrents.transferTitle":`Átviteli korlát`,"settings.torrents.uploadLimit":`Feltöltési korlát`,"settings.torrents.uploadLimitHint":`Korlátozza, hogy egy torrent milyen gyorsan tölt fel a rajnak seedelés közben. 0 = korlátlan.`,"settings.torrents.portTitle":`Port és továbbítás`,"settings.torrents.port":`Port`,"settings.torrents.portHint":`The port this instance listens for swarm connections on. 0 lets the built-in torrent client pick one.`,"settings.torrents.portRestartHint":`A motor csak egyszer építi fel a torrentkliensét, ezért az új port csak a példány újraindítása után lép életbe. A routert viszont azonnal megkérheted a továbbításra, akár figyel már rajta torrent, akár nem.`,"settings.torrents.portMapHint":`Megkéri a routert, hogy UPnP-n keresztül továbbítsa a fenti portot erre a gépre, hogy a más router mögötti peerek is elérjék. Nem minden router támogatja ezt, és némelyik úgy fogadja el a kérést, hogy az valójában nem működik.`,"settings.torrents.portMapButton":`UPnP-továbbítás megkísérlése`,"settings.torrents.portMapping":`Router lekérdezése…`,"settings.torrents.portMapNeedsPort":`Előbb adj meg fent egy portot, mielőtt továbbítanád. 0 esetén a routernek nincs hova továbbítania.`,"settings.torrents.portMapConfirmed":`Megerősítve: a(z) {port} port továbbítva, és ellenőrizve elérhetőnek bizonyult.`,"settings.torrents.portMapUnconfirmed":`A router elfogadta a kérést, de nem sikerült megerősíteni, hogy a továbbítás működik. Egyes routerek szó nélkül elfogadják a kérést, de nem hajtják végre. Próbálj ki egy elérhetőségi ellenőrzést a hálózaton kívülről.`,"settings.torrents.portMapFailed":`Nem sikerült továbbítani a portot: {error}`,"settings.torrents.portMapUnavailable":`Ez a build még nem kínál port-továbbítást.`,"settings.torrents.networkTitle":`Peer-felderítés`,"settings.torrents.dht":`DHT`,"settings.torrents.dhtHint":`Tracker nélkül talál peereket, más BitTorrent-kliensek elosztott jegyzékként való felhasználásával.`,"settings.torrents.pex":`Peer exchange (PEX)`,"settings.torrents.pexHint":`Kicseréli az ismert peereket a már kapcsolódottakkal, hogy egy kevés peerrel rendelkező raj gyorsabban megtalálható legyen.`,"settings.torrents.privateNote":`Egy privát torrent automatikusan kikapcsolja mindkettőt, amint ismertek a metaadatai, függetlenül attól, mi van itt beállítva: feltöltött .torrent fájlnál azonnal, magnet linknél pedig amint a saját metaadatai megérkeznek a rajtól. A legtöbb privát tracker kitiltja azokat a fiókokat, amelyek bármelyiket használják.`,"container.noJD":`titkosított, és csak egy JDownloader háttér tudja megnyitni. Nincs beállítva egy sem: állítsd a KL_JD-t egy olyan JDownloaderre, amelyet ez a példány elér, majd indítsd újra.`,"container.jdOff":`titkosított, és csak a JDownloader háttér tudja megnyitni. A „JDownloader háttér” ki van kapcsolva a Modulok oldalon.`,"torrent.staging":`Hozzáadás…`,"torrent.staged":`{file} hozzáadva a gyűjtőhöz.`,"torrent.stagedIn":`{file} hozzáadva a gyűjtőhöz itt: „{pkg}”.`,"torrent.duplicate":`{file} már szerepel a listán.`,"torrent.onlyOne":`egyszerre csak egy .torrent tekinthető át`,"torrent.tree.summary":`{n}/{total} fájl kiválasztva ({size})`,"torrent.tree.private":`Privát tracker`,"torrent.tree.selectAll":`Összes kijelölése`,"torrent.tree.selectNone":`Kijelölés törlése`,"torrent.tree.cancel":`Mégse`,"torrent.tree.add":`Hozzáadás a gyűjtőhöz`,"settings.torrents.notApplied":`Ez a build az alábbi beállítások közül kettőt még nem alkalmaz. A feltöltési korlátot elmenti és ellenőrzi, de a motor nem tudja alkalmazni egy futó letöltésre. A DHT és a PEX sem jut el egy közönséges torrentig: az mindkettővel bekapcsolva seedel, akármi van itt beállítva. A privát torrent másképp működik, ahogy a „Peer-felderítés” melletti (i) elmagyarázza.`,"onboarding.step":`{n}. lépés / {total}`,"onboarding.skip":`Kihagyás`,"onboarding.back":`Vissza`,"onboarding.next":`Tovább`,"onboarding.finish":`Kész`,"onboarding.welcome.title":`Üdvözöljük a KnightLoaderben`,"onboarding.welcome.body":`A KnightLoader egy saját üzemeltetésű letöltéskezelő. Illessz be vagy húzz be egy linket, és a hozzá illő háttérrendszer letölti: a beépített motor az egyszerű fájllinkeket, a yt-dlp a médiaoldalakat, egy debrid szolgáltatás azokat a tárhelyeket, amelyekért már fizetsz, egy headless JDownloader pedig minden mást. Ez a rövid bemutató azt az egy beállítást mutatja meg, amelyet érdemes indulás előtt ellenőrizni.`,"onboarding.welcome.langLabel":`Felület nyelve`,"onboarding.folder.title":`Hova kerüljenek a fájlok?`,"onboarding.folder.body":`Ez az a mappa, ahová a kész letöltések kerülnek. Írj be egy útvonalat, vagy tallózz a szerveren. Bármikor megváltoztathatod az Általános beállítások oldalon.`,"onboarding.accounts.title":`Prémium hosterek, amikor csak akarja`,"onboarding.accounts.body":`A sor fiók nélkül is működik. Ha teljes sebességet szeretnél egy olyan tárhelyen vagy debrid szolgáltatásnál, amelyért már fizetsz, add hozzá a belépési adatait a Fiókok alatt. Ezek közül semmit sem kell most beállítanod.`,"onboarding.accounts.link":`Fiókok megnyitása`,"onboarding.finished.title":`Készen áll`,"onboarding.finished.body":`Ezzel a bemutató véget ért. A Beállítások alatti Súgó oldal teljes áttekintést nyújt mindenről, amit ez a verzió tud, és a legtöbb vezérlőelem saját magyarázatot hordoz egy (i) ikon mögött.`,"commands.openPalette":`Parancspaletta megnyitása`,"commands.group.general":`Általános`,"commands.group.navigation":`Ugrás ide`,"commands.goOverview":`Ugrás az Áttekintésre`,"commands.goDownloads":`Ugrás a Letöltésekre`,"commands.goCollector":`Ugrás a Gyűjtőre`,"commands.goInstances":`Ugrás a Példányokra`,"commands.goAccounts":`Ugrás a Fiókokra`,"commands.goSettings":`Ugrás a Beállításokra`,"commands.group.settings":`Beállítások`,"commands.group.queue":`Sor`,"commands.group.language":`Nyelv`,"commands.group.downloads":`Letöltések`,"commands.group.collector":`Linkgyűjtő`,"commands.paletteLabel":`Parancspaletta`,"commands.searchPlaceholder":`Írjon be egy parancsot…`,"commands.noResults":`Nincs egyező parancs`,"settings.nav.shortcuts":`Gyorsbillentyűk`,"settings.shortcuts.subtitle":`Minden parancs, amely alapértelmezett gyorsbillentyűvel érkezik, alkalmazási hely szerint csoportosítva. Módosítson egy hozzárendelést, vagy állítsa vissza az alapértelmezettre.`,"settings.shortcuts.empty":`Egyetlen parancsnak sincs még alapértelmezett gyorsbillentyűje.`,"settings.shortcuts.change":`Módosítás`,"settings.shortcuts.reset":`Visszaállítás`,"settings.shortcuts.resetAll":`Összes visszaállítása alapértelmezettre`,"settings.shortcuts.resetAllConfirmTitle":`Visszaállítja az összes gyorsbillentyűt?`,"settings.shortcuts.resetAllConfirmBody":`Minden újra hozzárendelt gyorsbillentyű visszaáll az alapértelmezettre. Ez nem vonható vissza.`,"settings.shortcuts.resetAllConfirm":`Összes visszaállítása`,"settings.shortcuts.captureTitle":`Nyomjon meg egy új gyorsbillentyűt ehhez: „{name}”`,"settings.shortcuts.captureHint":`Nyomjon meg egy billentyűkombinációt, vagy az Escape-et a megszakításhoz.`,"settings.shortcuts.conflict":`A(z) „{combo}” billentyűt már használja: {command}.`,"settings.shortcuts.key.ctrl":`Ctrl`,"settings.shortcuts.key.alt":`Alt`,"dialog.dontShowAgain":`Ne kérdezze újra`,"dialog.dontShowAgainHint":`Legközelebb azonnal megtörténik. A kérdést a Beállítások, Megjelenés alatt hozhatod vissza.`,"settings.dialogs.title":`Kikapcsolt kérdések`,"settings.dialogs.hint":`Megerősítések, amelyeket kikapcsoltál. Kapcsold vissza, és újra kérdezni fog.`,"settings.categories.listTitle":`Kategóriák`,"settings.categories.listHint":`A kategória egy csokor alapbeállítás, névvel ellátva: mappa, hely a sorban, kibontási kapcsoló, sebességkorlát és szabály arra az esetre, ha a fájl már ott van. A nevet egyszer választod ki, amikor a linkek beérkeznek, ahelyett hogy minden adagnál újra megválaszolnád ezt az öt kérdést. Minden üresen hagyott mező azt jelenti, hogy ez a kategória nem mond róla semmit, és az eggyel feljebbi beállítás érvényes: a félig kitöltött kategória tehát csak azt változtatja meg, amit kitöltöttél. Legfeljebb 64 darab lehet, mert ez egy menü, amiből választasz.`,"settings.categories.name":`Név`,"settings.categories.nameHint":`Így hívják ezt a fiókot mindenhol, ahol felkínáljuk. Nevezd át, ahányszor csak akarod: az alatta lévő kulcs nem megy vele, tehát minden, ami már ide van sorolva, itt is marad. Az egyáltalán név nélküli sorhoz saját kulcs kell, különben a mentés pontosan ezzel az indokkal hiúsul meg.`,"settings.categories.id":`Kulcs`,"settings.categories.idHint":`Az az állandó azonosító, amelyre minden ide sorolt letöltés mutat. Új kategóriánál hagyd üresen: a kiszolgáló mentéskor egyszer levezeti a névből, és soha többé. A nagybetűk kicsire váltanak, a betűk és a számjegyek megmaradnak, minden más karaktersorozatból egyetlen kötőjel lesz, a „Filmek & Sorozatok” tehát „filmek-sorozatok” néven tárolódik. Ha később megváltoztatod, az nem átnevezés, hanem egy második fiók: a régi kulcs alá sorolt letöltések továbbra is olyan kulcsra mutatnak, amelyre senki nem hallgat, pontosan úgy viselkednek, mint a soha sehova nem sorolt letöltések, és azon a napon térnek vissza, amikor megint létezik ilyen kulcsú kategória.`,"settings.categories.dir":`Mappa`,"settings.categories.dirHint":`Ide kerül az ide sorolt letöltés. Az üres azt jelenti, hogy ez a kategória nem mond róla semmit, és a globális letöltési mappa érvényes. Lehet sablon is, például /media/sorozatok/<jd:packagename>, és csak az első helyőrző előtti résznek kell valódi mappának lennie. Az útvonalnak abszolútnak kell lennie, különben a mentés indoklással elutasításra kerül, ugyanígy akkor is, ha ez a példány nem tudja létrehozni a mappát vagy nem tud beleírni. A csomagonkénti almappák továbbra is érvényesek rá, az ide sorolás tehát nem kapcsolja ki őket. Az a Packagizer-szabály, amelyik saját mappát nevez meg, legyőzi ezt, mert az a szabály magát a linket nézte meg. A mappa pedig az indulás pillanatában íródik rá a letöltésre: ha itt megváltoztatod, minden átkerül, ami még nem indult el, és semmi, ami már fut.`,"settings.categories.priorityHint":`Hol kezdi a sorban az ide sorolt letöltés. A magasabb fut előbb. A „Nincs előírás” valódi válasz, és nem ugyanaz, mint az Alapérték: az Alapérték a középső hely, és visszahúzna egy linket, amelyet egy szabály már megemelt, a nincs előírás viszont pontosan úgy hagyja, ahogy megérkezett. A tartomány az, amit maga a sor elfogad, tehát egy kategória nem adhat a letöltésnek olyan helyet, amelyet semmilyen kezelővel nem tudsz visszavonni. Egyszer íródik rá, az előkészítés pillanatában, és soha többé, tehát az a letöltés, amelyet feljebb húztál a listában, ott marad, ahova tetted.`,"settings.categories.extractHint":`Kibontsuk-e az ebbe a kategóriába érkező archívumot. Az Öröklés az Archívumok oldalra bízza a döntést, és ez nem ugyanaz, mint a Ki: a Ki akkor is csomagolva hagyja az archívumokat, ha a globális beállítás kibontást mond, például egy zenei fiókban, ahol maga az archívum a szállítmány. A letöltés saját kapcsolója továbbra is erősebb ennél, mert ott egy szabály vagy egy ember döntött arról az egy letöltésről.`,"settings.categories.speedLimit":`Sebességkorlát (0 = nincs preferencia)`,"settings.categories.speedLimitHint":`Milyen gyorsan tölthet az ide sorolt letöltés. A 0 azt jelenti, hogy ennek a kategóriának nincs róla véleménye, és a példányszintű korlát érvényes. Egyelőre semmi sem érvényesíti: ebben a buildben egyetlen korlátozó van az egész alkalmazásra, a háttérrendszerek között szétosztva, és nincs letöltésenkénti keret, amelybe ez a szám beírható lenne. Az érték elmentődik és helyesen feloldódik, aztán senki nem kezd vele semmit. Azért van már most itt, hogy a beállítás később ne változtassa meg az alakját, amikor már mindenkinek fájljai vannak a lemezen.`,"settings.categories.collision":`Ha egy fájl már ott van`,"settings.categories.collisionHint":`Mi történik, ha már létezik az a fájl, amelyet egy ide sorolt letöltés írni készül. Az Öröklés a példányszintű választ veszi át a letöltési beállításokból, és az üres tényleg öröklést jelent: nem csendes „mindkettő megtartása”, így a véleménytelen kategória nem bírálhatja felül a kihagyásra állított példányt. A Mindkettő megtartása mellé írja „név (2)” néven, a Kihagyás meghagyja, ami ott van, és nem ír semmit, a Felülírás pedig csonkolja. „Kérdezz meg” nincs: nem lenne ott senki, aki válaszol, és a letöltés örökre a sorban ülne anélkül, hogy bármi megmondaná, miért.`,"settings.downloads.diskReserve":`Tartalék letöltésenként (GiB)`,"settings.downloads.diskReserveHint":`Az a hely, amely szabadon marad azon felül, amit egy letöltésnek még le kell hoznia. A letöltés csak akkor indul el, ha a hátralévő bájtjai és ez a mennyiség együtt is elfér, tehát csak olyat utasíthat el, amelyik amúgy is szárazra futtatta volna a kötetet. A három közül ez az egyetlen, amelyik gyárilag be van kapcsolva, 0,5 értékkel. A 0 kikapcsolja, akkor egyetlen letöltés az utolsó bájtig teleírhatja a kötetet. Az a fájl, amelynek a méretét a tárhely nem árulja el, mentesül mindaddig, amíg a méret meg nem érkezik, ez rendszerint néhány másodperccel az indulás után van.`,"settings.downloads.diskLowSpace":`Ne induljon el ez alatt (GiB)`,"settings.downloads.diskLowSpaceHint":`Az a szabad hely, amely alatt semmi új nem indul el, akármekkora, és akkor sem, ha a mérete ismeretlen. A 0 a kikapcsolt állapot, gyárilag így érkezik: a helyes szám teljesen a köteten múlik, egy gigabájt egy 16 TB-os tömbön semmi, egy memóriakártyán viszont a harmada. A sorban álló letöltések egyszerűen várnak, és maguktól újraindulnak, amint megint van hely. Ha az alatta lévő leállítási értéket ennél magasabbra állítod, mentéskor ez is felemelkedik hozzá, mert az „X alatt mindent leállítani” már azt is jelenti, hogy „X alatt semmit nem indítunk”.`,"settings.downloads.diskCriticalSpace":`Mindent leállít ez alatt (GiB)`,"settings.downloads.diskCriticalSpaceHint":`Az a szabad hely, amely alatt a már futó letöltéseket leállítjuk és visszatesszük a sorba; az ellenőrzés tizenöt másodpercenként történik. A 0 a kikapcsolt állapot, gyárilag így érkezik. Ez többe kerül, mint a fenti indítási érték: az az átvitel, amelyik nem folytatható, elveszíti mindazt, amit már lehozott, ezért olyan kötethez tartsd fenn, amelyik tényleg a betelés szélén áll. Ha magasabbra állítod az indítási értéknél, mentéskor az indítási érték emelkedik hozzá; az itt beírt számot soha nem csökkentjük csendben.`,"settings.feeds.titleHint":`RSS- és Atom-feedek, amelyeket ez a példány követ. Mindegyiket a saját ütemében kérdezzük le, és az új bejegyzés pontosan úgy kerül a gyűjtőbe, mint egy beillesztett link, tehát a hivatkozásszűrő, az oldalbejáró és a Packagizer is érvényes rá. Egy új feliratkozás első lekérése egyáltalán nem ad hozzá semmit: mindent, amit a feed abban a pillanatban tartalmaz, ismertként jegyzünk fel, hogy ne zúduljon rád egyszerre a kiadó teljes archívuma. Csak az kerül be, ami ezután jelenik meg. Az üres lista azt jelenti, hogy egyetlen feedet sem követünk.`,"settings.feeds.url":`Feed címe`,"settings.feeds.urlHint":`Az RSS- vagy Atom-dokumentum címe, csak http vagy https. Egyben ez azonosítja a feliratkozást is: ha megváltoztatod, másik feliratkozásod lesz, amelyik már nem tudja, mely bejegyzéseket vette át, tehát még egy elgépelés kijavítása is azzal jár, hogy a feedet újként olvassa végig. Az olvashatatlan vagy hosztot meg nem nevező cím miatt az egész beállításmentés a sor számával együtt hiúsul meg, ahelyett hogy csendben eltűnne. Az azonos című két sort mentéskor összevonjuk az elsőbe.`,"settings.feeds.interval":`Ellenőrzés ennyi percenként`,"settings.feeds.intervalHint":`Mennyi ideig hagyjuk békén ezt a feedet két lekérés között. Hagyd 0-n, akkor a szokásos negyedóra érvényes. 1 és 10080 között, ami egy hét, pontosan úgy vesszük a számot, ahogy beírtad. 1 alatt a kiszolgáló szó nélkül 1-re emeli, egy hét fölött egy hétre viszi vissza, és a mentés után a javított szám áll a mezőben. Egy perc az alsó határ, mert minden lekérés egy kérés valaki más kiszolgálójához, és a sűrűbb ütem az az út, amelyen egy példány kitiltatja a saját címét. Az első lekérés rögtön a mentés után történik, nem az első várakozás végén, és a lerövidített időköz azonnal érvénybe lép, nem annak a várakozásnak a végén, amelyet épp lerövidítettél.`,"settings.feeds.filter":`Címszűrő`,"settings.feeds.filterHint":`Reguláris kifejezés, amelyet minden bejegyzés címére próbálunk, vagyis arra a névre, amelyet a bejegyzés a gyűjtőben is kap. Hagyd üresen, ha mindent el akarsz vinni, amit a feed közzétesz. Azt dönti el, mi töltődik le, nem azt, mire emlékezünk: az elutasított bejegyzéseket is feljegyezzük látottként, tehát a jövő hónapban kitágított szűrő csak azt hozza be, ami onnantól jelenik meg, a feed teljes jelenlegi ablakát nem. Az érvénytelen minta miatt a mentés a sor számával együtt hiúsul meg. Sosem dobjuk el helyetted, mert az eldobott szűrő egy olyan feliratkozás, amelyik csendben begyűjti az egész feedet.`,"settings.feeds.dir":`Letöltési mappa`,"settings.feeds.dirHint":`Ide kerülnek ennek a feliratkozásnak a letöltései. Hagyd üresen, akkor oda mennek, ahova a letöltések általában. A mappa a begyűjtés után íródik rá a linkre, ugyanúgy, mint egy bedobott crawljob-fájl mappája, tehát felülbírálja azt a Packagizer-szabályt, amelyik mappát választott. Az útvonalváltozók itt működnek, és a mappaválasztó meghagyja a sablon többi részét. A fő letöltési mappával ellentétben itt mentéskor nem ellenőrzünk semmit: a létre nem hozható mappa csak akkor tűnik fel, amikor tényleg érkezik egy bejegyzés, és a letöltés ilyenkor a szokásos mappát kapja.`,"settings.feeds.priority":`Prioritás`,"settings.feeds.priorityHint":`Milyen prioritással indul az ebből a feedből érkező összes letöltés. Hagyd a Nincs megadva értéken, akkor a feliratkozás egyáltalán nem mond róla semmit, és ezek a letöltések ugyanúgy sorakoznak be, mint bármelyik másik. Minden más a begyűjtés után íródik rá a linkre, tehát felülbírálja azt a Packagizer-szabályt, amelyik prioritást állított be. A magasabb fut előbb; azt rendezi át, ami még vár, és a futó letöltést soha nem küldi vissza a sorba. Ha a fenti mappa nem használható, a prioritás sem kerül rá, mert a kettő egy menetben íródik.`,"settings.hostRules.title":`Kivételek tárhelyenként`,"settings.hostRules.titleHint":`Egy sor minden olyan tárhelyhez, amelyiknek a Letöltések oldalon lévőktől eltérő számok kellenek. A sor nélküli tárhely megtartja a globális értékeket, az üres táblázat tehát semmit nem változtat. Egy sor a megnevezett hosztra és annak minden aldomainjére vonatkozik: a rapidgator.net lefedi az rg.rapidgator.net címet is, a notrapidgator.net címet viszont nem. Ha két sor illik ugyanarra a linkre, a hosszabb hosztnév nyer.`,"settings.hostRules.pattern":`Tárhely`,"settings.hostRules.patternHint":`Az a hoszt, amelyről ez a sor szól, például rapidgator.net. Kisbetűsen tároljuk, vezető „*.” nélkül és záró pont nélkül, tehát a „*.Rapidgator.net.” és a „rapidgator.net” egy és ugyanaz a sor. A hoszt nélküli sort mentéskor eldobjuk, üzenet nélkül.`,"settings.hostRules.maxPerHost":`Egyidejű letöltések erről a tárhelyről (0 = globális beállítás)`,"settings.hostRules.maxPerHostHint":`Erre az egy tárhelyre lecseréli az „Egyidejű letöltések tárhelyenként” értéket, felfelé ugyanúgy, mint lefelé: a 8 itt akkor is működik, ha globálisan 2 áll. Az összesített „Egyidejű letöltések” fölé viszont nem visz, mert azt a végösszeget ellenőrizzük először, és az hamarabb telik be. A 0 azt jelenti, hogy ez a sor nem mond róla semmit, és a globális szám érvényes. 64 fölött a kiszolgáló 64-et tárol.`,"settings.hostRules.chunks":`Kapcsolatok letöltésenként erről a tárhelyről (0 = globális beállítás)`,"settings.hostRules.chunksHint":`Erre a tárhelyre felváltja a „Kapcsolatok letöltésenként” értéket, és egy szolgáltatás által a tárhelyről jelentett korláttal ellentétben magasabb is lehet a globális számnál. Két dolog mégis lefaragja: egyetlen letöltés vagy egy saját számot megadó szabály erősebb ennél a sornál, és az a szolgáltatás, amelyik tudja, hogy a tárhely csak kettőt enged, a reménykedő nyolcat visszaveszi kettőre. A 0 azt jelenti, hogy a globális szám érvényes. A motor legfeljebb 16-ot nyit, akármit írsz be.`,"settings.hostRules.retryDelay":`Várakozás az első újrapróbálkozás előtt, másodpercben (0 = a felette lévő szint)`,"settings.hostRules.retryDelayHint":`Mennyi ideig hagyjuk békén az erről a tárhelyről érkező sikertelen letöltést, mielőtt újra megpróbáljuk. Onnantól a várakozás duplázódik, amíg el nem éri az alábbi felső határt. A 0 nem azt jelenti, hogy „nincs várakozás”, hanem továbbadja a kérdést: előbb az adott hibafajta szabályának, aztán a példány egészére érvényes várakozásnak, végül a beépített 15 másodpercnek. Egy órára tiltó tárhelynél írj be ide egy órát, ahelyett hogy hat elutasított próbát égetnél el tíz perc alatt, és feladnád, mielőtt a tiltás letelik.`,"settings.hostRules.retryMax":`Leghosszabb várakozás két próbálkozás között, másodpercben (0 = a felette lévő szint)`,"settings.hostRules.retryMaxHint":`Itt áll meg a duplázás. A 0 ugyanúgy továbbadja a kérdést, mint a fenti várakozás, és a beépített 10 percnél ér véget. Az első várakozásnál alacsonyabb felső határt nem úgy használjuk, ahogy beírtad: az alkalmazás csendben felemeli arra a várakozásra, különben a várakozásként beírt szám egyszer sem lenne a tényleges várakozás. Az értéked így is a mezőben marad, tehát egy itteni 60 egy fenti 3600 mellett továbbra is 60-nak látszik, és 3600-ként viselkedik.`,"settings.hostRules.retryTries":`Próbálkozások ehhez a tárhelyhez (0 = globális beállítás)`,"settings.hostRules.retryTriesHint":`Hányszor próbáljuk meg egyáltalán az erről a tárhelyről érkező sikertelen letöltést. A 0 nem azt jelenti, hogy „soha”: továbbadja a kérdést az adott hibafajta szabályának, azután a Letöltések oldalon lévő „Automatikus újrapróbálkozások” értéknek. Ezzel adhatsz egyetlen szeszélyes tárhelynek tíz próbálkozást anélkül, hogy minden másnál megemelnéd a számot. 20-nál többet egyetlen sor sem kérhet, ugyanaz a felső határ, mint a globális számnál.`,"settings.hostRules.never":`Ezt a tárhelyet soha ne próbáljuk újra`,"settings.hostRules.neverHint":`Az erről a tárhelyről érkező, meghiúsult letöltést végleg félretesszük, időzítő nélkül. Ez saját végállapot, nem „három próbálkozás után meghiúsult”, és a lista is másképp mutatja: a próbálkozások számának emelése bárhol a másodikon segít, ezen semmit. Minden szint csak bekapcsolni tudja. A Ki itt nem vonja vissza azt a „soha” beállítást, amelyet az adott hibafajta szabálya már megadott, így egy sor lehet kikapcsolva úgy is, hogy a letöltést mégsem próbáljuk újra soha.`,"settings.advanced.mirrorPolicy":`Mikor számít két link ugyanannak a fájlnak`,"settings.advanced.mirrorPolicyHint":`Azt dönti el, melyik második linket hajtjuk össze egy már a listán lévő másolataként. A Soha egyáltalán nem hajt össze semmit. A Név ugyanazt a kiadást öt tárhelyről is elkapja, akkor is, ha azok a méretben nem értenek egyet, viszont két egymáshoz nem tartozó, setup.exe nevű fájlt is összevon. A Név és méret, az alapérték, mindkettő egyezését kéri, tehát az a link, amelynek a méretét még senki nem oldotta fel, soha nem vonódik össze. Az Ellenőrző összeg csak bizonyíték alapján von össze, és majdnem mindent elszalaszt, mert a hasítóérték ritkán ismert, mielőtt a fájl itt van. Ugyanazt az URL-t másodszor mindig elutasítjuk, akármit választasz, és egy szétdarabolt archívum részeit soha nem vonjuk össze egymással.`,"settings.advanced.keepMirrors":`A másolat megtartása eldobás helyett`,"settings.advanced.keepMirrorsHint":`Kikapcsolva az összehajtott másolat a következő újraindításnál eltűnik. Bekapcsolva második sorként áll oda amellett a letöltés mellett, amelyet másol, visszatartjuk, és annak másolataként címkézzük. Magától így sem indít el semmit: a sor addig vár, amíg kézzel el nem engeded, vagy amíg az alatta lévő kapcsoló el nem engedi. Ennek az ára másolatonként egy sorral több egy amúgy is hosszú listában, ezért a kikapcsolt az alapérték. A pontos duplikátumot soha nem tartjuk meg, akármi áll itt.`,"settings.advanced.mirrorFailover":`Váltás a másolatra, ha a letöltés elhal`,"settings.advanced.mirrorFailoverHint":`Nem csinál semmit, amíg a fenti kapcsoló ki van kapcsolva, mert akkor nincs félretett másolat, amelyet el lehetne engedni. Bekapcsolva a véglegesen elbukott letöltés átadja a mappáját, a csomagját és a prioritását a félretett másolatnak, és az elindul. Alapból ki van kapcsolva, mert az elengedéssel olyan tárhelyről indul átvitel, amelyet nem te választottál, annak a tárhelynek a tempójával, esetleg olyan fiókot igényelve, amilyened nincs, és itt semmi nem tud előbb megkérdezni. A megtelt lemez és az általad megszakított letöltés soha nem indítja el. A megbukott sor a saját indokával együtt a listán marad, a másolat pedig friss próbálkozásszámmal indul, nem örökli a halottét.`,"settings.advanced.onOffline":`Már offline-ként ismert linkek`,"settings.advanced.onOfflineHint":`Mi történik azzal a linkkel, amelyet egy ellenőrzés már eltűntnek talált, abban a pillanatban, amikor egy adag elhagyja a gyűjtőt. A „Mégis felvesszük” úgy indítja el, mintha semmi sem illett volna rá, és ez az egyetlen válasz, amely soha nem veszít el linket egy téves jelzés miatt. A „Maradjon a gyűjtőben”, az alapérték, semmi mást nem változtat a linken, így egy későbbi, más válasszal történő megerősítés még eléri. Az „Eldobás” az egyetlen válasz itt, amely bármit töröl. A „Kérdezz rá” csak akkor kérdez valóban, ha kézzel erősítesz meg: az automatikus megerősítésnél, a figyelt mappánál és a Click'n'Loadnál nincs, aki válaszoljon, ezért ott a link a gyűjtőben marad. Egy adag saját választ is hozhat, és felülbírálhatja ezt.`,"settings.advanced.reclaimTrust":`Mikor számít a lemezen már meglévő fájl a letöltésnek`,"settings.advanced.reclaimTrustHint":`Az a menet használja, amelyik még az első bájt előtt kész fájlokat keres, és amelyet kézzel indítasz: induláskor soha nem fut le, mert tízezer feladatnál ez egy lemezmenet lenne egy olyan sor előtt, amely még nem is létezik. Az Ellenőrző összeg csak ténylegesen ellenőrzött összeg alapján zárja le a feladatot, ez őszinte, és semmit nem segít annál a sok fájlnál, amely közzétett hasítóérték nélkül érkezik. A Saját feljegyzés, az alapérték, azt is elfogadja, ha a példány saját előzménye szerint pontosan ilyen nevű és ilyen hosszú fájl készült el. A Név és hossz elfogad egy teljes hosszúságú fájlt minden további bizonyíték nélkül, és ez ebben a buildben csapda: a letöltési könyvtár a végleges méretében hozza létre a fájlt, mielőtt az első bájt megérkezne, tehát a két százaléknál elhalt átvitel is késznek látszik. A rövidebb fájl mindig kezdetnek számít, az ellentmondó ellenőrző összeg mindig nyer, és ez a menet semmit nem töröl, nem helyez át és nem ír felül.`,"settings.advanced.retryTries":`Próbálkozások hibafajtánként`,"settings.advanced.retryTriesHint":`Hány próbálkozást kap egy letöltés, ha éppen ezért az okért bukott meg. A 0 azt jelenti, hogy nincs előírás, és helyette a Letöltések oldal általános újrapróbálkozási számát veszi; ez áll itt minden sorban addig, amíg bele nem írsz. Egy tárhelyre szóló szabály legyőzi ezt, ez pedig legyőzi az általános számot, a hármat viszont mezőnként oldjuk fel, tehát az ide beírt próbálkozásszám nem hallgattat el egy máshol beállított várakozást. A 20 fölött mentett érték 20-ra rövidül, a negatívból 0 lesz. Arra való ez, amikor egy tárhely egy órára tilt: hat próbálkozás tíz percen belül hat elutasítás, és az az egy, amelyik működött volna, soha nem történik meg.`,"settings.downloads.workDir":`Munkamappa`,"settings.downloads.workDirHint":`Ide íródik a letöltés, amíg még érkezik. A kész fájl utána kerül át a letöltési mappába, miután az ellenőrzőösszeg és az esetleges kibontás is megvolt, így ott soha nem látszik semmi félkész. Üresen, ahogy alapból van, a letöltések egyenesen a céljukba íródnak. Akkor állítsd be, ha valami más is figyeli a letöltési mappát: az Unraid movere leviszi a félkész fájlt a gyorsítótárról és a tömbre másolja, egy médiatár-szkenner pedig felveszi a befejezetlen videót, egyszer nem tudja lejátszani, és soha többé nem néz rá. Egyetlen rögzített abszolút útvonal, változók nélkül: minden azonos célba tartó letöltés ezen a mappán osztozik, egy sablon pedig szétszórná egy többkötetes archívum részeit. A nem abszolút útvonalat mentéskor eldobjuk. A torrentek és a más program által letöltött fájlok soha nem használják.`,"settings.archives.moveTo":`A kibontott fájlok áthelyezése ide`,"settings.archives.moveToHint":`Ide kerülnek a kibontott fájlok, amint a kibontás befejeződött. Ha üresen hagyod, ott maradnak, ahol kibontottuk őket. Ez nem egy második „Kibontás ide”: az a hely, ahová a kibontás ír, ott tehát a félkész kiadás mindaddig ott van, amíg a kibontás fut. Ez utólag mozgatja át a fájlokat, így a célhelyen soha nem látszik semmi befejezetlen. Ráadásul a tartalmat mozgatja, nem a kiadás mappáját, így a „Show.S01.COMPLETE.WEB/ep01.mkv” „ep01.mkv” néven érkezik, annak a mappának a nélkül, amelyet egyetlen médiatár sem kért. Változók itt megengedettek. Az a Packagizer-szabály, amely egy adott linkhez mappát nevezett meg, erősebb ennél.`,"settings.downloads.collision":`Ha a fájl már ott van`,"settings.downloads.collisionHint":`Mit tesz egy letöltés, ha a kívánt név a célmappában már foglalt. A „Mindkettő megtartása” a név (2).ext alakot írja mellé, a „Kihagyás” megtartja a meglévő fájlt, és sosem indítja el a letöltést, a „Felülírás” lecseréli, és a három közül ez az egyetlen, amelynél elveszíthet egy már meglévő fájlt. Ezt előre el kell dönteni, mert a szerver előtt senki sem ül, akitől megkérdezhetné. Csak a beépített letöltőnek lehet megmondani, milyen nevet írjon, és ez tölti le azt is, amit egy debrid szolgáltatás vagy a TorBox felold. A JDownloader és a yt-dlp maguk nevezik el a fájljaikat, így az ő linkjeiknél a „Kihagyás” az egyetlen válasz, amely egyáltalán eléri a fájlt.`,"settings.downloads.collisionAttempts":`Legfeljebb ennyi számozott név`,"settings.downloads.collisionAttemptsHint":`Ezt csak a „Mindkettő megtartása” használja. Felfelé számolja a név (2), név (3) és így tovább neveket, és hibával feladja, amint ennyit végigpróbált. A 0 a beépített 1000-es határt jelenti, nem azt, hogy „nincs határ”: ha egy mappa ugyanannak a névnek az ezer másolatával telik meg, az máshol elszabadult valami, rendszerint egy figyelt mappa, amelyik újra és újra beolvassa ugyanazt a listát, és egy soha meg nem álló számláló ebből olyan könyvtárat csinál, amelyet már senki nem tud megnyitni. Az 1000 fölötti értéket mentéskor visszavesszük 1000-re.`,"settings.downloads.autoConfirmDelay":`Várakozás az automatikus megerősítés előtt (másodperc)`,"settings.downloads.autoConfirmDelayHint":`Mennyi ideig vár egy új adag a gyűjtőben, mielőtt magától megerősítené magát. Ennyi időd van átnézni, kidobni egy linket vagy megváltoztatni a mappát. Minden adag külön számol vissza a jobb felső sarokban, és az ottani leállítás gomb a linkjeit a gyűjtőben hagyja. Azokhoz a linkekhez, amelyeket közben megerősítesz vagy eltávolítasz, nem nyúl. A 0 az érkezés pillanatában megerősíti az adagot. Az új érték a már futó visszaszámlálásokra is vonatkozik, így ha 0-t állítasz be, azonnal megerősíti őket. Mindez csak akkor történik meg, ha fent, a Linkfogadás alatt be van kapcsolva „A hozzáadott hivatkozások azonnali indítása”, és ha kikapcsolod, minden visszaszámlálás leáll. Egy nap a felső határ: a visszaszámlálást futás közben illik követni, ami ennél hosszabb, az elütött számjegy, nem beállítás. A negatív szám mentéskor 0 lesz.`,"settings.downloads.onDupes":`Linkek, amelyek már megvannak`,"settings.downloads.onDupesHint":`Mi történik a gyűjtőt elhagyó linkkel, ha már szerepel a listádban. A „Mégis felvesszük” ugyanúgy kezeli, mint bármelyik másik linket. A „Maradjon a gyűjtőben” nem erősíti meg, és semmi mást nem változtat rajta, így egy későbbi megerősítés még felveszi. Az „Eldobás” kiveszi a listából, és ez az egyetlen válasz, amely bármit eldob, ezért soha nem ez az alapérték. A „Kérdezz rá” csak akkor kérdez, ha valaki tényleg megnyomta a Megerősítést: a visszaszámlálásnak, a figyelt mappának és a Click’n’Loadnak nincs kit megkérdeznie, ezért ott a link a gyűjtőben marad. Egy adag ezt felülbírálhatja; amit itt beállítasz, az akkor érvényes, ha nem teszi.`,"settings.downloads.addAtTop":`Az újonnan megerősített linkek a sor elejére`,"settings.downloads.addAtTopHint":`A gyűjtőt elhagyó adag következőként kerül sorra, ahelyett hogy beállna mindaz mögé, ami már várt. A saját prioritási sávján belül mozdul, pontosan oda, ahová a „Legfelülre” is tenné, így egy általad magasabb prioritásúra állított letöltés továbbra is előbb fut. Alapból ki van kapcsolva, ekkor a linkek a sor végére állnak. Attól függetlenül érvényes, hogyan történt a megerősítés: kézzel, visszaszámlálással vagy a figyelt mappából.`,"settings.stall.enabled":`Az elakadó letöltések megjelölése`,"settings.stall.enabledHint":`A halott kapcsolat nem bukik meg és nem áll le. A sor továbbra is azt mondja, hogy fut, 0 B/s mellett, foglalja a letöltési helyét, és reggel is pont ott áll azzal a három százalékkal, amennyi éjfélkor volt. Ha ez be van kapcsolva, azt az átvitelt, amelyik az alább beállított ideig egyetlen bájtot sem mozdított, elakadtként jelöljük meg a listában. A jelölés semmit nem változtat magán a letöltésen, csak kimondja, ami amúgy is igaz. A kikapcsolt azt jelenti, hogy soha nem jelölünk meg semmit.`,"settings.stall.timeout":`Idő bájtok nélkül (másodperc)`,"settings.stall.timeoutHint":`Mennyi ideig nem mozdíthat egyetlen bájtot sem egy futó letöltés, mielőtt elakadtnak számít. A 60 másodperc a legkisebb létező érték, minden ez alatti mentéskor 60-ra emelkedik: egy percen belül a darabváltás, az újracsatlakozás vagy a tárhely saját visszaszámlálása pontosan úgy néz ki, mint egy halott kapcsolat, a rövidebb idő tehát nem elakadásokat találna, hanem az egész sort megjelölné. Felfelé egy nap (86400 másodperc) a határ. A captchára váró link soha nem számít elakadtnak, és az órája a válasz után megint nulláról indul.`,"settings.stall.restart":`Az elakadt letöltés indítása elölről`,"settings.stall.restartHint":`Visszateszi a megjelölt letöltést a sorba, és elölről kezdi. Ezzel eldobja azokat a bájtokat, amelyeket az elakadt próbálkozás már lehozott, pontosan úgy, mint egy kézi újraindítás, ezért is saját kapcsoló, és kikapcsolva marad, amíg be nem kapcsolod: a megjelölés információ, az újraindítás döntés. A torrenteket ezen a módon soha nem indítjuk újra, akármi áll itt, mert a peereket nem találó torrent csak ugyanazt a magnetet kapná még egyszer, mindaz nélkül, ami már megvolt neki.`,"settings.stall.maxRestarts":`Újraindítások letöltésenként`,"settings.stall.maxRestartsHint":`Hányszor indítható újra magától egy letöltés, mielőtt békén hagyjuk. A 0 nem korlátlan, hanem 3, a beépített szám. A határ elérése után a letöltés megtartja a jelölését és fekve marad, hogy te magad nézhess rá, ahelyett hogy egész éjjel hiába dolgozná ugyanazt a kiszolgálót. A kiszolgáló 20-nál többet nem fogad el, minden ennél nagyobb 20-ként tárolódik. A számláló a letöltéshez tartozik, és csak akkor nullázódik, amikor az elkészül.`,"settings.resolvers.audioFormat":`Hangformátum`,"settings.resolvers.audioFormatHint":`Az ilyen formátumú sávval rendelkező forrást átmásoljuk, az ilyen sáv nélkülit az ffmpeg alakítja át. Az „Automatikus” a legjobb sávot veszi úgy, ahogy van. Ez csak tartalék: az új linkek a lenti változat-alapbeállításokból veszik a hangformátumukat, a sorban megadott választás pedig mindkettőnél erősebb.`,"settings.resolvers.audioBitrate":`Hang bitrátája`,"settings.resolvers.audioBitrateHint":`Milyen bitrátára kódol az ffmpeg átalakításkor, kbit/s-ban. Az „Automatikus” nem ad meg célt, és meghagyja a yt-dlp alapértékét, nagyjából 128 kbit/s-ot, változó bitrátával. Az átmásolt sáv megtartja a saját bitrátáját. Ez felső korlát: egy 128-as forrásból a 320 semmivel sem szól jobban.`,"settings.resolvers.audioLang":`Beszélt nyelv`,"settings.resolvers.audioLangHint":`Egyetlen beszélt nyelvre szűkíti a hangsort, ha a forrás többet is kínál, ahogy a YouTube automatikus szinkronja: enélkül a legjobban szóló sáv nyer, és nem biztos, hogy az, amelyiken valóban beszélnek. Két betű, vagy egy teljes kód, például pt-BR. Az elejétől egyeztetünk, így a de a de-DE-t is elviszi. Az üres azt jelenti, hogy nincs előírás. Az a forrás, amely sávonként nem nevez meg nyelvet, emiatt nem bukik el: a kérés a szokásos legjobb sávra esik vissza.`,"settings.resolvers.music":`A hangletöltések címkézése zeneként`,"settings.resolvers.musicHint":`Címkézővé alakítja a Hang sorát: az előadó, az album, a cím és a sorszám beleíródik a fájlba, a fájlok Előadó és Album mappákba kerülnek számozott néven, és egy cover.jpg is lementődik melléjük. Címkék nélkül tizenkét fájl tizenkét összefüggéstelen kislemez Unknown Artist előadótól a Jellyfinben vagy a Navidrome-ban, mert a médiatár a címkéket olvassa, nem a fájlnevet. Az átnevezés csak addig történik meg, amíg a fenti kimeneti fájlnév mezője üres: a valaki által beírt sablon mindig nyer.`,"settings.resolvers.subtitleStrict":`Hibának számítson a Felirat sora, ha nem lett fájl`,"settings.resolvers.subtitleStrictHint":`Az a forrás, amelyik nem hordozza a kért nyelvet, ezt figyelmeztetésként mondja meg, ez a háttérrendszer pedig kikapcsolt figyelmeztetésekkel indítja a yt-dlp-t. A feladat tehát szépen véget ér és zölden áll egy üres mappa fölött, és sehol nem áll, hogy a nyelv soha nem is volt elérhető. Ezzel bekapcsolva a semmit sem író Felirat sora pirosra vált, és megnevezi a kért nyelveket. Alapból ki van kapcsolva, mert a bekapcsolása olyan sorokat visz pirosba, amelyeket egy meglévő telepítés hónapok óta zölden pipál ki.`,"settings.resolvers.embedMetadata":`Cím, feltöltő és dátum írása a fájlba`,"settings.resolvers.embedMetadataHint":`A forrás saját címét, feltöltőjét, dátumát és leírását a konténer címkeblokkjába teszi. Ezt olvassa először a Jellyfin és a Plex, ha nincs NFO-fájl a fájl mellett. Csak a Videó és a Hang sorára vonatkozik: a bélyegkép, a felirat és a leírás szándékosan külön fájl, és a címkék beleírása ellentmondás volna.`,"settings.resolvers.embedThumbnail":`A borítókép beágyazása`,"settings.resolvers.embedThumbnailHint":`A forrás saját bélyegképét borítóként a fájlba csatolja, hogy a saját gyűjtő nélküli médiatár is mutasson képet. Csak a Videó és a Hang sorára vonatkozik. A bélyegkép sorát nem váltja ki: az ugyanazt a képet külön .jpg fájlként is a letöltés mellé teszi.`,"settings.resolvers.embedChapters":`Fejezetjelölők beágyazása`,"settings.resolvers.embedChaptersHint":`A forrás saját fejezetjelölőit írja a konténerbe. Csak ettől ugrik a lejátszó tovább gombja a következő szakaszra, ahelyett hogy fix számú másodpercet lépne.`,"settings.resolvers.embedSubs":`A feliratok beépítése a videóba`,"settings.resolvers.embedSubsHint":`Lehozza a fenti feliratkártyán megnevezett nyelveket, és a videofájlba teszi őket, ahelyett hogy .srt fájlokat hagyna mellette. Csak a Videó soraira vonatkozik: a kinyert hangfájlnak nincs feliratsávja, amely elvinné őket, és a yt-dlp erre a kérésre olyan figyelmeztetéssel válaszol, amelyet ez a háttérrendszer soha nem ír ki. Ugyanazt a nyelvlistát és ugyanazt az automatikus felirat kapcsolót használja, mint a Felirat sora, a kettő tehát soha nem mondhat ellent egymásnak.`,"settings.resolvers.embedSplitChapters":`Fejezetenként egy fájl mentése is`,"settings.resolvers.embedSplitChaptersHint":`A teljes letöltés mellé fejezetenként még egy-egy fájlt ír. Hozzáad, nem az egész fájlt váltja ki: egy kétórás, húsz fejezetből álló videóból huszonegy fájl lesz.`,"settings.resolvers.embedNfo":`NFO-fájl írása a letöltés mellé`,"settings.resolvers.embedNfoHint":`Kodi, Jellyfin és Plex stílusú .nfo fájlt tesz a kész fájl mellé, azokból az adatokból építve, amelyeket a yt-dlp a kiolvasás közben amúgy is összeszedett. Csak a Videó és a Hang sorára vonatkozik. A sikertelen írás nem viszi bukásba a letöltést: a médiafájl így is, úgy is teljes, és a mellé kerülő fájl újra elkészül, ha a feladat még egyszer lefut.`,"settings.resolvers.measure":`A kész fájl megmérése`,"settings.resolvers.measureHint":`Minden kész videó- vagy hangletöltést visszaolvas az ffprobe-bal, és feljegyzi, mi van benne valójában: játékidő, felbontás, kodekek, hány hangsáv. Letöltésenként egy rövid helyi folyamatot futtat, hálózat nélkül és új függőség nélkül. Azt a letöltést fogja meg, amely korán megszakadt, és mégis összefűzték: a kilépési kód 0, a méret hihetőnek tűnik, a kép pedig húsz percnél megáll. Azt nem tudja elkapni, amikor az összefűzést írás közben lövik le, mert az a fejlécében megtartja a tervezett játékidőt, de ez az eset általában amúgy is hangosan elbukik magától.`,"settings.resolvers.measureShortPercent":`Ez alatt számít rövidnek (százalék)`,"settings.resolvers.measureShortPercentHint":`A forrás által bejelentett játékidő hány százalékát kell a fájlnak ténylegesen tartalmaznia ahhoz, hogy ne számítson rövidnek. A 90 az alapérték, nem a 99: egy valódi letöltés gyakran kicsivel a bejelentett szám alatt marad, és az a küszöb, amely ilyenkor megszólal, mindenkit arra tanít, hogy ne figyeljen rá. Egy levágott összefűzésből a fele hiányzik, nem öt százalék. Az 1 és 100 közötti tartományon kívüli értéket 90-ként tároljuk, nem a közelebbi széléhez igazítjuk. „Soha ne szólj” jelentésű 0 nincs, mert épp azért kapcsolod be az ellenőrzést, hogy szóljon.`,"settings.resolvers.measureFailOnShort":`A rövid letöltés számítson hibának, ne figyelmeztetésnek`,"settings.resolvers.measureFailOnShortHint":`A fenti küszöb alatti fájl készként áll oda, és figyelmeztetést visel a sorában. Ezzel bekapcsolva pirosra vált, és így egy kattintással újrafuttatható. Alapból ki van kapcsolva, mert a lemezen lévő bájtok valódiak, és sokszor így is megérik a megtartást.`,"settings.resolvers.live":`Livestreamek felismerése`,"settings.resolvers.liveHint":`A streamnek nincs vége és nincs teljes mérete, enélkül tehát a rá mutató link közönséges letöltésként érkezik, olyan számból rajzolt haladásjelzővel, amelyet senki nem ismer, és egy soha el nem érkező vég felé kúszik, miközben a lemez megtelik. Ezzel bekapcsolva az ilyen sor azt mutatja, mióta tart a felvétel és mennyi érkezett meg, a lenti két korlát pedig határt szabhat neki. Magát a felismerést is ez kapcsolja: kikapcsolva a letöltések pontosan azzal a haladásformátummal és azzal a feldolgozással futnak, amellyel mindig is.`,"settings.resolvers.liveFromStart":`Kezdés a stream elejétől`,"settings.resolvers.liveFromStartHint":`A stream saját elejétől vesz fel, ahelyett hogy az élő szélénél kapcsolódna be. A yt-dlp ezt csak YouTube-ra érvényesként és kísérletiként tartja számon, és mindenre, ami nem élő adás, egyszerűen figyelmen kívül hagyja, ott tehát semmibe nem kerül.`,"settings.resolvers.liveMaxMinutes":`A felvétel időkorlátja`,"settings.resolvers.liveMaxMinutesHint":`Ennyi perc után leállítja a felvételt, attól a pillanattól számolva, amikor a streamadatok ténylegesen megérkeznek, nem a feladat indulásától, így a premierre várás vagy egy botellenőrzéssel folytatott harc nem eszi meg ezt az időt. A 0 azt jelenti, hogy nincs korlát. A korlát időtartam, nem napszak: a „23:00-kor állj le” egy 22:00-kor indult streamnél egyórás korlát, amely csendben huszonhárom órássá válik, ha ugyanazt a linket éjfélkor illesztik be. A korlát elérésekor a felvétel kíméletesen áll le, így a fájl lezárul és lejátszható, a sor pedig késznek számít, mellette az okkal, nem hibaként.`,"settings.resolvers.liveMaxMB":`A felvétel méretkorlátja`,"settings.resolvers.liveMaxMBHint":`Leállítja a felvételt, amint ennyi megérkezett, MiB-ben. A 0 azt jelenti, hogy nincs korlát. Azt számoljuk, amit a yt-dlp letöltöttként jelent, nem a lemezen lévő méretet: az élő letöltés ideiglenes darabokba íródik, amelyek együttes mérete nem az a szám, amelyhez bárki korlátot szabna. A kettő közül amelyik előbb teljesül, az zárja le a felvételt, szelíden, és a sor készként nyugszik meg, az indokkal együtt.`,"settings.resolvers.cookies":`A tárolt bejelentkezési sütik használata`,"settings.resolvers.cookiesHint":`Átadja a yt-dlp-nek az adott oldalhoz tárolt cookies.txt fájlt, és ez az, ami átjut a „jelentkezz be, hogy igazold, nem vagy robot” képernyőn és a korhatár-kapukon. A tároló soha nem része a beállításdokumentumnak: a titkosított hitelesítőtárban él, csak rövid időre íródik ki ideiglenes fájlba, amelyet csak ez a kiszolgáló tud olvasni, és az a fájl a folyamat végén azonnal törlődik. Kapcsoló, nem automatizmus, mert egy bejelentkezett munkamenet elküldésének következményei vannak: a sebességkorlát vagy a kitiltás a fiókot éri, nem a címet. Annál az oldalnál, amelyhez nincs tárolt fájl, ez semmit nem változtat.`,"settings.resolvers.variantDefaults":`Változatok alapbeállításai`,"settings.resolvers.presetsHint":`Minden yt-dlp linkből öt sor lesz: videó, hang, bélyegkép, felirat és leírás. Ez a táblázat oldalanként dönti el, melyiket mutatja a gyűjtő, és milyen formátummal és minőséggel indul a videó- és a hangsor. Egy változat kikapcsolása azonnal eltávolítja a sorait, a gyűjtőben már bent lévő linkeknél is, visszakapcsolása pedig visszahozza őket. Ha egy link ellenőrizve van, a videó- és hangsora átvált a link saját sávjára, amelyik a legközelebb áll ehhez. Az az oldal, amelynek itt nincs sora, mind az ötöt legjobb minőségben kapja. Az oldal feljebb lévő minőség- és hangformátum-beállítása csak a saját választás nélküli sorokra vonatkozik. A gyűjtőben egy csomag fogaskereke ugyanezeket a beállításokat nyitja meg a csomag tárhelyére.`,"settings.module.categories":`Kategóriák`,"settings.module.feeds":`Feed-feliratkozások`,"settings.module.downloadclient":`Letöltőkliens a Sonarrhoz és a Radarrhoz`,"settings.downloads.collisionTitle":`Névütközések`,"settings.downloads.collectorTitle":`Gyűjtő`,"settings.downloads.diskTitle":`Lemezterület`,"settings.downloads.diskHint":`Három szám, amely visszatartja a letöltéseket, mielőtt megtelne a lemez. Mindhárom a szabad bájtokat jelenti azon a köteten, amelyre a letöltés éppen íródik, így egy másik lemezen lévő munkamappánál azt a lemezt mérjük. A nulla kikapcsolja az adott számot. Nem minden rendszertől lehet megkérdezni, mennyi a szabad hely, és ahol nincs válasz, ott soha nem tartunk vissza semmit, mert egy olyan őr, amely tudatlanságból blokkol, egy teljesen egészséges gépet állítana le.`,"settings.stall.title":`Elakadás`,"settings.advanced.mirrorsTitle":`Ugyanannak a fájlnak a másolatai`,"settings.advanced.offlineTitle":`Már halott linkek`,"settings.advanced.reclaimTitle":`A lemezen már meglévő fájlok`,"settings.advanced.retryTitle":`Újrapróbálkozások hibafajtánként`,"settings.resolvers.audioTitle":`Hang`,"settings.resolvers.subtitlesTitle":`Feliratok`,"settings.resolvers.embedTitle":`A fájlon belül`,"settings.resolvers.measureTitle":`A kész fájl ellenőrzése`,"settings.resolvers.liveTitle":`Livestreamek`,"settings.resolvers.cookiesTitle":`Bejelentkezési sütik`,"settings.hostRules.add":`Tárhely hozzáadása`,"settings.hostRules.remove":`Eltávolítás`,"settings.hostRules.empty":`Egyetlen tárhelynek sincs még saját száma.`,"settings.hostRules.emptyHint":`Amíg nem adsz hozzá egyet, mindenhol a Letöltések oldal értékei érvényesek.`,"settings.hostRules.duplicate":`Ehhez a tárhelyhez már van egy sor.`,"settings.feeds.add":`Feliratkozás hozzáadása`,"settings.feeds.remove":`Eltávolítás`,"settings.feeds.empty":`Még nincs feliratkozás.`,"settings.feeds.emptyHint":`A feliratkozás magától ellenőriz egy feedet, és az újat beteszi a gyűjtőbe.`,"settings.feeds.duplicate":`Erre a címre már feliratkoztál.`,"settings.categories.add":`Kategória hozzáadása`,"settings.categories.remove":`Eltávolítás`,"settings.categories.empty":`Még nincs kategória.`,"settings.categories.emptyHint":`A kategória egy mappát és néhány alapbeállítást tart egyetlen név alatt, hogy a nevet válaszd ahelyett, hogy ugyanazt még egyszer leírnád.`,"settings.categories.duplicate":`Ilyen nevű kategória már van.`,"settings.categories.full":`{max} kategóriánál betelt a táblázat.`,"settings.resolvers.presetAdd":`Tárhely hozzáadása`,"settings.resolvers.presetRemove":`Eltávolítás`,"settings.resolvers.presetsEmpty":`Egyetlen tárhelynek sincs még saját alapbeállítása.`,"settings.resolvers.presetHost":`Tárhely`,"settings.resolvers.presetHostHint":`Az oldal, amelyre ezek az alapértelmezések vonatkoznak, például youtube.com. Kisbetűvel és az elejéről elhagyott „www.” nélkül tárolódik, és egy teljes cím beillesztése is működik: csak a gazdagép marad meg. A nagy videós oldalaknál egy bejegyzés a többi címüket is lefedi: a youtube.com a youtu.be és az m.youtube.com címet is. Az a tárhely, amelynek itt nincs bejegyzése, minden változatot bekapcsolva indít, a legjobb minőségben.`,"settings.resolvers.quality.4320p":`Legfeljebb 4320p (8K)`,"settings.resolvers.quality.240p":`Legfeljebb 240p`,"settings.resolvers.quality.144p":`Legfeljebb 144p`,"settings.downloads.confirm.include":`Mégis felvesszük`,"settings.downloads.confirm.exclude":`Maradjon a gyűjtőben`,"settings.downloads.confirm.excludeAndRemove":`Eldobás`,"settings.downloads.confirm.ask":`Kérdezz rá`,"settings.advanced.mirror.off":`Soha`,"settings.advanced.mirror.filename-only":`Azonos fájlnév`,"settings.advanced.mirror.size-only":`Azonos méret`,"settings.advanced.mirror.filename-and-size":`Azonos név és azonos méret`,"settings.advanced.mirror.filename-or-hash":`Azonos név vagy azonos ellenőrző összeg`,"settings.advanced.mirror.hash-only":`Azonos ellenőrző összeg`,"settings.advanced.offline.include":`Mégis felvesszük`,"settings.advanced.offline.exclude":`Maradjon a gyűjtőben`,"settings.advanced.offline.exclude-and-remove":`Eldobás`,"settings.advanced.offline.ask":`Kérdezz rá`,"settings.advanced.reclaim.checksum":`Egyező ellenőrző összeg`,"settings.advanced.reclaim.record":`Bejegyzés arról, hogy ezt a fájlt ez a letöltés írta`,"settings.advanced.reclaim.size":`A helyes név és a helyes méret`,"settings.categories.priorityNone":`Nincs előírás`,"settings.feeds.priorityNone":`Nincs megadva`,"task.waiting.disk":`Lemezterületre vár`,"settings.feeds.status":`Állapot`,"settings.feeds.statusPolling":`Ellenőrizzük`,"settings.feeds.statusNotPolling":`Nem ellenőrizzük`,"settings.feeds.statusUnknown":`A kiszolgáló indítása óta még nem ellenőriztük`,"settings.feeds.lastPolled":`Utoljára ellenőrizve`,"settings.feeds.lastPolledNever":`Még nem ellenőriztük`,"settings.feeds.lastPolledHint":`Mikor néztük meg utoljára ezt a feliratkozást, függetlenül attól, hogy a lekérés sikerült-e. A kiszolgáló újraindításakor ez az adat elvész, az viszont nem, amit a feliratkozás már átvett, tehát egy hónapok óta követett feed az újraindítás utáni néhány másodpercben ellenőrizetlenként áll.`,"settings.feeds.pollFailed":`Az utolsó ellenőrzés nem sikerült`,"settings.feeds.notPolledReason":`Ezt a feliratkozást egyáltalán nem ellenőrizzük`,"settings.feeds.seededYes":`Kész, csak az új bejegyzések kerülnek be`,"settings.feeds.seededNo":`Az első ellenőrzés még hátravan, addig semmi nem kerül be`,"settings.feeds.seededHint":`Egy új feliratkozás első ellenőrzése mindent feljegyez, amit a feed abban a pillanatban tartalmaz, és semmit nem vesz át belőle, hogy ne zúduljon rád egyszerre a kiadó teljes archívuma. Csak az kerül be, ami ezután jelenik meg.`,"settings.feeds.remembered":`{n} megjegyzett bejegyzés`,"settings.feeds.rememberedHint":`Hány bejegyzést ismer fel újra ez a feliratkozás, hogy ne kerüljenek be másodszor is, amíg a feed még kiszolgálja őket. Feliratkozásonként legfeljebb 500; a legrégebbiek esnek ki először, és az a bejegyzés, amelyik még benne áll a feedben, soha nincs köztük.`,"settings.feeds.test":`Teszt`,"settings.feeds.testBusy":`Lekérés…`,"settings.feeds.testHint":`Egyszer lekéri ezt a címet, és megmutatja, mi van benne, hogy lásd, milyen bejegyzéscímekhez hasonlítjuk a szűrődet. Csak olvas: semmi nem kerül a gyűjtőbe, és semmit nem jegyzünk fel látottként, tehát olyan címre is megnyomhatod, amelyet még nem mentettél el.`,"settings.feeds.testResult":`Mi van ebben a feedben`,"settings.feeds.testFeedName":`Feed neve`,"settings.feeds.testNoName":`Ez a dokumentum nem közöl nevet`,"settings.feeds.testMatched":`{total} bejegyzés közül {matched} illeszkedik a címszűrőre`,"settings.feeds.testNoFilter":`Nincs címszűrő, tehát mind a(z) {total} bejegyzést elvisszük`,"settings.feeds.testShowing":`Az első {n} látszik`,"settings.feeds.testMatchYes":`Elvisszük`,"settings.feeds.testMatchNo":`Kimarad`,"settings.feeds.testNoneMatch":`Ebben a feedben semmi nem illeszkedik a címszűrődre. Vesd össze a helyesírást a fenti címekkel.`,"settings.feeds.testEmpty":`A cím válaszolt, de a dokumentum egyáltalán nem tartalmaz bejegyzéseket. Ellenőrizd, hogy tényleg feed-e, és nem az az oldal, amelyen a feed áll.`,"settings.feeds.testFailed":`Ezt a feedet nem sikerült beolvasni`,"settings.headerProfiles.title":`Fejlécprofilok`,"settings.headerProfiles.hint":`Néhány oldal csak olyan böngészőnek adja ki a fájlt, amelyik be van jelentkezve, vagy amelyik az egyik saját oldaláról érkezik. A profil pontosan egy oldalhoz tárolja a fejléceket, ugyanúgy titkosítva, ahogy a fiókjaid kulcsait, és a KnightLoader minden onnan induló letöltéssel elküldi őket.`,"settings.headerProfiles.empty":`Még nincs fejlécprofil.`,"settings.headerProfiles.emptyHint":`Akkor éri meg egyet létrehozni, amint egy letöltés csak addig működik, amíg a böngészőben be vagy jelentkezve.`,"settings.headerProfiles.add":`Profil hozzáadása`,"settings.headerProfiles.name":`Profil neve`,"settings.headerProfiles.nameHint":`Ezen a néven hivatkozol erre a profilra, Packagizer-szabályban éppúgy, mint itt. Csak betű, számjegy és - _ vagy . lehet benne.`,"settings.headerProfiles.namePlaceholder":`pl. forum`,"settings.headerProfiles.origin":`Oldal`,"settings.headerProfiles.originHint":`Illeszd be annak az oldalnak a címét, ahonnan a fejléceket másoltad. A másik port és a https helyett a http más oldalnak számít, és saját profil kell hozzá. Az aldomaint nem fedi le a fődomain profilja.`,"settings.headerProfiles.headers":`Fejlécek`,"settings.headerProfiles.headerName":`Név`,"settings.headerProfiles.headerValue":`Érték`,"settings.headerProfiles.valueStored":`Tárolva`,"settings.headerProfiles.valueStoredHint":`Az érték ezen a példányon marad, és soha nem küldjük vissza erre az oldalra. Hagyd a mezőt úgy, ahogy van, ha meg akarod tartani, vagy írj be új értéket, ha le akarod cserélni.`,"settings.headerProfiles.error.originInvalid":`Ez nem http- vagy https-cím. Illeszd be az oldal címét, például https://forum.example.org.`,"settings.headerProfiles.error.originTaken":`A(z) „{profile}” profil már lefedi ezt az oldalt. Szerkeszd azt, vagy előbb töröld.`,"settings.headerProfiles.error.nameNeeded":`Ezt az oldalt még egy profil sem fedi le, ezért adj ennek egy nevet.`,"settings.headerProfiles.error.nameInvalid":`Egy profilnév csak betűket, számjegyeket és - _ vagy . jelet tartalmazhat, legfeljebb 64 karaktert.`,"settings.headerProfiles.error.noHeaders":`Adj hozzá legalább egy fejlécet értékkel, vagy töröld a profilt.`,"settings.headerProfiles.addHeader":`Fejléc hozzáadása`,"settings.headerProfiles.removeHeader":`A fejléc eltávolítása`,"settings.headerProfiles.count":`{n} fejléc`,"settings.headerProfiles.save":`Profil mentése`,"settings.headerProfiles.delete":`Profil törlése`,"settings.headerProfiles.deleteConfirm":`Törlöd a(z) {id} profilt? A benne lévő fejlécek eltűnnek, és a(z) {origin} oldalról induló letöltések megint nélkülük indulnak.`,"settings.rules.action.category":`Kategória`,"settings.rules.action.categoryHint":`Az illeszkedő hivatkozásokat a lejjebb, ezen az oldalon található Kategóriák lista egyik fiókjába sorolja, amely a saját mappáját, sorbeli helyét, kibontási kapcsolóját és ütközési szabályát is magával hozza. Változatlanul hagyva egyetlen szabálynak sincs róla véleménye, és a hivatkozás besorolás nélkül marad. Ha ez a szabály letöltési mappát is megnevez, az a mappa nyer, a fiók pedig továbbra is mindent mást ad hozzá. A törölt fiók megnevezését mentéskor elutasítjuk, mert az a szabály, amelyik nem létező fiókra mutat, minden illeszkedő hivatkozásnál egyáltalán semmit nem tesz, csendben.`,"settings.rules.action.categoryNone":`Még nincs kategória. Előbb hozz létre egyet lejjebb ezen az oldalon, a Kategóriák alatt, különben ez a szabály olyan fiókba sorolná a hivatkozásokat, amelyik nem létezik.`,"settings.rules.action.categoryMissing":`{id} (törölve)`,"settings.resolvers.cookieJars":`Tárolt fájlok`,"settings.resolvers.cookieJarsHint":`A tárolt fájlt soha nem mutatjuk meg újra: élő, bejelentkezett munkamenet, ezért mindig csak egy irányba halad, ebbe a kiszolgálóba. Ha le akarod cserélni, illeszd fölé az újat.`,"settings.resolvers.cookieHost":`Oldal`,"settings.resolvers.cookieHostPlaceholder":`youtube.com, vagy az a cím, ahonnan a fájlt exportáltad`,"settings.resolvers.cookieText":`cookies.txt`,"settings.resolvers.cookieTextPlaceholder":`Illeszd be ide az exportált cookies.txt fájlt`,"settings.resolvers.cookieSave":`Fájl tárolása`,"settings.resolvers.cookieRemove":`Eltávolítás`,"settings.resolvers.cookieRemoveConfirm":`Eltávolítod a(z) {host} oldalhoz tárolt fájlt? Az arról az oldalról induló letöltések megint névtelenül futnak.`,"settings.resolvers.cookieEmpty":`Egyetlen oldalhoz sincs még tárolt fájl.`,"settings.resolvers.cookieStored":`Tárolva`,"detail.label":`Feladat részletei`,"detail.link":`Link`,"detail.address":`Cím`,"detail.addressHint":`Az a cím, amelyről ez a letöltés indult. Ezt kérte az alkalmazás, és ez nem mindig az a hely, ahonnan a bájtok jöttek: egy debrid szolgáltatáson keresztül a lenti tárhely az az oldal, amelyen a fájl fekszik, a backend pedig az, aki lehozta.`,"detail.copy":`Másolás`,"detail.copied":`Másolva`,"detail.copyFailed":`Semmi nem lett kimásolva.`,"detail.origin":`Így érkezett`,"detail.originUnknown":`Nincs feljegyezve`,"detail.package":`Csomag`,"detail.noPackage":`Nincs csomagban`,"detail.onDisk":`Jelenleg a lemezen`,"detail.onDiskHint":`Mekkora a fájl ebben a másodpercben a lemezen, a kiszolgálótól kérdezve, nem itt számolva. A futó letöltés két pillantás között is nő, és ez nem az a méret, amelyet a tárhely bejelentett.`,"detail.mirrorOf":`Ennek a tartalék másolata`,"detail.times":`Időbélyegek`,"detail.timesHint":`Mikor érkezett meg ez a link, mikor változott utoljára, és mikor lett kész. Az nem szerepel, mikor indult az átvitel: az alkalmazás ezt soha nem jegyzi fel, a másik háromból megtippelt érték pedig olyan szám lenne, amire az emberek építenének.`,"detail.nextTry":`Következő próbálkozás`,"detail.stalledSince":`Az elakadás kezdete`,"detail.retries":`Eddigi újrapróbálkozások`,"detail.retriesHint":`Hányszor indult újra ez a letöltés egy hiba után. Abban a pillanatban nullázódik, amikor a letöltés elkészül, a kész sorban tehát nulla áll akkor is, ha négy nekifutás kellett. Hogy hány próbálkozás van még hátra, itt nem látszik: a felső határ az októl és a tárhelytől függ, és ezt az oldal nem tudja kiszámolni.`,"detail.stallRestarts":`Újraindítások elakadás után`,"detail.stallRestartsHint":`Hányszor indította el magától újra ezt a letöltést az elakadásfigyelő. Nullázódik, amint a letöltés elkészül, ugyanúgy, mint a fenti számláló.`,"detail.failure":`Mi ment félre`,"detail.cause":`Ok`,"detail.message":`Amit a backend mondott`,"detail.messageHint":`Annak a mondata, ami ezt megpróbálta lehozni, szó szerint és lefordítatlanul. Ez az aktuális hiba és semmi más: egy újraindítás törli, a korábbiakat pedig sehol nem őrizzük meg.`,"detail.heldBack":`Ez tartja vissza`,"detail.doing":`Épp ezt csinálja`,"detail.gaveUp":`Nincs több próbálkozás`,"detail.gaveUpHint":`Itt szándékosan van vége, nem azért, mert elfogytak a próbálkozások: egy captcha, egy megtelt lemez vagy egy szabály, amelyik erre a tárhelyre azt mondja, hogy soha. Az újrapróbálkozások számának emelése ezen semmit nem változtat. Magát a jelölést nem írjuk az adatbázisba, egy újraindítás után tehát eltűnik, az oka viszont megmarad.`,"detail.rules":`Szabályok, amelyek ezt formálták`,"detail.rulesHint":`Azok a szabályok, amelyek az előkészítéskor lefutottak erre a linkre, abban a sorrendben, ahogy lefutottak. Néven vannak feljegyezve: az azóta átnevezett szabályt már nem találjuk meg, a soha nem nevezett szabály pedig azzal a hellyel szerepel, amely akkor volt neki. Egy kattintás megnyitja a szabályszerkesztőben.`,"detail.openRule":`Megnyitás a szabályszerkesztőben`,"detail.noRules":`Egyetlen szabály sem nyúlt ehhez a linkhez.`,"detail.player":`Lejátszás`,"detail.play":`Lejátszás itt`,"detail.playHint":`Egyenesen erről a példányról játssza le a fájlt, anélkül hogy másodszor is letöltenéd. A lejátszás megnyomásáig semmit nem hozunk le, és a fájl ott marad, ahol van.`,"detail.playPartial":`Ez a letöltés még nincs kész. Csak az a rész játszható le, amelyik már a lemezen van, azon túlra ugrani nem lehet, és van olyan fájl, amelyik egyáltalán semmit nem játszik le, amíg az utolsó bájt meg nem érkezik.`,"detail.playUnsupported":`Ez a böngésző nem tudja lejátszani ezt a fájlt. Nyisd meg vagy mentsd el helyette a jobbklikk menüből.`,"detail.playRemote":`Csak az ezen a példányon lévő fájlok játszhatók le itt. Egy másik példány egy darabban és ugrás nélkül adja át a fájljait, ezzel pedig egy lejátszó nem tud mit kezdeni.`,"detail.playNotLocal":`Ezt a letöltést a JDownloader hozta le, a fájl tehát annak a folyamatnak a lemezén van, nem ezen.`,"detail.playNoFile":`A lemezen még nincs semmi, amit le lehetne játszani.`,"detail.playRefused":`A kiszolgáló nem adja ki ezt a fájlt: {reason}`,"detail.playFailed":`A lejátszás megállt: {reason}`,"detail.playClose":`A lejátszó bezárása`,"settings.rules.notFound":`Itt egyetlen szabályt sem hívnak így: „{name}”. Átnevezték vagy törölték, mióta hozzáadtuk azt a linket, amelyik megnevezi.`,"notifications.title":`Értesítések`,"notifications.titleHint":`Eseményenként döntsd el, hogy buborékként jelenjen-e meg az alkalmazásban, az operációs rendszered üzeneteként, vagy sehogy. A rendszerüzenet csak addig ér el, amíg egy KnightLoader-lap nyitva van, és a lenti csendes mód ezen felül is érvényes.`,"notifications.channel.app":`Az alkalmazásban`,"notifications.channel.system":`Rendszerüzenet`,"notifications.channel.silent":`Ne mutasson semmit`,"notifications.event.downloadDone":`Letöltés kész`,"notifications.event.downloadDoneHint":`Minden letöltés jelez, amelyik végigfut. Kétszáz fájl a sorban kétszáz ilyen üzenetet jelent, gondold meg tehát jól, mielőtt a rendszerre bízod őket.`,"notifications.event.downloadFailed":`Letöltés sikertelen`,"notifications.event.downloadFailedHint":`Egy letöltés, amelyik feladta. A csendes mód ezt soha nem rejti el.`,"notifications.event.extractionDone":`Kibontás kész`,"notifications.event.extractionDoneHint":`Egy archívum, amelyik készen van a kibontással. Ezt eddig sehol nem jelentettük, ezért kezdetben a „Ne mutasson semmit” állapotban áll.`,"notifications.event.extractionFailed":`Kibontás sikertelen`,"notifications.event.extractionFailedHint":`Egy archívum, amelyik félbeszakadt. Rendszerint a jelszó hiányzik, és a fájlok addig fekve maradnak, amíg nem foglalkozol velük.`,"notifications.event.captchaWaiting":`Egy captcha vár`,"notifications.event.captchaWaitingHint":`A captcha ablaka így is, úgy is megnyílik ezen a lapon. Kezdetben a „Ne mutasson semmit” állapotban áll, mert amíg odanézel, maga az az ablak az üzenet. Állítsd rendszerüzenetre, és egy háttérlapon várakozó captcha is elér, mielőtt a tárhely eldobja a munkamenetet.`,"notifications.event.captchaFailed":`Captcha sikertelen`,"notifications.event.captchaFailedHint":`Senki nem válaszolt időben, vagy a válasz nem jutott át. A mögötte lévő letöltés fekve marad.`,"notifications.event.captchaResolved":`A captchát máshol oldották meg`,"notifications.event.captchaResolvedHint":`Valaki egy másik böngészőben vagy egy automatikus megfejtő megválaszolta, és az ablak magától bezárult.`,"notifications.systemUnavailable":`Itt nincsenek rendszerüzenetek: a böngésző csak HTTPS-en vagy localhoston kínálja fel őket. Ezen a kártyán minden így is megjelenik az alkalmazásban.`,"notifications.systemBlocked":`A böngésző blokkolja az értesítéseket erre a címre. A „Rendszerüzenet” állapotú sorok addig az alkalmazásban jelennek meg, amíg a böngésződ webhelybeállításaiban újra nem engedélyezed őket.`,"notifications.systemNotGranted":`A böngésző nem adta meg az engedélyt, ezért ez az esemény az alkalmazásban marad. Válaszd újra a „Rendszerüzenet” lehetőséget, hogy még egyszer rákérdezzen.`,"notifications.test":`Teszt küldése`,"notifications.testBody":`Így néz ki egy KnightLoader-értesítés.`,"captcha.waiting":`A(z) {host} captchája válaszra vár.`,"archive.doneToast":`A(z) {name} kibontása kész.`,"archive.failedToast":`A(z) {name} kibontása nem sikerült.`,"settings.search.placeholder":`Keresés minden beállításban…`,"settings.search.hint":`A beállítások minden szakaszában keres: a szakasznevekben, a kártyacímekben, a vezérlők melletti feliratokban és az (i) mögötti magyarázatokban. Ha kiválasztasz egy találatot, megnyitjuk a szakaszt, és kiemeljük a sort. A beállított értékekben nem keres: arra a Haladó oldal mezője való.`,"settings.search.clear":`Keresés törlése`,"settings.search.noMatch":`Semmi nem illik rá.`,"settings.search.results":`Keresési találatok`,"settings.search.countOne":`1 találat`,"settings.search.count":`{n} találat`,"settings.search.inHint":`a magyarázatban található`,"settings.search.section":`Szakasz`,"settings.search.rowHidden":`A(z) {card} nyitva van. Ez a sor most nem látszik a képernyőn.`,"settings.search.command":`Keresés minden beállításban`,"views.label":`Mentett nézetek`,"views.save":`A nézet mentése`,"views.saveHint":`A nézet az a keresés és azok a szűrők, amelyeket éppen beállítottál, egy általad választott néven elmentve. Az oszlopok és a rendezés nem tartoznak bele, azokat külön jegyezzük meg.`,"views.saveTitle":`A nézet elnevezése`,"views.nameLabel":`Név`,"views.namePlaceholder":`Nagy fájlok a múlt hétről`,"views.saveConfirm":`Nézet mentése`,"views.overwriteConfirm":`Nézet felülírása`,"views.full":`{n} mentett nézeted van, ennél többet ez a lista nem tart meg. Törölj egyet, és megint lesz hely.`,"views.tooBig":`Ebben a nézetben több szűrőérték van, mint amennyit el lehet tárolni. Vegyél ki néhány pipát az oldalsávban, és mentsd el újra.`,"views.manage":`Mentett nézetek kezelése`,"views.rename":`Átnevezés`,"views.renameTitle":`A nézet átnevezése`,"views.delete":`Törlés`,"views.deleteTitle":`Törlöd a(z) „{name}” nézetet?`,"views.deleteBody":`A nézet csak egy név egy kereséshez és néhány szűrőhöz. A törlésével semmi nem változik a listában, és egyetlen link sem tűnik el.`,"views.deleteConfirm":`Nézet törlése`,"views.clearAll":`A keresés és minden szűrő törlése`,"views.clearAllHint":`A keresés és a szűrők akkor is beállítva maradnak, ha elhagyod ezt az oldalt, és visszajössz, tehát azt a listát látod megint, amelyet otthagytál. Ezzel az egész listát hozod vissza. A mentett nézetekhez nem nyúl.`,"disk.title":`Célmappák`,"disk.hint":`Szabad és foglalt hely minden mappán, ahova egy letöltés érkezhet, és az a mennyiség, amelyet a sor még bele akar írni. Az értékek ugyanabból a lekérdezésből származnak, amellyel a lemezhatárokat is ellenőrizzük, és legfeljebb néhány másodpercesek. A szabad és a foglalt nem mindig adja ki a kötet méretét: a fájlrendszer egy szeletet fenntart a rendszernek, egy felhasználónkénti kvóta pedig kevesebbet hagyhat ennek a példánynak, mint amennyi a köteten valójában van. Az ugyanazon a lemezen lévő két mappa ugyanazt a lemezt mutatja, a sorokat tehát soha ne add össze.`,"disk.free":`Szabad`,"disk.used":`Foglalt`,"disk.size":`A kötet mérete`,"disk.queued":`Még ide íródik`,"disk.queuedHint":`Amennyit a még hátralévő letöltések ebbe a mappába írnának: az a méret, amelyet a tárhely megnevezett, mínusz az, ami már megérkezett. Az a letöltés, amelynek a méretét a tárhely nem árulja el, itt nullaként számít, ez a szám tehát alsó határ és soha nem ígéret, és ezért állhat nulla bájt egy egész sor letöltés mellett. A kikapcsolt letöltések kimaradnak, ugyanaz a szabály, mint a lista alatti összesítőknél. Az a letöltés, amelyik már fut, a helyét rendszerint az indulás pillanatában lefoglalta a lemezen, a bájtjai tehát már hiányoznak a mellette álló szabad helyből, és nem jönnek rá még egyszer.`,"disk.tasks":`{n} letöltés`,"disk.unknown":`Ez a rendszer nem jelent szabad helyet`,"disk.unknownHint":`Nem minden kerneltől lehet megkérdezni, mennyi hely maradt egy köteten, és ennek a buildnek nincs ilyen hívása ahhoz a kernelhez, amelyen éppen fut. Ahol hiányzik a válasz, ott semmit nem tartunk vissza: a letöltések úgy indulnak, mintha nem lenne lemezkorlát beállítva. Ez a sor azért van itt, hogy ezt meg tudd különböztetni egy valóban megtelt lemeztől.`,"disk.missing":`Még nincs létrehozva`,"disk.missingHint":`Ezt a mappát az hozza létre, aki az első fájlt beleírja, tehát még nincs meg. Az értékek a(z) {path} mappát írják le, a legközelebbi meglévő mappát felette, és az azon a köteten van, amelyre a letöltés érkezne.`,"disk.measured":`Itt mérve: {path}`,"disk.elsewhereHint":`Magát a mappát nem sikerült megmérni, ezért a felette lévő legközelebbit mértük meg. Ha egy csatolás nem jött fel, ez egészen más lemez lehet, mint amelyikre a letöltés készül. Nézd meg az útvonalat, mielőtt bármit kiolvasnál a számokból.`,"disk.sampled":`{n} másodperce olvasva`,"disk.tight":`A sor nem fér el`,"disk.tightHint":`Ebbe a mappába több van hátra, mint amennyi a köteten szabad. Ez a sor önmagában semmit nem állít le: visszatartani egyesével tartunk vissza, amikor egy letöltés sorra kerül, a Letöltések beállítási oldal számai szerint. Az a letöltés pedig, amelynek a méretét senki nem ismeri, itt egyáltalán nem számít bele.`,"disk.truncated":`Nem minden mappa szerepel itt`,"disk.truncatedHint":`A sor a beállítottakon kívül több mappára irányul, mint amennyit minden egyes lekérdezésnél érdemes megmérni, ezért a legkevesebbet váró mappák kimaradtak. Minden mappa, amelyet te állítottál be, mindig itt van.`,"disk.markLow":`Ez alatt semmi új nem indul el`,"disk.markStop":`Ez alatt minden leáll`,"disk.limits":`A lemezhatárok beállítása`,"disk.stripLabel":`Hely a célmappákon`,"disk.role.downloads":`Letöltési mappa`,"disk.role.category":`Kategóriamappa`,"disk.role.work":`Munkamappa`,"disk.role.task":`Magán a letöltésen beállítva`,"settings.volume.title":`Forgalmi keret`,"settings.volume.titleHint":`Amit ez a példány készre töltött, egy általad beállított kerethez mérve, időszakonként. Azt a méretet számoljuk, amelyet a tárhely a kész letöltéshez megnevezett: ami méret nélkül lett kész, az nullaként számít, amit pedig egy torrent feltölt, egyáltalán nem számít. Ez a letöltéseid kiértékelése, nem a vonalad mérése: azt, hogy a routered valójában mennyi bájtot mozgatott meg, itt senki nem látja.`,"settings.volume.cap":`Keret időszakonként (GB)`,"settings.volume.capHint":`A 0 azt jelenti, hogy nincs keret: a számláló tovább fut, és soha semmit nem tartunk vissza. A gigabájtot itt tízes alapon számoljuk, ahogy egy szolgáltató is megadja a keretet: 500 GB az 500 000 000 000 bájt, nem 465 GiB. Az oldal feljebbi lemezértékei bináris GiB-ben állnak, az másik egység egy másik kérdéshez.`,"settings.volume.resetDay":`A számláló ezen a napon indul újra`,"settings.volume.resetDayHint":`A hónapnak az a napja, amelyen a számláló megint nulláról indul, rendszerint az a nap, amelyen a kereted megújul. Az olyan hónapban, amelyik rövidebb a választott napnál, a hónap utolsó napján indul újra, és soha nem csúszik át a következőbe. A kiszolgáló órája szerint számoljuk, nem a böngésződé szerint, mert a sort a kiszolgáló tartja vissza.`,"settings.volume.action":`Ha a keret betelt`,"settings.volume.actionHint":`A már futó átvitelt soha nem szakítjuk meg, bármit is választasz: a fájl közepén megállni annyi, mint eldobni a már elköltött bájtokat. A „Csak szólj” semmit nem változtat, akkor a számláló az egész funkció. A „Ne induljon több letöltés” hagyja végigfutni, ami fut, és visszatartja a sort, amíg a számláló újra nem indul; minden várakozó sor ezt is mondja majd. A „Minden lassítása” tovább viszi a sort, a lenti tempóval.`,"settings.volume.actionReport":`Csak szólj`,"settings.volume.actionPause":`Ne induljon több letöltés`,"settings.volume.actionThrottle":`Minden lassítása`,"settings.volume.throttle":`Sebesség a korlát után`,"settings.volume.throttleHint":`Az a tempó, amely az időszak hátralévő részére érvényes. A többi korlátod mellett álló felső határ, és soha nem azok helyett: az éjszakai idősáv vagy a kevesebbet kérő csendes kapcsoló továbbra is nyer. A 0 itt azt jelentené, hogy egyáltalán nincs korlát, ez pedig ugyanaz, mintha nem lenne keret, a legkisebb értelmes szám tehát az 1.`,"settings.volume.noCap":`Nincs keret`,"settings.volume.used":`Ebben az időszakban letöltve`,"settings.volume.usedOf":`{cap} keretből {used}`,"settings.volume.resetsOn":`Újraindul ekkor: {date}`,"settings.volume.reached":`A keret betelt.`,"volume.title":`Letöltött forgalom`,"volume.titleHint":`A kész letöltések naponként és hónaponként összeadva, a letöltési előzményekből. Az előzményeknek saját felső határuk van, és kézzel is üríthetők, a végükről kiesett hónapok tehát egyszerűen nincsenek itt. Az újraindított letöltés egyszer számít, azon a napon, amelyen utoljára készen lett. A naptár a kiszolgálóé, {zone} szerint.`,"volume.range.days":`30 nap`,"volume.range.months":`12 hónap`,"volume.split.total":`Minden`,"volume.split.host":`Tárhely szerint`,"volume.split.backend":`Backend szerint`,"volume.other":`Minden más`,"volume.empty":`Ebben az időszakban még semmi nem lett kész.`,"volume.unsizedHint":`Ezek közül {n} letöltésnél a tárhely soha nem nevezett meg méretet. Ezek semmit nem adnak az összeghez, a valódi érték tehát magasabb az itt rajzoltnál.`,"volume.trimmedHint":`Az előzmények elérték a saját határukat, minden, ami a legrégebbi bejegyzésüknél korábbi, ebből a görbéből is hiányzik. Emeld meg ezen az oldalon az előzmények felső határát, ha hosszabb feljegyzést szeretnél.`,"volume.meter":`Forgalom`,"volume.meterHint":`Ami a számláló legutóbbi újraindulása óta készre töltődött, a Letöltések beállítási oldal keretéhez mérve. A szám akkor mozdul, amikor egy letöltés elkészül, nem futás közben. A letöltési előzményekből adódik össze, így ha kiüríted az előzményeket, ez a számláló is nullázódik.`,"task.waiting.volumeCap":`A forgalmi keretre vár`,"task.waiting.module":`Modul kikapcsolva`,"task.reason.botCheck":`Botellenőrzés`,"task.reason.membersOnly":`Csak tagoknak`,"task.reason.geoBlocked":`Itt tiltva`,"task.reason.drm":`DRM`,"task.reason.extractorBroken":`Az oldal megváltozott`,"events.title":`Események`,"events.open":`Eseménylista megnyitása`,"events.titleHint":`Minden értesítés, amelyet ez az ablak mutat neked, ide is bekerül. Így azt is elolvashatod, amelyiknek a buborékja már eltűnt. Az utolsó {max} marad meg, és a lista minden oldalbetöltéskor elölről kezdődik.`,"events.unread":`{n} olvasatlan`,"events.empty":`Még nem történt semmi`,"events.emptyHint":`Amit a KnightLoader legközelebb jelent neked, az itt fog állni.`,"events.noMatch":`Ebből a fajtából semmi nincs a listában`,"events.filterLabel":`Fajta`,"events.kind.downloads":`Letöltések`,"events.kind.archives":`Archívumok`,"events.kind.captcha":`Captchák`,"events.kind.accounts":`Fiókok`,"events.kind.actions":`Műveletek`,"events.clear":`Lista ürítése`,"events.jump":`A sor megmutatása`,"events.jumpGone":`Ez a letöltés már nincs a listában`,"commands.openEvents":`Eseménylista megnyitása`,"settings.shortcuts.listTitle":`A lista billentyűi`,"settings.shortcuts.listHint":`Ezek a letöltési listához és a gyűjtő linklistájához tartoznak, és nem lehet őket újra kiosztani. Csak addig hatnak, amíg egy soron van a fókusz, ezért egyik sem vesz el billentyűt a fentebbi parancsoktól.`,"keys.list.move":`Lépés sorról sorra`,"keys.list.moveKeep":`Lépés a kijelölés változtatása nélkül`,"keys.list.edges":`Ugrás az első vagy az utolsó sorra`,"keys.list.pick":`A sor hozzávétele a kijelöléshez vagy kivétele belőle`,"keys.list.range":`A kijelölés kiterjesztése addig a sorig, ahova lépsz`,"keys.list.properties":`A kijelöltek tulajdonságainak megnyitása`,"keys.list.open":`Mappa kinyitása vagy lépés a benne lévő első linkre`,"keys.list.close":`Mappa becsukása vagy lépés egy linkről a mappájára`,"keys.list.menu":`A sorhoz tartozó menü megnyitása`,"settings.shortcuts.key.home":`Home`,"settings.shortcuts.key.end":`End`,"settings.shortcuts.key.delete":`Del`,"task.retry.pending":`{max} próbálkozásból a(z) {n}., a következő {countdown} múlva`,"task.retry.pendingNoMax":`{n}. próbálkozás, a következő {countdown} múlva`,"task.retry.due":`{max} próbálkozásból a(z) {n}., most esedékes`,"task.retry.dueNoMax":`{n}. próbálkozás, most esedékes`,"task.retry.compact":`{n}/{max} · {countdown}`,"task.retry.compactNoMax":`{n} · {countdown}`,"task.retry.exhausted":`Nincs több újrapróbálkozás, {max} próbálkozásból {n} elhasználva`,"task.retry.exhaustedNoMax":`Nincs több újrapróbálkozás, {n} elhasználva`,"task.retry.gaveUp":`Nem próbáljuk meg még egyszer`,"task.retry.skip":`Újrapróbálkozás most`,"task.retry.skipDetail":`A várakozás vége helyett azonnal elindítja a linket. A számláló tovább fut: ez az az újrapróbálkozás, amelyik amúgy is be volt tervezve, nem egy ráadás.`,"task.retry.skipFailed":`Az újrapróbálkozást nem sikerült elindítani.`,"volume.rangeLabel":`Időszak`,"volume.splitLabel":`Felosztás`,"failure.title":`Miért nem sikerült`,"failure.open":`Miért nem sikerült`,"failure.raw":`Amit a backend mondott`,"failure.rawHint":`Az a sor, amelyet maga az eszköz írt ki, változatlanul és angolul. Jól jön, ha rákeresel, vagy ha valahol bejelented. A fölötte lévő mondat ennek az alkalmazásnak az olvasata.`,"failure.nothingToDo":`A KnightLoaderben semmi nem változtat ezen.`,"failure.close":`Bezárás`,"failure.botCheck.line":`Az oldal bejelentkezett munkamenetet kér, mielőtt kiadná a videót.`,"failure.botCheck.hint":`A várakozás, a lassabb letöltés vagy egy másik böngészőazonosító itt semmin nem változtat. Csak az olyan böngészőből származó sütik segítenek, amelyikben tényleg be vagy jelentkezve. Exportáld az oldal cookies.txt fájlját abból a böngészőből, és illeszd be ide: a titkosított hitelesítőtárba kerül, a yt-dlp olyan fájlként kapja meg, amelyet csak ez a kiszolgáló tud olvasni, és a letöltés végén azonnal törlődik.`,"failure.botCheck.action":`Sütik tárolása ehhez az oldalhoz`,"failure.membersOnly.line":`Csak tagoknak szól, a letöltés pedig tagság nélkül érkezett.`,"failure.membersOnly.hint":`A yt-dlp annak érkezik meg, akinek a tárolt sütik mondják. Jelentkezz be azzal a fiókkal, amelyiken a tagság van, exportáld abból a böngészőből az oldal cookies.txt fájlját, és illeszd be. Ha azon a fiókon nincs tagság, itt semmi nem változtat a válaszon.`,"failure.membersOnly.action":`Sütik tárolása ehhez az oldalhoz`,"failure.geoBlocked.line":`Az oldal ebbe a régióba nem szolgálja ki ezt a videót.`,"failure.geoBlocked.hint":`A sütik nem segítenek, mert a cím van letiltva, nem a fiók. A KnightLoader egy yt-dlp letöltést a saját megnevezett kapcsolatain sem tud átküldeni, mert a yt-dlp külön folyamatként fut, és a proxyját abból a környezetből veszi, amelyben ez a kiszolgáló elindult. A megoldás tehát ezen az ablakon kívül van: indítsd a kiszolgálót VPN mögött, vagy állítsd be neki a HTTP_PROXY és a HTTPS_PROXY változót.`,"failure.gone.line":`A forrás szerint ez már nincs meg.`,"failure.gone.hint":`A forrásnál törölték, eltávolították vagy privátra állították. Semmilyen fiók és semmilyen újrapróbálkozás nem hozza vissza, minden további próbálkozás csak arra kéri a tárhelyet, hogy ugyanazt a választ ismételje meg. Az eltávolítás leveszi a sort a listáról, ami pedig már letöltődött, az a lemezen marad.`,"failure.gone.action":`A link eltávolítása`,"failure.drm.line":`Ez a videó titkosított, és a yt-dlp nem fejti vissza.`,"failure.drm.hint":`A DRM nem olyan zár, amelyen egy bejelentkezés vagy egy másik cím átjut: az adat titkosítva érkezik, a kulcsot pedig csak olyan lejátszó kapja meg, amelyikben az oldal megbízik. Ehhez nincs mit beállítani. Ugyanannak a linknek a többi sorát, a bélyegképet, a leírást és a feliratot ez rendszerint nem érinti, azok maradhatnak.`,"failure.drm.action":`A link eltávolítása`,"failure.extractorBroken.line":`Az oldal megváltozott, és ennek a buildnek a yt-dlp-je már nem tudja kihozni a videót.`,"failure.extractorBroken.hint":`Ezt a yt-dlp maga mondta: nem tudta elolvasni az oldalt, és hibabejelentést kért. Szinte mindig az oldal mozdított el valamit, és egy újabb yt-dlp néhány napon belül megint elboldogul vele. A yt-dlp a KnightLoader konténerképében utazik, az újabb változathoz vezető út tehát egy újabb konténerkép, nem egy gomb itt bent: ez a kiszolgáló nem cserélheti le, és egy konténerben nem is lenne hova tennie egy új példányt.`,"cookies.title":`A(z) {host} sütijei`,"cookies.addTitle":`Sütik tárolása egy oldalhoz`,"cookies.add":`Oldal hozzáadása`,"cookies.save":`Mentés és újrapróbálkozás`,"cookies.saved":`A sütik tárolva.`,"cookies.hostHint":`A fájlt ehhez a hoszthoz keressük, és minden fölötte álló domainhez is, a szűkebbtől az általánosabb felé. A youtube.com alatt mentett fájl tehát egy music.youtube.com linkhez is érvényes. A kiszolgáló kisbetűsíti a nevet, elhagyja a vezető www. részt, és egy egész beillesztett címet magára az oldalra rövidít, ezért a lista kicsit másként nevezheti, mint ahogy beírtad.`,"cookies.jarHint":`Illeszd be, amit egy sütiexportáló ad, Netscape formátumban, a megjegyzéssorokkal együtt. Pontosan úgy tároljuk, ahogy beillesztetted: egy olyan fájl átformálásából, amelyet a yt-dlp mindjárt elolvas, az lesz, hogy a fájl az egyik eszközben működik, a másikban meg nem.`,"cookies.useStoredHint":`Egy kapcsoló az egész példányra, nem erre a linkre: ha ki van kapcsolva, a tárolt fájl sehova nem megy el, és itt beilleszteni sem változtat semmin. Ahhoz tartozik, amit a Mentés csinál, és nem a beállítás élő kijelzése: azt látod, amit ez az ablak mindjárt maga után hagy. Kapcsoló és nem automatizmus, mert egy bejelentkezett munkamenetnek következményei vannak: a sebességkorlát vagy a kitiltás a fiókot éri, nem a címet.`,"select.hidden":`ebből {n} nem látszik`,"select.hiddenTip":`A kijelölésben olyan sorok is benne vannak, amelyeket a keresés, egy szűrő vagy egy összecsukott csomag épp elrejt. A Del azokat is elviszi. Kattints a számra, és csak azok a sorok maradnak, amelyeket látsz.`,"select.reduceKeep":`Csak a látható sorok megtartása`,"select.reduceKeepAria":`{n} kijelölt sor nem látszik. Kattints, hogy csak a láthatók maradjanak kijelölve.`,"select.reduceRemove":`Csak a látható sorok eltávolítása`,"select.reduceRemoveAria":`Az eltávolítandó sorok közül {n} nem látszik. Kattints, hogy csak a láthatókat távolítsd el.`,"select.reduced":`{n} sor kikerült a kijelölésből.`,"remove.doneHidden":`{n} letöltés eltávolítva. Ebből {hidden} nem is látszott.`,"settings.dbmaint.title":`Adatbázis-karbantartás`,"settings.dbmaint.hint":`A feladatlista, a letöltési előzmények és a felület állapota együtt, egyetlen SQLite-fájlban van. A törölt sorok a fájlon belül szabadítanak fel helyet, a lemeznek soha nem adják vissza. Néhány év után a fájl ezért gyakran a tartalmának többszöröse. Az ellenőrzés minden lapot elolvas, és megmondja, hogy a fájl ép-e még. A zsugorítás a valódi méretére írja újra. Mindkettő az élő adatbázison fut, és addig minden más írást feltart.`,"settings.dbmaint.storeSize":`Adatbázisfájl`,"settings.dbmaint.storeSizeHint":`Az adatbázis, és mellette egy naplófájl, ha az SQLite éppen nyitva tart egyet.`,"settings.dbmaint.reclaimable":`Szabad a fájlon belül`,"settings.dbmaint.reclaimableHint":`Hely, amit a törölt sorok hagytak maguk után. Még mindig a lemezen lévő fájlhoz tartozik, és csak a zsugorítás adja vissza. A szám alsó határ: a zsugorítás a félig telt lapokat is újracsomagolja, így általában ennél több jön vissza.`,"settings.dbmaint.settingsSize":`settings.json`,"settings.dbmaint.settingsMissing":`Még nincs kiírva`,"settings.dbmaint.settingsMissingHint":`Ez a fájl csak akkor íródik ki, amikor először mentesz el egy beállítási oldalt. Addig a példány a beépített alapértékeken fut.`,"settings.dbmaint.inBundle":`Ezek a méretek a diagnosztikai csomagban is szerepelnek. Az útvonalak nem: a csomag arra való, hogy egy nyilvános hibajelentéshez lehessen csatolni.`,"settings.dbmaint.check":`Integritás ellenőrzése`,"settings.dbmaint.checkHint":`Elolvassa az adatbázis minden lapját, és jelenti, amit az SQLite talál. Csak olvas, semmit nem változtat. Nagy fájlnál ez eltart egy ideig, és közben semmi más nem tud az adatbázisba írni.`,"settings.dbmaint.compact":`Zsugorítás`,"settings.dbmaint.compactHint":`Az egész fájlt újraírja a valódi méretére. Ehhez az adatbázis egy teljes második másolatának is el kell férnie, és ez a másolat az ideiglenes mappába kerül, nem az adatmappába.`,"settings.dbmaint.analyze":`Lekérdezési statisztika frissítése`,"settings.dbmaint.analyzeHint":`Az SQLite újra felméri a táblákat, hogy jobb tervet válasszon a lista és az előzmények lekérdezéseihez. Gyors, és nem változtat adatot. Az ezelőtt előkészített lekérdezések megtartják a régi tervüket, a hatás tehát legkésőbb a következő újraindítás után teljes.`,"settings.dbmaint.running":`Fut…`,"settings.dbmaint.busy":`Már fut valami. Várd meg, amíg befejeződik.`,"settings.dbmaint.neverRun":`Ezen a példányon még semmi nem futott.`,"settings.dbmaint.lastRun":`Legutóbb {when}, {seconds} másodpercig tartott.`,"settings.dbmaint.checkOk":`Ép. Az SQLite minden lapot elolvasott, és nem talált semmi hibát.`,"settings.dbmaint.checkFailed":`Sérült. Az SQLite {n} problémát jelez.`,"settings.dbmaint.checkFailedHelp":`Ne indítsd újra a kiszolgálót. Olyan adatbázissal, amelyet nem tud megnyitni, egyáltalán nem indul el, egy magától újrainduló konténer pedig ilyenkor körbe-körbe jár. Előbb próbáld ki a „Biztonsági mentés letöltése” gombot az Általános oldal „Biztonsági mentés és átvitel” részében, és tedd a fájlt biztonságos helyre; erősen sérült adatbázisnál ez is meghiúsulhat. Ha meghiúsul, állítsd le a kiszolgálót, és kézzel másold félre a(z) {path} fájlt, mielőtt bármi más hozzányúlna, majd a „Biztonsági mentés feltöltése” gombbal hozd vissza az utolsó jó mentésedet.`,"settings.dbmaint.compacted":`Előtte {before}, utána {after}. {freed} visszakerült a lemezre.`,"settings.dbmaint.compactedNothing":`Előtte és utána is {before}. Nem volt mit visszaadni.`,"settings.dbmaint.analyzed":`A statisztika frissítve.`,"settings.dbmaint.failed":`Nem futott végig: {error}`,"settings.dbmaint.diskFullHelp":`A zsugorítás előbb egy teljes második másolatot ír az adatbázisról, és csak azután cseréli le az eredetit. Ez a másolat az ideiglenes mappába kerül, nem az adatmappába. Ez itt a(z) {tmp} mappa, ahol {free} szabad hely van. Mutass a TMPDIR változóval egy olyan mappára, amely ugyanazon a köteten van, mint az adatmappád, és próbáld újra.`,"settings.dbmaint.skippedBusy":`Az ütemezett futás elmaradt, mert letöltések futottak.`,"settings.dbmaint.interval":`Fusson magától`,"settings.dbmaint.intervalHint":`Meglévő telepítésen ki van kapcsolva, és frissítés után is kikapcsolva marad: semmi nem kezd magától futni csak azért, mert új verziót telepítettél. Ha bekapcsolod, az első futás egy egész időközzel később jön, nem most azonnal. Ha abban a pillanatban éppen tölt le valamit, a futás elmarad, és nem áll sorba.`,"settings.dbmaint.intervalNever":`Csak gombnyomásra`,"settings.dbmaint.interval30":`30 naponta`,"settings.dbmaint.interval90":`90 naponta`,"settings.dbmaint.interval180":`180 naponta`,"settings.dbmaint.nextRun":`Következő futás: {when}.`,"settings.dbmaint.compactOnSchedule":`Az ütemezett futás zsugorítson is`,"settings.dbmaint.compactOnScheduleHint":`Kikapcsolva az ütemezett futás csak olvas és jelent. A zsugorítás az egész fájlt újraírja, és ehhez egy második másolatnak is el kell férnie az ideiglenes köteten, ezért ne kapcsold be anélkül, hogy tudnád, megvan-e ez a hely. A fenti Zsugorítás gomb mindig zsugorít, ha megnyomod, bármi is áll itt.`,"settings.dbmaint.confirmTitle":`Zsugorítsuk az adatbázist?`,"settings.dbmaint.confirmBody":`A fájl teljesen újraíródik. Amíg ez el nem készül, semmi más nem tud beleírni, és egy {size} méretű fájlnál ez eltarthat egy ideig. A letöltések tovább futnak, de amit jelentenek, az csak utána íródik le.`,"settings.dbmaint.loadFailed":`Nem sikerült beolvasni az adatbázis méretét. Elérhető a kiszolgáló?`,"overview.speedWindow":`A görbe időablaka`,"overview.speedWindow.minute":`Utolsó perc`,"overview.speedWindow.hour":`Utolsó óra`,"overview.speedGraphHint":`A példány maga rögzíti ezt a görbét: másodpercenként egy mérési értéket az utolsó két percre, tíz másodpercenként egyet az utolsó órára. Ezért az oldal újratöltése után már kitöltve jelenik meg, ahelyett hogy laposan indulna. A rögzítés csak a memóriában él: ha újraindítod a KnightLoadert, üres lesz, a görbe megint egyenes vonalként indul, és futás közben töltődik fel.`,"settings.diagnostics.speedSamples":`Rögzített sebességértékek`,"settings.diagnostics.speedSamplesHint":`Hány értékből rajzolódik éppen az Áttekintés sebességgörbéje, ahhoz mérve, amennyit legfeljebb megtart: elöl a két perces rögzítés, utána az egyórás. Ha mindkettőnél nulla áll, semmi nem rögzít, és az Áttekintés görbéje lapos marad, amíg ez nincs orvosolva. A rögzítés minden újraindítás után üresen kezdődik, és soha nem íródik a lemezre.`,"settings.downloads.idleActionQuit":`Kilépés a KnightLoaderből`,"settings.downloads.idleActionCommand":`Parancs futtatása`,"settings.downloads.idleActionSuspend":`Ennek a gépnek az altatása`,"settings.downloads.idleDeploymentContainer":`Ez konténerben fut. A folyamata PID 1 a saját névterében: a kilépés a konténert állítja le és semmi mást, az alatta lévő gépet pedig nem tudja elaltatni, mert annak a gépnek az energiaállapotához a konténeren belülről semmi nem fér hozzá. Hogy a konténer a kilépés után visszatér-e, azt az általad megadott újraindítási szabály dönti el, nem ez a beállítás. Ha a gazdagépet szeretnéd elaltatni, olyan parancsot adj meg itt, amelyik eléri a gazdagépet.`,"settings.downloads.idleDeploymentDesktop":`Ez a desktop build, tehát el tudja altatni ezt a gépet. A kilépés itt nem választható, mert az ablak és a tálcaikon már amúgy is rendesen bezárja az alkalmazást.`,"settings.downloads.idleQuitHint":`A kilépés hagyja lefutni, ami még folyamatban van, majd leállítja a folyamatot, pontosan úgy, mint az Általános oldal Kilépés gombja. Hogy utána újraindul-e, azt a konténered újraindítási szabálya dönti el, nem ez a beállítás.`,"settings.downloads.idleSuspendHint":`Az altatás megkéri az operációs rendszert, hogy függessze fel ezt a gépet. Csak ott működik, ahol a rendszer engedi, hogy ez az alkalmazás kérje: Linuxon a jogosultságkezelő elutasíthatja, és akkor az indok a legutóbbi futás alatt jelenik meg.`,"settings.downloads.idleCommandProgram":`Program`,"settings.downloads.idleCommandProgramHint":`Annak a programnak a teljes útvonala, amelyik elindul. Közvetlenül fut, nem parancsértelmezőn keresztül, ezért a cső, az átirányítás vagy két egymás utáni parancs egy szkriptfájlba való, amelyre innen mutatsz. Semmit nem helyettesítünk be: ami itt áll, pontosan az fut le.`,"settings.downloads.idleCommandArgs":`Argumentumok`,"settings.downloads.idleCommandArgsHint":`Soronként egyet, így a szóközt tartalmazó argumentum egy argumentum marad.`,"settings.downloads.idleCommandTimeout":`Megszakítás ennyi után (másodperc)`,"settings.downloads.idleCommandTimeoutHint":`Meddig futhat a program, mielőtt leállítjuk. A leállítás nem ugyanaz, mint a meghiúsulás: egy gépet altató parancsot menet közben is le lehet lőni, a dolgát akkor is elvégezte.`,"settings.downloads.idleCommandSecretHint":`A parancssor nyílt szövegként áll a settings.json fájlban, és minden biztonsági mentéssel vándorol, ezért jelszó és token ne kerüljön bele: tedd olyan fájlba, amelyet csak a program olvas. A diagnosztikai csomagból kimarad, és ezen az oldalon sem mutatjuk vissza, ezért üres a fenti mező, amint el van mentve valami.`,"settings.downloads.idleCommandStored":`Egy parancs el van mentve, és itt nem mutatjuk vissza. Írj be valamit a lecseréléséhez.`,"settings.downloads.idleCommandStoredShort":`a tárolt parancs`,"settings.downloads.idleCommandVerify":`Mielőtt a visszaszámlálás megteszi`,"settings.downloads.idleCommandVerifyHint":`Az ellenőrzés csak feloldja a program útvonalát, és megmondja, mit talált, a megnyomása tehát semmibe nem kerül. A futtatás pontosan azt teszi, amit a visszaszámlálás tenne, ezen a példányon, azonnal. Mindkettő az elmentett állapotra kérdez rá, ezért előbb mentsd el az oldalt: amíg itt bármi mentetlen, a két gomb kikapcsolva marad.`,"settings.downloads.idleCommandCheck":`Parancs ellenőrzése`,"settings.downloads.idleCommandChecking":`Ellenőrzés…`,"settings.downloads.idleCommandCheckOk":`Megtaláltuk itt: {path}. Így indul: {argv}`,"settings.downloads.idleCommandRun":`Futtatás most`,"settings.downloads.idleCommandRunConfirm":`Ezzel a(z) {program} azonnal lefut ezen a példányon, pontosan úgy, ahogy a visszaszámlálás tenné.`,"settings.downloads.idleArmHint":`Ha úgy mented el ezt az oldalt, hogy a sor már üres, a visszaszámlálás azonnal elindul. Nem várja meg a következő menet végét.`,"idleAction.action.quit":`Kilépés folyamatban`,"idleAction.action.command":`Parancs futtatása folyamatban`,"idleAction.action.suspend":`A gép altatása folyamatban`,"idleAction.lastRun":`Legutóbbi futás`,"idleAction.lastRunHint":`A példány legutóbbi indulása óta. Itt semmi nem éli túl az újraindítást, egy sikerült kilépés tehát egyetlen sort sem hagy maga után: a bejegyzés a folyamattal együtt tűnt el.`,"idleAction.lastRunNever":`Ez még soha nem futott.`,"idleAction.lastRunOk":`Lefutott ekkor: {at}, és nem volt mit jelentenie.`,"idleAction.lastRunFailed":`Meghiúsult ekkor: {at}.`,"idleAction.problem.empty":`Nincs beírva program, tehát nincs mit futtatni. Írd be fent a program teljes útvonalát.`,"idleAction.problem.notFound":`A(z) {program} nincs meg ezen a példányon.`,"idleAction.problem.notFoundContainer":`A(z) {program} nincs meg ebben a konténerben. Itt csak az van, amit a konténerkép hoz magával: nincs systemd, nincs curl, nincs ssh, nincs sudo. Tedd a parancsot a gazdagépre, és innen hívd meg, vagy mutass itt egy szkriptre, amelyet becsatoltál a konténerbe.`,"idleAction.problem.notExecutable":`A(z) {path} megvan, de nem futtatható. Add rá a futtatási jogot, és gondoskodj róla, hogy az a felhasználó, amelyikkel ez a folyamat fut, olvashassa: a konténerben ez az uid 1000, nem a root.`,"idleAction.problem.permission":`A rendszer elutasította: ez a folyamat ezt nem teheti meg. A konténerben uid 1000 alatt fut, root nélkül és a gazdagéphez való hozzáférés nélkül, ezért mindennek, ami a gép energiaállapotát megváltoztatja, magán a gazdagépen kell megtörténnie.`,"idleAction.problem.timeout":`A program {seconds} másodperc után még futott, ezért leállítottuk. Könnyen lehet, hogy a dolgát így is elvégezte. Emeld feljebb a határt, ha a parancsnak tovább kell tartania.`,"idleAction.problem.exit":`A program {code} kilépési kóddal állt le. A saját kimenete: {output}`,"idleAction.problem.notSupported":`Ez a build ezt nem tudja végrehajtani. Válassz másik műveletet a sor végére.`,"idleAction.problem.suspendRefused":`A rendszer elutasította az altatást. Linuxon ez rendszerint a jogosultságkezelő, amelyik olyan megerősítést vár, amit ez az alkalmazás nem tud megadni: engedélyezd a felhasználódnak az altatást, vagy válts a „Parancs futtatása” lehetőségre, és saját szkriptből altasd el a gépet.`,"idleAction.runFailed":`A parancsot nem sikerült elindítani.`,"idleAction.failedTitle":`A sor végi művelet nem sikerült`,"idleAction.openSettings":`Ugrás a beállításhoz`,"idleAction.dismiss":`Elrejtés`,"settings.transfer.cardTitle":`Biztonsági mentés és átvitel`,"settings.transfer.cardHint":`Mindkét fájl itt készül, és a böngésződ menti el őket, máshová nem kerülnek. Egyik sem viszi magával a debrid- és hoszterbejelentkezéseidet, a fejlécprofilokat, a captchakulcsokat, ennek a felületnek a belépési jelszavát vagy a szkriptjeidet: ezek titkosítva, a settings.json fájlon kívül fekszenek, és az archívum is itt hagyja őket, úgyhogy ezeket az új gépen újra beállítod.`,"settings.transfer.archiveLabel":`A teljes telepítés`,"settings.transfer.archiveText":`Egy archívum mindennel, ami ezen a gépen van: az adatbázis, a letöltési lista, az előzmények és a beállítások, a jelszavakkal együtt, ezért tartsd a fájlt bizalmas helyen. A visszaállítás mindezt lecseréli, és a következő indítástól érvényes.`,"settings.transfer.settingsLabel":`Csak a beállítások`,"settings.transfer.settingsText":`Csak a settings.json: a sor korlátai, a mappák, a szabályok, a kategóriák és az időzítés. Importáláskor előbb minden kulcsot látsz, csak az íródik ki, amit bejelölsz, és azonnal érvénybe lép, újraindítás nélkül.`,"settings.transfer.export":`Beállítások exportálása`,"settings.transfer.import":`Beállítások importálása`,"settings.transfer.withSecrets":`A tárolt jelszavak is menjenek vele`,"settings.transfer.withSecretsHint":`Bekapcsolva a fájl nyílt szövegben tartalmazza a router jelszavát, minden proxyjelszót és minden archívumjelszót. Kikapcsolva ezek a mezők üresen érkeznek meg a másik gépen, és egyszer begépeled őket. Mindkét esetben állhat titok olyan helyen, amelyet itt senki nem ismer fel: egy feedcím, amelyben API-kulcs van, vagy egy jelszó, amelyet újracsatlakozási szkriptbe írtál.`,"settings.transfer.previewTitle":`Mi kerüljön át?`,"settings.transfer.previewFrom":`Innen: {version}, {date}`,"settings.transfer.previewSecretless":`Ezt a fájlt jelszavak nélkül exportálták. Az alább megjelölt sorok a sajátjuk nélkül érkeznek meg.`,"settings.transfer.colStored":`Most itt`,"settings.transfer.colFile":`A fájlban`,"settings.transfer.same":`Azonos`,"settings.transfer.unknownKey":`Ez a build nem ismeri ezt a beállítást, így nem vehető át.`,"settings.transfer.identityKey":`Ehhez a géphez tartozik, és soha nem kerül át`,"settings.transfer.identityKeyHint":`A példányazonosítón keresztül szólítja meg ezt a gépet a relé és minden párosított testvér. Két gép ugyanazzal az azonosítóval ütközik egy csoporton belül, ezért ott marad, ahol létrejött.`,"settings.transfer.noPassword":`Jelszó nélkül érkezik meg. Utólag írd be.`,"settings.transfer.wholeList":`Az itteni teljes listát lecseréli, sorról sorra`,"settings.transfer.newFolder":`Ez a mappa itt még nem létezik. Mentéskor létrejön, olyan konténerben is, amelyben nincs hozzá illő kötet becsatolva.`,"settings.transfer.selectAll":`Mind`,"settings.transfer.selectNone":`Egyik sem`,"settings.transfer.selectChanged":`Csak ami eltér`,"settings.transfer.apply":`{n} átvétele`,"settings.transfer.cancel":`Mégse`,"settings.transfer.applying":`Átvétel…`,"settings.transfer.nothingSelected":`Nincs kiválasztva semmi.`,"settings.transfer.applied":`{n} beállítás átvéve. Semmit nem indítottunk újra.`,"settings.transfer.incomplete":`Itt még hiányzik egy jelszó: {fields}`,"settings.transfer.incompleteReconnect":`a router jelszava`,"settings.transfer.incompleteConnections":`a proxyjelszavak`,"settings.transfer.incompleteArchives":`az archívumjelszavak`,"settings.transfer.rulesUncompiled":`{n} olyan szabály érkezett, amelyet ez a build nem tud lefordítani. El vannak mentve, de soha nem futnak le. Nézd meg a Szabályok és kategóriák oldalt.`,"settings.transfer.parseFailed":`Ez nem beállításexport: {reason}`,"settings.transfer.tooNew":`Ezt a fájlt a(z) {version} írta, ez a kiszolgáló pedig a(z) {running} verzión fut. Előbb frissítsd a kiszolgálót, utána importálj.`,"settings.transfer.applyFailed":`Nem sikerült átvenni: {error}`,"settings.transfer.group.queue":`Sor és tempó`,"settings.transfer.group.folders":`Mappák`,"settings.transfer.group.archives":`Archívumok`,"settings.transfer.group.rules":`Szabályok és kategóriák`,"settings.transfer.group.schedule":`Időzítés és csendes mód`,"settings.transfer.group.network":`Kapcsolatok és újracsatlakozás`,"settings.transfer.group.resolvers":`Backendek`,"settings.transfer.group.look":`Megjelenés`,"settings.transfer.group.other":`Minden egyéb`,"settings.mediahook.title":`Médiatár értesítése`,"settings.mediahook.hint":`Egy cím, amelyet a KnightLoader egyszer meghív, amint egy csomag utolsó fájlja megérkezett és a helyére került. Jellyfin vagy Plex könyvtár-újraolvasásához szánjuk, de a mező egyikről sem tud semmit: azt a címet hívja meg, amelyet beírsz, azzal a módszerrel, amelyet kiválasztasz, és egy fejlécet is hozzátesz, ha megadsz egyet. A fejléc értéke ugyanabban a titkosított tárban van lezárva, mint a fiókbejelentkezéseid, és soha nem kerül vissza erre az oldalra. Semmit nem hívunk meg, amíg nem tárolsz el egy címet, és nem választod ki egy kategóriánál a Szabályok és kategóriák alatt. Az a letöltés, amelynek nincs csomagneve, soha nem indít hívást, mert nincs csomag, amelynek az utolsó fájlja lehetne. Az a csomag sem indít, amelyik a kiszolgáló újraindítása közben készül el: az első menet feljegyzi, ami már kész, és nem jelenti be.`,"settings.mediahook.empty":`Még nincs cím eltárolva.`,"settings.mediahook.emptyHint":`Már akkor megéri egy, amint a médiakiszolgálód magától nem veszi észre az új fájlokat.`,"settings.mediahook.add":`Cím létrehozása`,"settings.mediahook.name":`Név`,"settings.mediahook.nameHint":`Ezen a néven választod ki a címet egy kategóriánál a Szabályok és kategóriák alatt. Csak betű, számjegy és - _ vagy . lehet benne. Utólag nem módosítható, mert a kategória ezen a néven keresztül mutat rá.`,"settings.mediahook.url":`Cím`,"settings.mediahook.urlHint":`A teljes cím, amelyet meghívunk, http vagy https, hoszttal és porttal együtt. Mentés előtt olvasd el még egyszer: ami itt áll, azt erről a gépről hívjuk meg. Maga a cím nyílt szövegként áll a settings.json fájlban, és így a diagnosztikai csomagba is bekerül. A kulcsot ezért lent a fejlécbe írd, és ne a cím lekérdezési részébe.`,"settings.mediahook.method":`Módszer`,"settings.mediahook.methodHint":`GET vagy POST. A POST törzs nélkül megy ki. A Jellyfin POST-ot kér, a Plex GET-et, és ha bizonytalan vagy, a tesztkérés megmondja, mit fogad el a túloldal.`,"settings.mediahook.headerName":`A fejléc neve`,"settings.mediahook.headerNameHint":`Az az egy fejléc, amely a hívással együtt megy, Jellyfinnél például X-Emby-Token. Ha üresen hagyod, nem megy vele külön fejléc.`,"settings.mediahook.headerValue":`A fejléc értéke`,"settings.mediahook.headerValueHint":`Az a kulcs, amely ebbe a fejlécbe kerül. Ugyanabban a titkosított tárban fekszik, mint a fiókadataid, soha nem kerül a settings.json fájlba, és soha nem küldjük vissza erre az oldalra.`,"settings.mediahook.valueStored":`Eltárolva`,"settings.mediahook.valueStoredHint":`Az érték ezen a példányon marad. Hagyd úgy a mezőt, ahogy van, ha meg akarod tartani, vagy írj be egy újat a lecseréléséhez. Ha kiüríted a mezőt, az érték eltűnik.`,"settings.mediahook.goesTo":`A hívás ide megy: {host}`,"settings.mediahook.goesToForeign":`Ez a cím nem a saját hálózatodban van. A hívás elhagyja ezt a gépet, és a fejléc vele megy.`,"settings.mediahook.wait":`Várakozás a hívás előtt`,"settings.mediahook.waitHint":`Mennyi ideig hagyjuk békén ezt a címet egy elkészült csomag után, hogy húsz egyszerre elkészült csomagból egy hívás legyen húsz helyett. A könyvtár-újraolvasás valódi munkát ad a médiakiszolgálónak, és az, amelyik egy perccel később érkezik, neked semmibe nem kerül. 0-ra állítva a hívás azonnal kimegy, amint egy csomag fájljai a helyükön vannak, és nem vár továbbiakra.`,"settings.mediahook.waitImmediate":`A hívás azonnal kimegy, amint egy csomag elkészült, és nem vár továbbiakra.`,"settings.mediahook.error.nameInvalid":`Egy név csak betűket, számjegyeket és - _ vagy . jelet tartalmazhat, legfeljebb 64 karaktert.`,"settings.mediahook.save":`Cím mentése`,"settings.mediahook.delete":`Cím törlése`,"settings.mediahook.deleteConfirm":`Töröljük a(z) {name} címet? A tárolt fejlécérték vele megy, és erről az oldalról nem hozható vissza.`,"settings.mediahook.deleteInUse":`A(z) {name} még {n} kategóriánál ki van választva. Előbb állítsd azokat a „Ne értesítsen semmit” lehetőségre, utána töröld.`,"settings.mediahook.usedBy":`{n} kategóriánál kiválasztva`,"settings.mediahook.usedByNone":`Eltárolva, és még semmi nem hívja`,"settings.mediahook.test":`Tesztkérés küldése`,"settings.mediahook.testRunning":`Hívás folyamatban`,"settings.mediahook.lastCall":`Legutóbbi hívás`,"settings.mediahook.lastCallHint":`Mi történt, amikor ezt a címet utoljára meghívtuk, a tesztkéréseket is beleszámítva. Csak a memóriában él, egy újraindítás tehát törli, anélkül hogy magán a címen bármit változtatna.`,"settings.mediahook.lastCallNever":`A kiszolgáló indulása óta még nem hívtuk meg`,"settings.mediahook.answeredAfter":`Válasz: {status}, {duration} után`,"settings.mediahook.failedAfter":`Sikertelen, {duration} után`,"settings.mediahook.lastCallFor":`A(z) {name} csomaghoz`,"settings.mediahook.lastCallTest":`Tesztkérés`,"settings.mediahook.lastCallCoalesced":`{n} csomaghoz, amelyek együtt készültek el`,"settings.mediahook.problem.dns":`A hosztnevet nem sikerült feloldani. Ellenőrizd a helyesírást, és vedd az IP-címet, ha ez a példány nem éri el a hálózatod saját névkiszolgálóját.`,"settings.mediahook.problem.refused":`Ezen a porton semmi nem figyel. Ellenőrizd a portot, és azt is, hogy a médiakiszolgáló elérhető-e ebből a konténerből, nem csak a saját gépedről.`,"settings.mediahook.problem.timeout":`A túloldal fogadta a kapcsolatot, és {seconds} másodpercen belül nem válaszolt. A cím valószínűleg jó, a kiszolgáló pedig elfoglalt vagy megakadt.`,"settings.mediahook.problem.tls":`A biztonságos kapcsolat nem jött létre. Ennek szokásos oka a saját kiállítású tanúsítvány. Vedd a http-t és a belső címet, ha a médiakiszolgáló a saját hálózatodban áll.`,"settings.mediahook.problem.auth":`A kiszolgáló {status} kóddal válaszolt: nem fogadta el a fejlécet. Ellenőrizd a fejléc nevét, és illeszd be újra a kulcsot.`,"settings.mediahook.problem.notFound":`A kiszolgáló 404-gyel válaszolt: a cím elérhető, ez az útvonal viszont nincs meg rajta. Ellenőrizd az útvonalat, benne a könyvtárazonosítót is, ha a cím tartalmaz ilyet.`,"settings.mediahook.problem.method":`A kiszolgáló 405-tel válaszolt: ezen az útvonalon nem fogad {method} kérést. Válts módszert, és teszteld újra.`,"settings.mediahook.problem.redirect":`A cím {status} kóddal válaszolt, és máshová mutat. Az átirányításokat itt nem követjük, mert a fejléc velük menne az új címre. Írd be azt a címet, amelyre mutat.`,"settings.mediahook.problem.server":`A kiszolgáló {status} kóddal válaszolt. Ez a túloldal hibája, nem ezé a címé. Nézz bele a médiakiszolgáló saját naplójába.`,"settings.mediahook.problem.proxy":`A hívás a HTTP_PROXY szerinti proxyn keresztül ment, és nem érkezett meg. Írd be a médiakiszolgáló hosztját a NO_PROXY változóba, és teszteld újra.`,"settings.mediahook.problem.unknown":`A hívás nem sikerült: {error}`,"settings.categories.notify":`Médiatár értesítése`,"settings.categories.notifyHint":`Melyik eltárolt címet hívjuk meg, amint egy ebbe a kategóriába sorolt csomag elkészült, és a fájljai a helyükön vannak. Az a csomag, amelynek a linkjei két kategóriában fekszenek, mindkettőt meghívja, egyszer-egyszer. A „Ne értesítsen semmit” állásban ez a kategória csendben marad, és pontosan ezt teszi minden kategória, amíg nem változtatsz rajta.`,"settings.categories.notifyNone":`Ne értesítsen semmit`,"settings.categories.notifyEmpty":`Még nincs cím eltárolva. Vegyél fel egyet az Automatizálás oldalon.`,"settings.categories.notifyMissing":`{id} (törölve)`,"settings.module.eventtargets":`Eseménycélok`,"settings.eventTargets.titleHint":`Hová jelent ez a példány, ha történik valami: egy általad megadott címre, az általad megadott módszerrel, fejlécekkel és törzzsel. Semmi nincs előre kitöltve és semmi nincs bekapcsolva, amíg te meg nem teszed, és egy üzenet mindig csak arra a címre megy, amelyik a sorban áll. Ugyanazok az események választhatók, amelyekre a szkriptszerkesztő is reagál.`,"settings.eventTargets.add":`Cél hozzáadása`,"settings.eventTargets.empty":`Még nincs cél.`,"settings.eventTargets.emptyHint":`Cél nélkül egyetlen üzenet sem hagyja el ezt a gépet. Vegyél fel egyet, hogy értesülj egy elkészült csomagról, egy meghiúsult letöltésről vagy egy várakozó captcháról.`,"settings.eventTargets.remove":`Eltávolítás`,"settings.eventTargets.name":`Név`,"settings.eventTargets.nameHint":`Így hívják ezt a célt a listában, az alatta lévő állapotban és a naplóban. A nevet sehová nem küldjük el, használd tehát arra, hogy megkülönböztesd a telefonodat a csevegőszobádtól.`,"settings.eventTargets.enabled":`Küldés erre a célra`,"settings.eventTargets.enabledHint":`Kikapcsolva marad, amíg be nem kapcsolod, és ez minden felvett célra igaz. Amíg ki van kapcsolva, a sor megtart mindent, amit beírtál, és nem küld semmit. Így nyugodtan befejezheted és letesztelheted a célt, mielőtt bárki hallana róla.`,"settings.eventTargets.url":`Cím`,"settings.eventTargets.urlHint":`A teljes cím, amelyre az üzenet megy, csak http vagy https. Ezt a kiszolgálót te nevezed meg, nem a KnightLoader választja ki, és minden, ami a lenti törzsben áll, oda érkezik meg. A hoszt az összecsukott sorban látszik, hogy egy pillantással lásd, hová jelent egy cél. A helyőrzők itt is működnek, és címhez illően kódolódnak. Ha a cím egy másik hosztra irányít tovább, az Authorization fejléc útközben elvész, ami többnyire 401-ként jön vissza.`,"settings.eventTargets.method":`Módszer`,"settings.eventTargets.methodHint":`GET, POST vagy PUT. A POST az, amit az ntfy, a Gotify és a Matrix egyaránt vár. A GET nem küld törzset, ezért nála a lenti törzssablon kimarad.`,"settings.eventTargets.headers":`Fejlécek`,"settings.eventTargets.headersHint":`Soronként egy fejléc, Név: érték alakban, ahogy mindenhol másutt is. Ide kerül a token: Authorization: Bearer … a Matrixhoz, X-Title vagy Priority az ntfyhoz. Az értéket ugyanúgy tároljuk, mint a router jelszavát, ezen a gépen a settings.json fájlban, és soha nem adjuk vissza a böngészőnek: ott nyolc csillag áll helyette. Ha megváltoztatod a címet, a tárolt értéket eldobjuk, nem visszük át az új címre.`,"settings.eventTargets.body":`Törzssablon`,"settings.eventTargets.bodyHint":`Amit elküldünk, olyan helyőrzőkkel, amelyek az esemény pillanatában töltődnek ki. Ha üresen hagyod, csak a fejlécek mennek ki. Az értékeket a fejlécekben beállított tartalomtípushoz igazítva maszkoljuk, így egy JSON-törzsben az idézőjelet tartalmazó fájlnév maszkolva kerül bele, ahelyett hogy tönkretenné a dokumentumot.`,"settings.eventTargets.events":`Események`,"settings.eventTargets.eventsHint":`Mely események mennek erre a célra. Kezdetben semmi nincs bepipálva. Három közülük újraindítás után ismét jelentkezik, mert amit megjegyeznek, az a memóriában él és nem a lemezen: a sor üresnek jelenti magát, minden még várakozó captcha újra jelentkezik, és minden már lejárt fiók újra jelentkezik. Egy elkészült csomag nem, mert az indulás utáni első menet csak tudomásul veszi az állást, és nem mond semmit.`,"settings.eventTargets.eventsNone":`Nincs bepipálva semmi, ez a cél tehát soha nem küld.`,"settings.eventTargets.eventsBurst":`A hozzáadott link linkenként indít, kétszáz beillesztett link tehát kétszáz üzenet. Amit a sor nem fogad be, azt eldobjuk és lent megszámoljuk, ahelyett hogy felhalmozódna.`,"settings.eventTargets.replaysHint":`Ez az esemény minden újraindítás után újra jelentkezik, mert amit megjegyez, az a memóriában él, nem a lemezen.`,"settings.eventTargets.attempts":`Kézbesítési kísérletek`,"settings.eventTargets.attemptsHint":`Hányszor próbálkozunk egy üzenettel, mielőtt feladjuk. A 0 azt jelenti, hogy nincs róla véleményed, és a szokásos három érvényes; hogy éppen melyik szám van érvényben, a mező mellett áll. 1 és 5 között. A túloldal elutasítását, egy rossz tokent vagy egy nem létező útvonalat egyáltalán nem ismételjük meg, mert ezen egy második próbálkozás nem változtat, az okot pedig az alatta lévő állapot mutatja. Amíg egy üzenet vár, semmi nem íródik a lemezre. Az a cél, amelyik egész éjjel oda volt, visszatéréskor tehát nem pótol semmit.`,"settings.eventTargets.attemptsDefault":`a 0 hármat jelent`,"settings.eventTargets.timeout":`Időkorlát (másodperc)`,"settings.eventTargets.timeoutHint":`Meddig tarthat egy kísérlet. A 0 azt jelenti, hogy nincs róla véleményed, és tizenöt másodperc érvényes. 1 és 60 között. A lassan válaszoló push-kiszolgáló ennyi ideig feltartja ezt a célt, és minden, ami mögötte várakozik, vele vár.`,"settings.eventTargets.placeholders":`Helyőrzők`,"settings.eventTargets.placeholdersHint":`Azok a nevek, amelyeket a címbe, egy fejlécbe vagy a törzsbe írhatsz, mindegyiket két százalékjel közé fogva. A kiszolgálótól jönnek, ez a lista tehát az, amit ez a build tényleg behelyettesít. Azt a nevet, amelyet ez a build nem ismer, úgy hagyja, ahogy beírtad, hogy az elgépelés feltűnjön az üzenetben, ahelyett hogy csendben eltűnne. Az a név, amelyet ismer, de amelyet ez az esemény nem hoz magával, üresen marad.`,"settings.eventTargets.placeholderUnused":`A fent bepipált események közül egyik sem hozza magával a(z) {name} nevet, ezért a helyőrző üresen marad ennek a célnak minden üzenetében.`,"settings.eventTargets.leavesTheBox":`Ennek a célnak minden üzenete elhagyja ezt a gépet, és a(z) {host} hosztra megy.`,"settings.eventTargets.test":`Teszt küldése`,"settings.eventTargets.testBusy":`Küldés folyamatban`,"settings.eventTargets.testHint":`Ez tényleg elküld egy üzenetet a fenti címre, azonnal, ennek a sornak az értékeivel és egy kitalált eseménnyel. Nem szárazpróba: a telefonod rezegni fog, és a csevegőszobád is látni fogja. A választ úgy mutatjuk, ahogy visszajött, hogy az elutasítást el lehessen olvasni, ne kitalálni kelljen. A tárolt fejlécértéket behelyettesítjük a kéréshez, utána pedig nyolc csillagként mutatjuk, mert ez a böngésző soha nem látta.`,"settings.eventTargets.testResult":`A válasz, ami visszajött`,"settings.eventTargets.testSent":`Amit elküldtünk`,"settings.eventTargets.took":`Időtartam: {duration}`,"settings.eventTargets.testTruncated":`A válasz ennél hosszabb. Itt csak az első {n} karakter látszik.`,"settings.eventTargets.testEmptyBody":`A válasznak nem volt törzse, ez egy push-kiszolgálónál normális.`,"settings.eventTargets.testNoAnswer":`Nem érkezett válasz.`,"settings.eventTargets.status":`Állapot`,"settings.eventTargets.statusUnknown":`A kiszolgáló indulása óta semmi nem ment ki erre a célra. Ez nem ugyanaz, mint hogy soha.`,"settings.eventTargets.lastAttempt":`Utolsó kísérlet`,"settings.eventTargets.lastOk":`Utoljára megérkezett`,"settings.eventTargets.lastOkNever":`A kiszolgáló indulása óta semmi nem érkezett meg.`,"settings.eventTargets.sentCount":`{n} kézbesítve a kiszolgáló indulása óta`,"settings.eventTargets.dropped":`{n} eldobva, mert a sor tele volt`,"settings.eventTargets.droppedHint":`A roham, amelyik gyorsabban érkezik, mint ahogy ez a cél átveszi, eldobásra kerül, nem tesszük félre. A félretétel azt jelentené, hogy memóriát költünk olyan üzenetekre, amelyek megérkezéskor már rég elavultak. Ha ez a szám tovább nő, a cél túl lassú a bepipált eseményekhez.`,"settings.eventTargets.problem.noUrl":`Ebben a sorban nincs cím, így nem lehet semmit elküldeni. Írj be egyet fent.`,"settings.eventTargets.problem.badUrl":`A cím nem olvasható ki http vagy https címként. Ellenőrizd a sémát és a hosztot.`,"settings.eventTargets.problem.badMethod":`Ez a build GET, POST és PUT kérést küld, mást nem. Válaszd a három valamelyikét.`,"settings.eventTargets.problem.badTemplate":`Egy helyőrző nincs lezárva. Mindegyiket két százalékjellel írjuk, a név mindkét oldalán.`,"settings.eventTargets.problem.unknownTrigger":`Ennek a sornak az egyik eseményét ez a build nem váltja ki. Vedd ki, és válassz egyet a listából.`,"settings.eventTargets.problem.dns":`A hosztot erről a példányról nem sikerült feloldani. A konténernek gyakran saját névfeloldója van, az a cím tehát, amelyet a saját géped elér, nem feltétlenül elérhető ebből a dobozból.`,"settings.eventTargets.problem.refused":`Ott semmi nem figyel. Ellenőrizd a portot, és azt is, hogy a szolgáltatás egyáltalán fut-e.`,"settings.eventTargets.problem.tls":`A tanúsítványt nem fogadtuk el. Ennek szokásos oka a saját kiállítású tanúsítvány a saját kiszolgálódon. A saját hálózatodon belül vedd a http-t, vagy add oda ennek a konténernek a tanúsítványt.`,"settings.eventTargets.problem.timeout":`A túloldal az időkorláton belül nem válaszolt. Emeld meg fent a korlátot, vagy küldd valami gyorsabbra.`,"settings.eventTargets.problem.auth":`A túloldal elutasította a belépési adatokat. Ellenőrizd a tokent a fejlécekben, és ne feledd: a másik hosztra mutató átirányítás útközben eldobja az Authorization fejlécet.`,"settings.eventTargets.problem.notFound":`A túloldal nem ismeri ezt az útvonalat. Az ntfynál a téma a cím része, a Matrixnál a szobaazonosító.`,"settings.eventTargets.problem.rejected":`A túloldal elolvasta a kérést, és elutasította. A lenti válasz az ő saját szövege, és többet mond, mint bármilyen itteni besorolás.`,"settings.eventTargets.problem.rateLimited":`A túloldal egyelőre elutasít, mert túl sok érkezett egyszerre. Vedd ki a hangosabb eseményeket, vagy küldd a saját kiszolgálódra egy nyilvános helyett.`,"settings.eventTargets.problem.server":`A túloldal saját hibával válaszolt. Annyiszor próbáltuk újra, amennyit ez a sor megenged, a következő hely tehát az ő saját naplójuk.`,"settings.scripts.trigger.linkAdded":`Egy link hozzáadódik`,"settings.scripts.trigger.packageDone":`Egy csomag elkészül`,"settings.scripts.trigger.extractDone":`Egy archívum kicsomagolása befejeződik`,"settings.scripts.trigger.checksumFailed":`Egy ellenőrzőösszeg nem egyezik`,"settings.scripts.trigger.reconnectDone":`Lefutott egy újracsatlakozás`,"settings.scripts.trigger.accountExpired":`Egy fiók lejárt`,"settings.scripts.trigger.captchaPending":`Egy captcha vár`,"settings.nav.health":`Állapot`,"settings.module.metrics":`Mérőszámok címe egy felügyeleti rendszerhez`,"settings.health.title":`Állapot most`,"settings.health.titleHint":`Ez az oldal csak olvas. Semmi rajta nem indít, nem állít le és nem változtat meg semmit, és ha nyitva hagyod, az sem változtat semmin. Az értékeket tíz másodpercenként kérjük le; ha egy lekérés meghiúsul, az utolsó leolvasás marad kiírva, ahelyett hogy kiürülne az oldal. A lekérdezendő részeket fél percig megosztjuk, ami tehát itt áll, az akár harminc másodperccel a Letöltések oldal sorai mögött járhat.`,"settings.health.version":`Verzió`,"settings.health.uptime":`Fut ennyi ideje`,"settings.health.uptimeHint":`Mennyi ideje fut ez a folyamat, nem az, hogy mennyi ideje fut a gép. Az egy órája újraindult konténer itt megint nulláról kezd, bármit is mond a gazdagép. A mellette álló dátum a kiszolgáló saját órája, nem a böngésződé.`,"settings.health.startedAt":`Elindult`,"settings.health.sampled":`{n} másodperce olvasva`,"settings.health.loadFailed":`Az állapotot nem sikerült betölteni. Elérhető a kiszolgáló?`,"settings.health.oldHealthHint":`A régi /api/health cím nem változott, és amíg ez a folyamat fut, továbbra is „ok” választ ad, bármit mutat is ez az oldal. Azért marad így, mert a konténer saját állapotellenőrzése, a Click'n'Load híd és a telefonos alkalmazás hálózati példánykeresése mind ezt olvassa, és ha ott nem „ok” lenne a válasz, a konténer egészségtelennek számítana, a telefon pedig nem találná többé ezt a példányt. A hibákat ez az oldal jelenti; az a cím csak annyit mond, hogy figyel-e ott valami.`,"health.state.ok":`Működik`,"health.state.degraded":`Működik, de hibával`,"health.state.failed":`Nem működik`,"health.state.unused":`Itt nincs használatban`,"health.state.unknown":`Itt nem ellenőrizhető`,"settings.health.parts":`Összetevők`,"settings.health.partsHint":`Egy sor az alkalmazás minden olyan részéhez, amely önmagában is meghibásodhat. Az a rész, amelyet ezen a példányon soha nem állítottál be, ezt jelzi, ahelyett hogy hibának számítana, és az is jelzi, amelyről ez a build nem tud kérdezni. Egy sor elolvasása semmin nem változtat: az a rész, amely azt mondja, hogy nem működik, már egy ideje hibás, itt csak értesülsz róla.`,"health.part.store":`Adatbázis`,"health.part.queue":`Sor`,"health.part.disk":`Célmappák`,"health.part.jd":`JDownloader háttér`,"health.part.ytdlp":`yt-dlp`,"health.part.accounts":`Tárhelyfiókok`,"health.part.feeds":`Feed-feliratkozások`,"health.part.relay":`Relé`,"health.part.captcha":`Captchák`,"health.remedy.store.failed":`Az adatbázis nem válaszolt. A letöltések tovább futnak, de már semmit nem írunk le róluk, egy újraindítás tehát mindent elveszítene, ami azóta megváltozott. Nézd meg, hogy az adatmappa még be van-e csatolva és írható-e még.`,"health.remedy.jd.unreachable":`A KL_JD olyan címet nevez meg, amelyet ez a példány éppen nem ér el. Nézd meg, fut-e a JDownloader konténer, és válaszol-e innen az API-portja. Azok a linkek, amelyeket csak a JDownloader tud lehozni, addig a sorban maradnak; nem hiúsultak meg.`,"health.remedy.jd.notWired":`A JDownloader megint válaszol, de ez a folyamat induláskor kötötte be a háttereit, és akkor nem volt meg. Indítsd újra a KnightLoadert, hogy átvegye.`,"health.remedy.ytdlp.missing":`Ennek a folyamatnak az indulásakor nem találtunk yt-dlp programot (KL_YTDLP, vagy „yt-dlp” a PATH-on). A médiaoldalak ilyenkor az oldal saját hibájával hiúsulnak meg, ahelyett hogy változatokra bomlanának. A megtalálásához újraindítás kell.`,"health.remedy.disk.low":`Egy célmappa a Letöltések oldalon beállított határ alatt van. Ott semmi új nem indul el, amíg megint nincs hely, vagy amíg le nem viszed a határt. Ami már fut, azt ez a határ nem állítja le.`,"health.remedy.disk.elsewhere":`Egy mappa nincs meg, ezért a számok a fölötte lévő legközelebbi mappát írják le. Ha egy csatolás nem jött fel, az egy teljesen más lemez. Nézd meg az útvonalat, mielőtt elhinnéd a számokat.`,"health.remedy.accounts.benched":`Legalább egy tárhelyfiókot hiba után békén hagyunk. Magától próbálkozunk vele még egyszer, ha letelt a várakozás, és a várakozás minden alkalommal duplázódik. Nyisd meg a Fiókok oldalt, és nyomd meg a soron a Frissítést, ha most akarod tudni.`,"health.remedy.accounts.invalid":`Legalább egy tárhelyfiókot elutasítottak. Új kulcs vagy megújított előfizetés segít, a várakozás nem.`,"health.remedy.feeds.failing":`Legalább egy feliratkozásnál meghiúsult az utolsó lekérés. Hogy melyiknél és miért, az a Letöltések oldalon a feed mellett áll, és a Diagnosztika oldal naplósoraiban.`,"health.remedy.relay.down":`Egy relécím el van mentve, és a kapcsolat nem áll. Ez a példány magától tovább próbálkozik, és helyben minden a szokásos módon működik; csak kívülről nem érhető el.`,"health.remedy.captcha.waiting":`Egy backend megállt, és embert kérdez. Mögötte semmi nem mozdul, amíg valaki nem válaszol.`,"settings.health.tasks":`Letöltések most`,"settings.health.tasksHint":`A lista pillanatfelvétele, ahogy éppen áll, nem idővel gyűlő összesítés, így egyik szám sem mondja meg, milyen gyakran hiúsult meg bármi. A „Meghiúsult” azokat a sorokat számolja, amelyek hibával állnak a listában: csökken, amikor kitakarítod őket, és amikor a lista a beállított napok után rendbe teszi magát, és újra nő, ha valami új romlik el.`,"settings.health.diskWhere":`Hogy mennyi hely van a célmappákban, azt a Letöltések oldal mutatja.`,"settings.health.running":`Fut`,"settings.health.waiting":`Vár`,"settings.health.failed":`Meghiúsult`,"settings.health.waitingWhy":`Miért várnak`,"settings.health.failedWhy":`Mi ment félre`,"settings.health.nothingWaiting":`Semmit nem tartunk vissza.`,"settings.health.nothingFailed":`A listában semmi nem hiúsult meg.`,"settings.health.scrapeHint":`Megnyit egy második címet, amely ugyanazokat az értékeket adja ki sima szövegként, abban a formátumban, amelyet a Prometheus és a mintájára épült eszközök olvasnak. Ezt a címet lekérik, magától soha nem küld semmit: semmi nem hagyja el ezt a gépet, amíg a saját felügyeleted ide nem jön és el nem kéri. Amíg ez ki van kapcsolva, a cím egyáltalán nem létezik, és 404-gyel válaszol, ugyanúgy, mint bármelyik másik cím, amelyik ennek az alkalmazásnak nincs meg. Jelszavas példányon a lekéréshez kell az egyik API-tokened, és ezt minden gyűjtőnek meg lehet tanítani. A gyűjtő nem küld származási fejlécet, ezért átjut; egy másik címen álló böngészőlap küld egyet, és elutasítjuk, ha az nem illik ennek a példánynak a saját címéhez. A szövegben ott állnak a célmappáid útvonalai. Csak oda add tehát, ahová magukat a mappaneveket is odaadnád.`,"settings.health.scrapeUrl":`Mérőszámok címe`,"settings.health.scrapeCopy":`Cím másolása`,"settings.health.scrapeCopied":`Cím másolva`,"settings.health.scrapeOffHint":`Ez a cím semmit nem válaszol, amíg a fenti kapcsoló ki van kapcsolva.`,"settings.diagnostics.systemTitle":`Rendszerinformációk`,"settings.diagnostics.fileTitle":`Naplófájl`,"settings.diagnostics.fileOn":`Napló írása fájlba`,"settings.diagnostics.fileOnHint":`Kikapcsolva marad, amíg be nem kapcsolod, és egy frissítés soha nem kapcsolja be helyetted. Bekapcsolva ez a példány minden naplózott sorát az adatmappájában lévő fájlba írja, így egy tegnapelőtti összeomlás újraindítás után is olvasható marad. Egy naplósor megnevezheti annak a feednek a címét, amelyre feliratkoztál, kezeld tehát a fájlt sajátodként. Konténerben ugyanezek a sorok már a docker logs kimenetébe is eljutnak; a fájl az, ami megmarad, amikor az már továbbgördült.`,"settings.diagnostics.fileSize":`Fájlonkénti méret`,"settings.diagnostics.fileSizeHint":`Amint a fájl eléri ezt a méretet, átnevezzük, és újat kezdünk.`,"settings.diagnostics.fileKeep":`Megtartott régi fájlok`,"settings.diagnostics.fileKeepHint":`Hány átnevezett fájl marad meg az éppen írt mellett. A nulla csak az aktuális fájlt tartja meg, a naplózást nem kapcsolja ki.`,"settings.diagnostics.fileWhere":`Hol fekszik`,"settings.diagnostics.fileWhereHint":`Fixen beállítva, hogy egy útvonal elgépelése ne bénítsa meg a napló írását. Indítás előtt állítsd be a KL_LOG_DIR változót, ha másik lemezre akarod tenni.`,"settings.diagnostics.fileStateOff":`Nem íródik`,"settings.diagnostics.fileStateOn":`{max} méretből {size} foglalt`,"settings.diagnostics.fileProblem":`A naplófájl nem íródik: {error}`,"settings.diagnostics.fileProblemHint":`Ellenőrizd, hogy a(z) {path} létezik-e, és hogy az a fiók, amely alatt ez a folyamat fut, írhat-e oda. Unraidon ez rendszerint azt jelenti, hogy a mappa a rooté, miközben a konténer más felhasználóként fut. Egyébként semmi nem állt le: az utolsó {n} sor továbbra is a memóriában van, és továbbra is bekerül a diagnosztikai csomagba.`,"settings.diagnostics.fileProblemSpace":`A köteten még {free} szabad.`,"settings.diagnostics.fileProblemSpaceUnknown":`Hogy mennyi hely maradt azon a köteten, azt ezen a rendszeren nem lehet kiolvasni.`,"settings.diagnostics.fileCurrent":`Aktuális fájl`,"settings.diagnostics.fileOlder":`Régebbi fájl {n}`,"settings.diagnostics.fileEmpty":`Még nincs semmi kiírva.`,"settings.diagnostics.fileDownload":`Letöltés`,"settings.diagnostics.logSearch":`Keresés a sorokban`,"settings.diagnostics.logSearchHint":`Sima szöveg, helyettesítő karakterek nélkül, a kis- és nagybetű egyre megy. Az itt betöltött sorokban keres, nem a régebbi fájlokban. Egy egész fájl átkutatásához töltsd le a fájlt.`,"settings.diagnostics.logSource":`Forrás`,"settings.diagnostics.logSourceAll":`Minden forrás`,"settings.diagnostics.logSourceOther":`Többi sor`,"settings.diagnostics.logSourceHint":`Az alkalmazás melyik részéből származik egy sor, a sor elejéről leolvasva. Az a sor, amelyik nem nevez meg részt, a „Többi sor” alatt áll. Súlyossági szint szerint nem lehet szűrni: ebben az alkalmazásban egyetlen sor sem jegyez fel ilyet.`,"settings.diagnostics.logFollow":`Új sorok követése`,"settings.diagnostics.logFollowHint":`Két másodpercenként rákérdez, mi jött hozzá a legutóbbi óta, és a legújabb sorra ugrik. Kikapcsolva a nézet ott marad, ahol van, így olvasás közben nem csúszik el alólad.`,"settings.diagnostics.logMatches":`{total} sorból {shown}`,"settings.diagnostics.logNoMatches":`Itt egyetlen sor sem tartalmazza ezt.`,"settings.diagnostics.logGap":`Két lekérdezés között {n} sor esett ki: több érkezett, mint amennyit a memóriában tartott {cap} sor elbír. Kapcsold be a naplófájlt, hogy megmaradjanak.`,"settings.diagnostics.logTaskOnly":`Csak ez a letöltés`,"settings.diagnostics.logTaskClear":`Megint minden letöltés mutatása`,"settings.diagnostics.logTaskChip":`Csak azokat a sorokat mutasd, amelyek ezt a letöltést nevezik meg`,"detail.log.title":`Ennek a letöltésnek a naplója`,"detail.log.hint":`Azok a sorok, amelyeket ez a példány naplózott, és amelyek ezt a letöltést az azonosítóján nevezik meg.`,"detail.log.empty":`Ehhez a letöltéshez semmi nem került a naplóba.`,"detail.log.emptyHint":`Nem minden sor jegyzi fel, melyik letöltéshez tartozik, egy letöltés tehát úgy is bajba kerülhet, hogy itt egyetlen sor sem jelenik meg. A teljes napló a Diagnosztika oldalon áll.`,"detail.log.openDiagnostics":`A teljes napló megnyitása`,"detail.log.remote":`A napló azon a példányon marad, amelyik írta, ezért egy másik gépen futó letöltéshez itt nincs mit mutatni.`,"settings.owner.identityTitle":`Kiként ír ez a példány`,"settings.owner.identityHint":`Minden fájl, amelyet ez a példány létrehoz, ezt a tulajdonost és ezeket a jogokat kapja, és mindaz is, amit elindít: a yt-dlp, az ffmpeg és a mellékelt JDownloader. Konténerben az identitás abban a pillanatban eldől, amikor a konténer elindul, aszerint, hogy melyik fiók alatt indították, és erről az oldalról semmi nem változtat rajta.`,"settings.owner.uid":`Felhasználó`,"settings.owner.gid":`Csoport`,"settings.owner.umask":`Umask`,"settings.owner.umaskUnknown":`Ez a kernel nem adja ki`,"settings.owner.asked":`Kért érték`,"settings.owner.envIgnored":`A(z) {name}={value} be van állítva, de ebben a konténerképben senki nem olvassa. Az identitást az a fiók dönti el, amely alatt a konténert elindították, és ez a(z) {owner}.`,"settings.owner.envHow":`Ha másik fiók alatt szeretnél futni, nevezd meg az indítóparancsban: --user <uid>:<gid>. Unraidon ez az Extra Parameters mezőbe kerül, és a konténert újra kell hozni, hogy érvénybe lépjen.`,"settings.owner.desktopNote":`Az asztali alkalmazás a saját fiókod alatt fut. A PUID, a PGID és az UMASK konténerbeállítás, itt nem csinálnak semmit.`,"settings.owner.noOwners":`Ezen a rendszeren a fájloknak nincs tulajdonosuk, nincs tehát mit összehasonlítani. Ez nem hiba.`,"settings.owner.checkTitle":`Mappaellenőrzés`,"settings.owner.checkHint":`Itt tényleg egy fájl és egy almappa íródik minden mappába, utána megnézzük, kié mindkettő és ki olvashatja még, végül mindkettőt eltávolítjuk. Ezt mérni kell, kiszámolni nem szabad: egy megosztás hozhat saját jogosultsági szabályokat, és a set-group-id jelzésű mappa más csoportot ad, mint amelyik ennek a folyamatnak van. Magától lefut, miután elmentettél egy megváltozott mappát, és minden alkalommal, amikor megnyomod a gombot.`,"settings.owner.run":`Mappák ellenőrzése most`,"settings.owner.running":`Ellenőrzés…`,"settings.owner.never":`Még nem ellenőriztük.`,"settings.owner.checkedAt":`Legutóbb ellenőrizve: {time}.`,"settings.owner.checkFailed":`Az ellenőrzés nem futott le: {error}`,"settings.owner.role.downloads":`Letöltési mappa`,"settings.owner.role.work":`Munkamappa`,"settings.owner.role.category":`Kategóriamappa`,"settings.owner.role.watch":`Figyelt mappa`,"settings.owner.v.ok":`A fájlok {fileOwner} tulajdonossal és {fileMode} jogokkal kerülnek ide, az új almappák {subdirMode} jogokkal, a mappa maga pedig {dirOwner} tulajdona. Ezen semmi nem tűnik fel.`,"settings.owner.v.ownerMismatch":`A fájlok {fileOwner} tulajdonossal kerülnek ide, a mappa viszont {dirOwner} tulajdona. Olvasni többnyire még lehet őket, átnevezni, áthelyezni és törölni másik fiók alól nem, és ami azt várja, hogy a mappáé legyen a saját tartalma, az idegennek tartja ezeket a fájlokat.`,"settings.owner.v.groupUnreadable":`A fájlok {fileMode} jogokkal kerülnek ide, megnyitni tehát csak {fileOwner} tudja őket. Ami másik fiók alatt fut, az a neveket látja, mást semmit.`,"settings.owner.v.dirUnreadable":`Az új almappák {subdirMode} jogokkal kerülnek ide. {fileOwner} felhasználón kívül senki nem jut be, bármit is engedjenek a bennük lévő fájlok, és minden letöltés ilyen mappába érkezik.`,"settings.owner.v.notWritable":`Ez a példány ide egyáltalán nem tud írni: {detail}`,"settings.owner.v.missing":`A mappa nincs meg. Akkor jön létre, amikor először írnak bele valamit.`,"settings.owner.v.unknown":`Ezen a rendszeren a fájloknak nincs tulajdonosuk, itt tehát nincs mit összehasonlítani. Ez nem hiba.`,"settings.owner.fix.user":`Indítsd a konténert az alatt a fiók alatt, amelyé a mappa: --user {dirUid}:{dirGid} az indítóparancsban. Unraidon ez az Extra Parameters mezőbe kerül.`,"settings.owner.fix.chown":`Vagy add át inkább a mappát, a gazdagépen: chown -R {uid}:{gid} {dir}`,"settings.owner.fix.mask":`Ezen ez a példány nem tud változtatni. A maszk onnan jön, ami a konténert elindította, és egy becsatolt megosztás a saját umask, file_mode vagy dir_mode kapcsolójával kényszerítheti ki a magáét. Ott javítsd, ahol a mappa be van csatolva.`,"settings.owner.fix.recreate":`A megváltozott indítóparancshoz újra kell hozni a konténert. Az újraindítás nem elég: az identitás abban a pillanatban eldől, amikor elindul.`,"settings.owner.fix.past":`A már letöltött fájlok megtartják azt a tulajdonost, amellyel íródtak. Amit módosítasz, az arra vonatkozik, ami ezután jön, a többihez a fenti parancs kell.`,"settings.selftest.title":`Önteszt`,"settings.selftest.hint":`Minden, amit ez a példány ki tud deríteni magáról: a JDownloader háttér, a yt-dlp, a mappáid, a debrid bejelentkezéseid, a relé és az óra. Mindez ezen a gépen fut. Csak a debrid bejelentkezések hagyják el, és ezek a beállított szolgáltatóidhoz mennek.`,"settings.selftest.run":`Önteszt indítása`,"settings.selftest.running":`Ellenőrzés…`,"settings.selftest.pending":`Vár`,"settings.selftest.never":`Még nem futott.`,"settings.selftest.lastRun":`Legutóbb futott: {when}.`,"settings.selftest.startFailed":`Az öntesztet nem sikerült elindítani: {error}`,"settings.selftest.status.pass":`Rendben`,"settings.selftest.status.warn":`Érdemes megnézni`,"settings.selftest.status.fail":`Hibás`,"settings.selftest.status.skipped":`Nincs beállítva`,"settings.selftest.status.unknown":`Nem megállapítható`,"settings.selftest.jd":`JDownloader háttér`,"settings.selftest.jd.ok":`Elérhető, {version} revízió.`,"settings.selftest.jd.provisioningOff":`A saját JDownloader előkészítése ki van kapcsolva, és nincs cím beállítva, így nincs elérhető háttér.`,"settings.selftest.jd.missing":`A háttérnek nincs címe. A titkosított DLC- és konténerlinkeket elutasítjuk.`,"settings.selftest.jd.missingAdvice":`Ez a build induláskor rendszerint elindítja a saját felület nélküli JDownloaderét, és a KL_JD értékét maga tölti ki. Hogy üres, azt jelenti: ez az indítás meghiúsult. Keresd a naplóban lejjebb a "JD provisioning failed" sort, vagy állítsd a KL_JD értékét egy saját JDownloaderre.`,"settings.selftest.jd.unreachable":`A(z) {address} nem válaszolt.`,"settings.selftest.jd.unreachableAdvice":`A cím el van mentve, de semmi nem figyel rajta. Ellenőrizd, hogy fut-e a JDownloader háttér, és hogy a 3128-as portja elérhető-e ebből a konténerből, nem csak a gazdagépről.`,"settings.selftest.jd.noVersion":`Válaszol, de nem árulja el, melyik revízió.`,"settings.selftest.ytdlp":`yt-dlp`,"settings.selftest.ytdlp.ok":`{version}, {days} napos.`,"settings.selftest.ytdlp.aging":`A(z) {version} {days} napos.`,"settings.selftest.ytdlp.old":`A(z) {version} {days} napos. A nagy videóoldalak általában heteken belül elrontják.`,"settings.selftest.ytdlp.oldAdvice":`A konténerben a yt-dlp abból az Alpine-csomagból jön, amelyik a konténerkép építésekor aktuális volt, és soha nem frissíti magát. Húzz le újabb konténerképet, vagy csatolj be a konténerbe egy saját yt-dlp példányt, és mutass rá a KL_YTDLP változóval.`,"settings.selftest.ytdlp.missing":`Nincs meg, ezért a médiaoldalak helyette a tárhely saját hibájával hiúsulnak meg.`,"settings.selftest.ytdlp.missingAdvice":`Mutass a KL_YTDLP változóval a futtatható fájlra, vagy tedd a yt-dlp-t a PATH-ra. Csak egyszer, induláskor keressük, a most telepített tehát csak újraindítás után kerül használatba.`,"settings.selftest.ytdlp.undated":`A(z) {version} nem néz ki dátumnak, a korát tehát nem lehet megítélni.`,"settings.selftest.folders":`Letöltési mappa és munkamappa`,"settings.selftest.folders.allOk":`Minden ellenőrzött mappa megvan, és írható.`,"settings.selftest.folders.someBad":`Legalább egy mappánál van néznivaló.`,"settings.selftest.folders.none":`Egyetlen mappát sem sikerült megmérni.`,"settings.selftest.folders.ok":`A(z) {dir} írható, {free} szabad.`,"settings.selftest.folders.notWritable":`A(z) {dir} nem írható.`,"settings.selftest.folders.notWritableAdvice":`Ez a folyamat {uid} uid alatt fut. Nézd meg, kié az a mappa a gazdagépen, és hogy ez az uid írhat-e bele.`,"settings.selftest.folders.missing":`A(z) {dir} még nincs meg, a számok ezért a(z) {measured} mappát írják le.`,"settings.selftest.folders.missingAdvice":`Ez normális annál a mappánál, amelybe még semmi nem írt, és az első letöltés létrehozza. Ha viszont a(z) {measured} a kötet gyökere, akkor hiányzik a várt csatolás, és a letöltés a konténerbe kerül, nem a lemezedre.`,"settings.selftest.folders.low":`Már csak {free} szabad a(z) {dir} mappán, kevesebb, mint a(z) {mark} határ, amelynél a sor megáll.`,"settings.selftest.folders.noMark":`A(z) {dir} mappán {free} szabad. Nem állítottál be fix küszöböt, a sor tehát csak azt a letöltést tartja vissza, amelyik már így sem férne el.`,"settings.selftest.folders.unknown":`Ezen a platformon nem lehet lekérdezni, mennyi hely van a(z) {dir} mappán.`,"settings.selftest.accounts":`Debrid bejelentkezések`,"settings.selftest.accounts.none":`Nincs debrid fiók beállítva, nem volt tehát mit ellenőrizni.`,"settings.selftest.accounts.allOk":`Mind a(z) {n} bejelentkezést elfogadták.`,"settings.selftest.accounts.someFailed":`{n} bejelentkezésből {bad} elutasítva.`,"settings.selftest.accounts.rowOk":`{label}: elfogadva, {hosts} tárhely.`,"settings.selftest.accounts.rowFailed":`{label}: elutasítva.`,"settings.selftest.accounts.rowGone":`{label}: a kulcsot eltávolították, miközben az ellenőrzés futott.`,"settings.selftest.accounts.rowUnknownService":`{label}: ez a build nem ismeri ezt a szolgáltatást.`,"settings.selftest.accounts.advice.invalid":`A szolgáltató szerint ez a kulcs rossz, vagy visszavonták. Csak új kulcs segít.`,"settings.selftest.accounts.advice.expired":`A kulcs rendben van, az előfizetés nem. Újítsd meg a szolgáltatónál.`,"settings.selftest.accounts.advice.temp":`Lehet sebességkorlát, a szolgáltató kiesése vagy a saját vonalad. Magától megpróbáljuk még egyszer.`,"settings.selftest.accounts.advice.error":`A szolgáltató olyat nevez meg, amelyet sem új kulcs, sem várakozás nem old meg, például a címedre kimondott tiltást.`,"settings.selftest.accounts.readOnlyHint":`Ez az ellenőrzés az irányításon semmit nem változtat. Az itt megbukó bejelentkezést jelentjük, nem tesszük félre: a kiesett vonal mellett futó önteszt nem béníthat meg minden fiókot a következő negyedórára.`,"settings.selftest.relay":`Relé`,"settings.selftest.relay.off":`Kikapcsoltad a relét, nem tárcsáztunk tehát semmit.`,"settings.selftest.relay.notSetUp":`A távoli hozzáférést itt soha nem állítottad be, nem tárcsázunk tehát relét.`,"settings.selftest.relay.ownNoAddress":`A saját relé van kiválasztva, és nincs cím beállítva, nem tárcsázunk tehát semmit.`,"settings.selftest.relay.badSecret":`A tárolt kapcsolódási titkot nem lehet elolvasni. Add meg újra a kapcsolódási kifejezést.`,"settings.selftest.relay.connected":`Csatlakozva ide: {address}.`,"settings.selftest.relay.notConnected":`A(z) {address} el van mentve, és a kapcsolat nem áll.`,"settings.selftest.relay.notConnectedAdvice":`Vagy nem érhető el éppen a relé, vagy elutasította a kulcsot. Magától tovább próbálkozik. Ha egyáltalán nem jön fel, ellenőrizd a címet, és add meg újra a kapcsolódási kifejezést.`,"settings.selftest.clock":`Óra és időzóna`,"settings.selftest.clock.ok":`Ez a gép {time} időt mond, a zóna {zone}.`,"settings.selftest.clock.skew":`Ez a gép és a böngésződ {skew} eltéréssel jár.`,"settings.selftest.clock.skewAdvice":`A kettő közül az egyik rosszul jár, és ez az alkalmazás nem tudja megmondani, melyik. Az ennyire eltérő óra érvénytelennek mutatja a TLS-tanúsítványokat, és ahhoz vezet, hogy a debrid tokeneket elutasítják. Előbb a gazdagép óráját nézd meg, a konténer onnan veszi az idejét.`,"settings.selftest.clock.utc":`Az időzóna UTC, és be van állítva egy ütemezés.`,"settings.selftest.clock.utcAdvice":`Az ütemezés ennek a gépnek a helyi ideje szerint fut, és beállított TZ nélkül ez az UTC. A 22:00-ra tett ablak így 22:00 UTC-kor indul, ami Berlinben télen 23:00, nyáron éjfél. Indítsd a konténert TZ változóval, például TZ=Europe/Berlin, és indítsd újra.`,"settings.selftest.clock.noZoneDB":`A TZ a(z) {zone} zónát nevezi meg, és a zónaadatbázist nem sikerült elolvasni, ezért ebben a folyamatban minden idő UTC-re esik vissza.`,"settings.selftest.torrentPort":`Torrent-port`,"settings.selftest.torrentPort.noPort":`The built-in torrent client picks its own port, and this build cannot read back which one it took.`,"settings.selftest.torrentPort.noPortAdvice":`Állíts be fix portot a Torrentek oldalon. Enélkül nincs mit továbbítani és nincs mit ellenőrizni, és a másik router mögötti partnerek csak akkor érnek el, ha ők csatlakoznak először.`,"settings.selftest.torrentPort.notChecked":`A(z) {port} port be van állítva. Ezen a hálózaton kívül semmit nem kérdeztünk meg, ezért nem tudni, kívülről nyitva van-e.`,"settings.selftest.torrentPort.notCheckedAdvice":`Erre csak egy a saját hálózatodon kívüli gép tud válaszolni, és ez az alkalmazás egyetlen olyat sem keres meg, amelyet nem te választottál. A Torrentek oldal UPnP gombja megkéri a routeredet, hogy továbbítsa a portot, és megmondja, sikerült-e megerősítenie. Az a port, amelyet ennek a futásnak az első torrentje után mentesz el, csak újraindítás után lép életbe.`,"settings.selftest.proxy.title":`Fordított proxy`,"settings.selftest.proxy.hint":`Mit mond a böngésződ és mit ez a példány pontosan ugyanarról a kérésről. Ez a négy az, ami a Nginx Proxy Manager és a Traefik mögött félremegy, és a négyből három mindenféle hibaüzenet nélkül bukik meg.`,"settings.selftest.proxy.desktopSkip":`Az asztali kiadás a saját felületét maga szolgálja ki, és nincs előtte proxy, itt tehát nincs mit összehasonlítani.`,"settings.selftest.proxy.host":`Host fejléc`,"settings.selftest.proxy.host.ok":`A böngésződ és ez a példány egyetért abban, hogy a hoszt {host}.`,"settings.selftest.proxy.host.rewritten":`A böngésződ a(z) {browser} hosztot kérte, ennek a példánynak {server} lett mondva.`,"settings.selftest.proxy.host.rewrittenAdvice":`A proxyd lecseréli a Host fejlécet. Ez a példány a böngésződ Origin fejlécét hasonlítja a Host értékéhez, ezért minden írást 403-mal utasítunk el, és az élő nézet soha nem nyílik meg, miközben maga az oldal továbbra is betölt és jól néz ki. A Traefikben hagyd bekapcsolva a passHostHeader kapcsolót. Az nginxben vedd a proxy_set_header Host $host sort.`,"settings.selftest.proxy.proto":`Továbbadott protokoll`,"settings.selftest.proxy.proto.ok":`A proxy https-t mond, és a böngésződ pontosan ezen van.`,"settings.selftest.proxy.proto.direct":`Ezt a példányt közvetlenül érted el, nincs tehát proxy, amelynek bármit közölnie kellene.`,"settings.selftest.proxy.proto.missing":`A böngésződ https-en van, és a proxy ezt nem adta tovább.`,"settings.selftest.proxy.proto.missingAdvice":`X-Forwarded-Proto nélkül ez a példány azt hiszi, hogy sima http-n keresztül érték el. A QR-kód és a Távoli elérés oldal párosítási címei ekkor http:// linkeket kínálnak, és a JDownloadernek átadott konténer is http-n keresztül töltődik le. Az nginxben: proxy_set_header X-Forwarded-Proto $scheme; a Traefik és a Caddy magától beállítja.`,"settings.selftest.proxy.prefix":`Útvonalelőtag`,"settings.selftest.proxy.prefix.underPath":`Ezt a példányt a(z) {path} alatt szolgáljuk ki.`,"settings.selftest.proxy.ws":`WebSocket-upgrade`,"settings.selftest.proxy.ws.ok":`Az élő kapcsolat létrejött.`,"settings.selftest.proxy.ws.failed":`Az élő kapcsolat nem jött létre.`,"settings.selftest.proxy.ws.failedAdvice":`Ez a leggyakoribb hiba egy proxy mögött, és semmi más nem mutatja meg neked: az alkalmazás csendben újra meg újra csatlakozik, a lista egyszerűen nem mozdul többé, és csak az oldal újratöltése mutat valami újat. Az nginxben a location blokkhoz kell a proxy_http_version 1.1, a proxy_set_header Upgrade $http_upgrade és a proxy_set_header Connection "upgrade". A Nginx Proxy Managerben a hosztnál van egy Websockets Support kapcsoló. A Traefiknek és a Caddynek semmi nem kell.`,"settings.diagnostics.startupTitle":`Indítási jelentés`,"settings.diagnostics.startupHint":`Amit ez a példány induláskor egyszer ellenőrzött: a programokat, amelyeket meghív, minden mappát, amelybe letöltés kerülhet, és az órát, amely szerint az ütemezés működik. Ez csak leolvasás, így semmi itt nem tart vissza letöltést, és nem akadályozza meg a kiszolgáló indulását. Induláskor csak megnézzük; az írási próba akkor történik, amikor megnyomod az „Újraellenőrzés” gombot.`,"settings.diagnostics.startupTakenAt":`Ellenőrizve: {when}, nem sokkal ennek a példánynak az indulása után.`,"settings.diagnostics.startupJustChecked":`Épp az imént ellenőrizve. A letölthető csomag továbbra is az induláskor felvett mérést hordozza, mert egy hibajelentéshez az kell.`,"settings.diagnostics.startupRunning":`Még tart az ellenőrzés. Egy olyan megosztáson lévő mappa, amelyik már nem válaszol, annyi ideig tart, amennyi alatt az a megosztás feladja.`,"settings.diagnostics.startupOff":`Ennél a példánynál az ellenőrzés ki van kapcsolva (KL_STARTUP_CHECK=0). Semmit nem néztünk meg, és ez nem ugyanaz, mint hogy minden rendben van.`,"settings.diagnostics.startupNotRun":`Ez a build soha nem futtatta az ellenőrzést. A kiszolgálóban és az asztali alkalmazásban fut le.`,"settings.diagnostics.startupStatOnly":`Induláskor csak megnéztük: egyetlen mappába sem írtunk semmit. A „Rendben” jelzésű mappa tehát létezik, de nem írtunk bele.`,"settings.diagnostics.startupNothingWrong":`Itt nincs teendő.`,"settings.diagnostics.startupRecheck":`Újraellenőrzés`,"settings.diagnostics.startupRechecking":`Ellenőrzés…`,"settings.diagnostics.startupRecheckHint":`Most futtatja le ugyanazokat az ellenőrzéseket, és ezúttal egy kis tesztfájlt ír minden meglévő mappába, amelyet utána megint töröl. Induláskor ez nem történik meg, mert a tömbön lévő mappába írás felébreszti azt a lemezt, amelyiken fekszik, és ez minden újraindításnál megtörténne. A letölthető csomag megtartja az induláskor felvett mérést, mert egy hibajelentéshez az kell.`,"settings.diagnostics.startupRecheckFailed":`Az újraellenőrzés nem sikerült: {error}`,"settings.diagnostics.startupNearest":`a legközelebbi meglévő mappa: {measured}`,"settings.diagnostics.verdict.ok":`Rendben`,"settings.diagnostics.verdict.warn":`Érdemes megnézni`,"settings.diagnostics.verdict.fail":`Nem használható`,"settings.diagnostics.verdict.skipped":`Itt nem szükséges`,"settings.diagnostics.check.data":`Adatmappa`,"settings.diagnostics.check.java":`Java`,"settings.diagnostics.check.ytdlp":`yt-dlp`,"settings.diagnostics.check.ffmpeg":`ffmpeg`,"settings.diagnostics.check.ffprobe":`ffprobe`,"settings.diagnostics.check.clock":`Időzóna és helyi idő`,"settings.diagnostics.role.downloads":`Letöltési mappa`,"settings.diagnostics.role.work":`Munkamappa`,"settings.diagnostics.role.category":`Kategóriamappa`,"settings.diagnostics.role.extract":`Kibontási mappa`,"settings.diagnostics.role.extractMove":`A kibontás utáni célmappa`,"settings.diagnostics.role.watch":`Figyelt mappa`,"settings.diagnostics.fix.missing":`A mappa nem létezik. A fölötte lévő legközelebbi létező mappa: {measured}. Megosztást csatoló gépen ez általában azt jelenti, hogy a megosztás nincs csatolva, és ezért ez az ellenőrzés nem hozza létre a mappát: egy hiányzó csatolás alatt létrehozott mappa magába fogadná a letöltéseket, és azok a következő konténerfrissítéssel eltűnnének.`,"settings.diagnostics.fix.denied":`A mappa megvan, de ez a példány nem írhat bele. A konténerben a KnightLoader uid 1000 alatt fut, a mappának tehát ehhez a felhasználóhoz vagy egy olyan csoporthoz kell tartoznia, amelyben benne van.`,"settings.diagnostics.fix.readonly":`Az ehhez a mappához tartozó fájlrendszer csak olvasásra van becsatolva. Ezen ez a példány nem változtat, a csatolást kell megváltoztatni.`,"settings.diagnostics.fix.full":`Azon a köteten, amelyen ez a mappa fekszik, nincs több hely.`,"settings.diagnostics.fix.notRemoved":`A tesztfájlt ki lehetett írni, de újra törölni nem. A letöltés ideérkezne, és utána soha nem lehetne átnevezni vagy elrakni. A mappa törlési jogát nézd meg, ne az írási jogot.`,"settings.diagnostics.fix.notADir":`Ezen az útvonalon fájl áll, nem mappa.`,"settings.diagnostics.fix.timeout":`A mappa nem válaszolt időben, ezért békén hagytuk. Az a megosztás, amelynek a kiszolgálója ki van kapcsolva, pontosan így viselkedik, és az is, amelyik egy eltűnt hálózaton van.`,"settings.diagnostics.fix.dataDenied":`Ez az az egy mappa, amely nélkül a példány nem boldogul: az adatbázis, a beállítások és a titkosított fióktár mind itt fekszik. A letöltések egyelőre tovább futnak, a következő mentésed viszont elvész.`,"settings.diagnostics.fix.javaMissing":`Nem található Java. A konténerkép tartalmaz egyet, az asztali alkalmazás viszont nem, így asztali gépen a Javát telepíteni kell, a PATH-ba vagy a JAVA_HOME alá. Nélküle a saját JDownloader nem indul el, és egy titkosított konténerlink (.dlc, .ccf, .rsdf) egyáltalán nem nyitható meg. Telepítsd a Javát, vagy irányítsd a KL_JD-t egy máshol futó JDownloaderre.`,"settings.diagnostics.fix.javaNotNeeded":`Ez a példány nem indít saját Java-folyamatot: vagy a KL_JD mutat egy máshol futó JDownloaderre, vagy a saját példány ki van kapcsolva a KL_PROVISION_JD=0 beállítással.`,"settings.diagnostics.fix.ytdlpMissing":`A yt-dlp nem található (KL_YTDLP, vagy „yt-dlp” a PATH-on). A médiaoldalak ilyenkor az oldal saját hibájával hiúsulnak meg, ahelyett hogy letöltődnének.`,"settings.diagnostics.fix.ffmpegMissing":`Az ffmpeg nem található. A yt-dlp-nek szüksége van rá, hogy összefűzze a legtöbb oldal által külön kiadott kép- és hangsávot, ezért a letöltés vagy a kettő egyikénél megáll, vagy hang nélkül jön vissza.`,"settings.diagnostics.fix.ffprobeMissing":`Az ffprobe nem található. Csak a kész videó hosszellenőrzése használja, minden más működik nélküle.`,"settings.diagnostics.fix.notRunnable":`Megvan itt: {subject}, de nem futott le: {error}`,"settings.diagnostics.fix.appearedLate":`Most fut, és ennek a példánynak az indulásakor nem volt meg, ezért még semmit nem irányítunk hozzá. Az átvételéhez indítsd újra.`,"settings.diagnostics.fix.utcFallback":`A TZ értéke {subject}, ez a példány viszont nem tudta betölteni ezt a zónát, és szó nélkül visszaesett UTC-re. Amíg ez nincs orvosolva, minden ütemezési ablak UTC szerint fut. Ellenőrizd a helyesírást a zónalista alapján („Europe/Berlin”), és azt is, hogy a konténerképben van-e egyáltalán zónaadatbázis.`,"settings.diagnostics.fix.noZoneDatabase":`Ezen a rendszeren nincs zónaadatbázis, az időket tehát mindenféle nyáriidőszámítás-váltás nélkül olvassuk. Az éjszakai ablak az egész nyáron megtartja a téli óráját, és senki nem szól, amikor ez bekövetkezik.`,"settings.diagnostics.fix.tzUnset":`A TZ nincs beállítva, és helyi időt sem találtunk, így ez a példány UTC szerint fut. Ez működik, de akkor egy 23:00-ra írt ütemezési idősáv 23:00 UTC-t jelent, nem a nálad érvényes 23:00-t.`,"settings.resolvers.toolsTitle":`Eszközök`,"settings.resolvers.toolsHint":`A yt-dlp olvassa ki a médiaoldalt, az ffmpeg fűzi össze a sávokat, amelyeket visszaad. Mindkettő külön program, amelyet a KnightLoader indít el, és egyik sem része ennek a buildnek, ezért érdemes tudni a verziójukat: az elavult yt-dlp a leggyakoribb oka annak, hogy egy múlt hónapban még működő médialink egyszer csak nem megy.`,"settings.resolvers.toolsInUse":`Használatban`,"settings.resolvers.toolsNotFound":`Nem található`,"settings.resolvers.toolsFrom.managed":`A KnightLoader saját másolata`,"settings.resolvers.toolsFrom.env":`KL_YTDLP`,"settings.resolvers.toolsFrom.path":`A PATH-on megtalálva`,"settings.resolvers.toolsFrom.none":`Sehol`,"settings.resolvers.toolsYtdlpMissingHint":`yt-dlp nélkül egyáltalán nincs médiabackend: egy videóoldalra mutató linket az oldal saját hibájával utasítunk el, ahelyett hogy letöltenénk. A konténerben a konténerkép yt-dlp csomagjából jön, az asztalon magad telepíted, és vagy a PATH-ra teszed, vagy a KL_YTDLP változóval mutatsz rá. A lenti gomb magától lehoz egy másolatot, ha egyik út sem járható.`,"settings.resolvers.toolsFfmpegMissingHint":`Az ffmpeg hiányában a yt-dlp nem tudja összefűzni a külön kép- és hangsávokat, amelyeket a legtöbb oldal kiad, a letöltés tehát vagy néma videósávként landol, vagy egyenesen megbukik. Az ffprobe hiányában a fentebb ezen az oldalon álló „A kész fájl megmérése” semmit nem mér, és nem is mond róla semmit. A konténerben mindkettő abból az ffmpeg csomagból jön, amelyet a konténerkép telepít, az asztalon magad telepíted őket, és a PATH-ra teszed.`,"settings.resolvers.toolsShadowed":`A KnightLoader saját másolata fut. Amíg megvan, a KL_YTDLP és a PATH nem indul: helyettük a(z) {path} kerülne sorra, és az {version} verziót jelenti.`,"settings.resolvers.toolsShadowedOlder":`Vigyázz: az a másolat, amelyet a KnightLoader lehozott ({current}), régebbi, mint az, amelyik ezen a gépen amúgy is ott van ({system}, itt: {path}). Egy konténerfrissítés újabb yt-dlp-t hoz magával, a saját másolatod viszont nem mozdul vele. Hozz le egy újat, vagy térj vissza a rendszer másolatához.`,"settings.resolvers.toolsManagedBroken":`A(z) {path} helyen egy lehozott másolat van bejegyezve, és az nem indul el. Helyette a fent mutatott tartalék fut. Hozd le újra, vagy térj vissza a rendszer másolatához.`,"settings.resolvers.toolsActions":`A yt-dlp naprakészen tartása`,"settings.resolvers.toolsActionsHint":`A lehozás letölti a yt-dlp-t a github.com oldalról, összeveti az ugyanabban a kiadásban közzétett SHA2-256SUMS fájllal, egyszer elindítja, hogy lássa, egyáltalán fut-e ezen a gépen, és csak azután teszi az adataid mellé, ahonnan a KnightLoader indítja. Az utolsó lépésig az a másolat működik tovább, amelyik eddig is megvolt, a rendszered saját yt-dlp példányához pedig soha nem nyúlunk.`,"settings.resolvers.toolsCheck":`GitHub megkérdezése`,"settings.resolvers.toolsChecking":`Kérdezzük a GitHubot…`,"settings.resolvers.toolsFetch":`Ennek a kiadásnak a lehozása`,"settings.resolvers.toolsFetching":`Lehozás és ellenőrzés…`,"settings.resolvers.toolsRevert":`Vissza a rendszer másolatához`,"settings.resolvers.toolsReverting":`Eltávolítás…`,"settings.resolvers.toolsSame":`A(z) {version} van telepítve, és ez a legújabb közzétett kiadás.`,"settings.resolvers.toolsNewer":`Közzétéve: {latest}, telepítve: {current}.`,"settings.resolvers.toolsOlder":`Telepítve: {current}, és ez újabb, mint a legújabb közzétett kiadás ({latest}). Nincs teendő.`,"settings.resolvers.toolsUnknown":`Közzétéve: {latest}, telepítve: {current}. Hogy a kettő közül melyik az újabb, a két verziószámból nem olvasható ki, ezért itt nem állítunk semmit.`,"settings.resolvers.toolsCheckFailed":`A GitHubot nem sikerült megkérdezni: {error}`,"settings.resolvers.toolsFetched":`A(z) {version} a helyén van és fut.`,"settings.resolvers.toolsFetchFailed":`Semmit nem cseréltünk le. {error}`,"settings.resolvers.toolsReverted":`A lehozott másolat eltűnt. Megint a(z) {path} fut.`,"settings.resolvers.toolsAutoCheck":`Az oldal megnyitásakor kérdezzük meg a GitHubtól a yt-dlp verzióját`,"settings.resolvers.toolsAutoCheckHint":`Egy kérés az api.github.com címre az oldal minden betöltésekor, és semmi több: semmit nem töltünk le és semmit nem cserélünk le anélkül, hogy megnyomnád a gombot. Alapból ki van kapcsolva, mert a magad üzemeltette gépnek nem kell magától kifelé telefonálnia, amíg nem engedted meg.`,"settings.diagnostics.toolsMissing":`nem található`,"settings.eventTargets.problem.redirect":`A cím átirányítással válaszol, és ez a példány nem követi. Ebben a sorban minden fejlécérték titoknak számít, és egy másik hosztra mutató átirányítás annak a hosztnak az üzemeltetője kezébe adná. Nyisd meg a címet a böngészőben, nézd meg, hova jut, és azt a címet írd be ide.`,"auth.twoFactor.title":`Kétlépcsős azonosítás`,"auth.twoFactor.hint":`Hatjegyű kód egy hitelesítő alkalmazásból, a jelszó mellé. A jelszó mellett áll, és soha nem lép a helyébe. Ennek a példánynak nincsenek felhasználói fiókjai, tehát nincs más, aki feloldhatná neked: a helyreállítási kódokat máshol tartsd, mint azon a telefonon, amelyik a kódokat készíti. Ha mindkettő elveszett, futtasd a gépen a knightloader -reset-2fa parancsot, vagy állítsd le a KnightLoadert, és töröld a totp és recovery bejegyzéseket az adatmappa auth.json fájljából. A jelszó mindkét esetben tovább működik.`,"auth.twoFactor.on":`Be`,"auth.twoFactor.off":`Ki`,"auth.twoFactor.needsPassword":`Előbb állíts be jelszót. A második lépcső egy jelszót véd, tehát kell hogy legyen egy.`,"auth.twoFactor.beforeYouStart":`A beállítás végén nyolc helyreállítási kód jön, egyszer látható és soha többé. Készíts elő valamit, amire felírod őket, mielőtt belekezdesz.`,"auth.twoFactor.enable":`Beállítás`,"auth.twoFactor.scan":`Olvasd be ezt a hitelesítő alkalmazásoddal.`,"auth.twoFactor.qrLabel":`QR-kód, amely felveszi ezt a példányt egy hitelesítő alkalmazásba`,"auth.twoFactor.secretManual":`Vagy írd be kézzel`,"auth.twoFactor.confirmLabel":`Hatjegyű kód az alkalmazásból`,"auth.twoFactor.confirm":`Bekapcsolás`,"auth.twoFactor.codesTitle":`Írd fel őket most`,"auth.twoFactor.codesHint":`Ez az egyetlen alkalom, amikor látszanak. Mindegyik egyszer érvényes, az alkalmazás kódja helyett, és csak ezek juttatnak vissza, ha a telefon elvész.`,"auth.twoFactor.codesAck":`Felírtam őket`,"auth.twoFactor.recoveryLeft":`Még {n} helyreállítási kód maradt.`,"auth.twoFactor.disable":`Kikapcsolás`,"auth.twoFactor.disablePrompt":`A kikapcsoláshoz adj meg egy kódot`,"auth.twoFactor.signInHint":`Add meg a hitelesítő alkalmazásod kódját, vagy az egyik helyreállítási kódodat.`,"auth.twoFactor.verify":`Tovább`,"auth.twoFactor.codeWrong":`Ezt a kódot nem fogadta el.`,"auth.passkey.title":`Azonosítókulcsok`,"auth.passkey.hint":`Egy kulcs, amelyet a telefonod, a laptopod vagy a biztonsági kulcsod őriz, jelszó begépelése nélkül léptet be. Ez egy további út befelé: a jelszó tovább érvényes, és az összes azonosítókulcs eltávolítása senkit sem zár ki. Az azonosítókulcs ahhoz a webcímhez tartozik, amelyen létrejött, tehát a proxyn keresztül készített nem működik a helyi hálózati címen, és fordítva sem.`,"auth.passkey.registered":`{n} beállítva`,"auth.passkey.none":`Egy sincs beállítva`,"auth.passkey.needsPassword":`Előbb állíts be jelszót. Az azonosítókulcs egy második út a bejelentkezéshez, tehát kell hogy legyen egy.`,"auth.passkey.unavailableTitle":`Az azonosítókulcsokhoz gépnév kell, ez az oldal pedig IP-címen van megnyitva.`,"auth.passkey.unavailableReason":`Az azonosítókulcs egy tartományhoz kötődik, ezért a böngészők csupasz címen az egész cserét megtagadják, és megtagadják újra olyan tanúsítványnál, amelyben nem bíznak. Érd el a KnightLoadert fordított proxyn keresztül valódi néven, érvényes tanúsítvánnyal, nyisd meg ott, és ott vedd fel a kulcsot.`,"auth.passkey.noBrowserTitle":`Ez a böngésző nem kínál azonosítókulcsokat.`,"auth.passkey.noBrowserReason":`Ezzel a példánnyal semmi baj. Nyisd meg egy mai böngészőben, vagy olyan eszközön, amely azonosítókulcsot tud tárolni, és a gomb itt megjelenik.`,"auth.passkey.add":`Beállítás`,"auth.passkey.create":`Létrehozás`,"auth.passkey.nameLabel":`Név`,"auth.passkey.nameHint":`Te választod, hogy később meg tudd különböztetni a kulcsaidat. A böngészőnek semmit sem jelent.`,"auth.passkey.namePlaceholder":`pl. a telefonom`,"auth.passkey.defaultName":`Azonosítókulcs`,"auth.passkey.usableHere":`Működik ezen a címen`,"auth.passkey.otherAddress":`Ehhez felvéve: {host}`,"auth.passkey.notSynced":`nincs kulcstartóba szinkronizálva`,"auth.passkey.lastUsed":`utoljára használva {when}`,"auth.passkey.rename":`Átnevezés`,"auth.passkey.saveName":`Mentés`,"auth.passkey.remove":`Eltávolítás`,"auth.passkey.removeTitle":`Eltávolítod ezt az azonosítókulcsot?`,"auth.passkey.removeBody":`{name} többé nem léptet be. A jelszó továbbra is működik.`,"auth.passkey.added":`Azonosítókulcs hozzáadva.`,"auth.passkey.removed":`Azonosítókulcs eltávolítva.`,"auth.passkey.signIn":`Belépés azonosítókulccsal`,"auth.passkey.signInFailed":`Ez az azonosítókulcs nem léptetett be.`,"auth.passkey.error.expired":`A beállítás túl sokáig tartott. Kezdd újra.`,"auth.passkey.error.otherAddress":`Ezt a beállítást egy másik címen kezdted el. Nyisd meg a KnightLoadert azon a címen, amelyen a kulcsnak működnie kell, és ott kezdd újra.`,"settings.stall.reconnect":`Új kapcsolatok nyitása elakadt letöltéshez`,"settings.stall.reconnectHint":`Bezárja egy megjelölt letöltés kapcsolatait, és újakat nyit, amelyek a fájl hátralévő részét kérik. A letöltés megtartja, amit már megkapott, és a helyét is, ezért ez bekapcsolva marad, amíg ki nem kapcsolod. Az a szerver, amely a fájlt csak egyben tudja küldeni, újra az elejéről küldi. E nélkül az a letöltés, amelynek a szervere a fájl közepén abbahagyja a válaszolást, 0 B/s-on áll, amíg valaki szüneteltetni nem kezdi. Amíg a letöltés áll, ez minden alkalommal megismétlődik, amikor a fent beállított idő lejár. Ha „Az elakadt letöltés indítása elölről” is be van kapcsolva, az új kapcsolatok után is ennyi ideig álló letöltés elölről indul. Új kapcsolatot csak a beépített motor letöltései kapnak, a debrid és TorBox letöltéseket is beleértve. A JDownloader és a yt-dlp maguk gondoskodnak a kapcsolataikról, és a társak nélküli torrentnek az új kapcsolatok nem segítenek, ezért ezeket csak megjelöli.`,"props.backend":`Szolgáltatás`,"props.backendAuto":`Automatikus`,"props.backendHint":`Which backend fetches these links. Automatic takes the first one in the priority order on the Accounts page that can take the link right now. A pinned link goes only to that backend, and fails with the reason when the backend cannot take it. A running download keeps its backend. A paused one moves when you resume it, and starts from the beginning there.`,"settings.globalSpeedLimit":`Sebességkorlát (0 = ∞)`,"rename.menu":`Átnevezés…`,"rename.confirm":`Átnevezés`,"rename.linkTitle":`Link átnevezése`,"rename.packageTitle":`Csomag átnevezése`,"rename.whenDone":`Ez a letöltés még fut. A fájl az új nevet a befejezésekor kapja meg.`,"rename.unpacking":`Ez a fájl kibontás alatt áll. Átnevezni a kibontás befejezése után lehet.`,"rename.remote":`A JDownloader háttérrendszer a saját gépén tölti le ezt a fájlt, és maga nevezi el, ezért innen nem nevezhető át.`,"rename.torrent":`A torrent maga nevezi el a fájljait, ezért nem nevezhető át.`,"rename.volume":`Ez a fájl egy többkötetes archívum egyik része. A részek megtartják a nevüket, különben az archívumot nem lehetne kibontani.`,"rename.separator":`A név nem tartalmazhat / vagy \\ jelet.`,"rename.empty":`A név nem lehet üres.`,"rename.dots":`A névnek pontoknál többől kell állnia.`,"rename.exists":`Abban a mappában már van „{name}” nevű fájl. A KnightLoader nem írja felül.`,"archive.unpackingAt":`Kibontás {percent}`,"archive.unpacked":`Kibontva`,"archive.tally":`{total} archívumból {done} kibontva`,"columns.variant.convertTo":`Átalakítás erre`,"settings.browsertools.desktopArchHint":`A Windows és a Linux két változatban is elérhető: x64 a legtöbb PC-hez és ARM64 az ARM-processzoros gépekhez, például a Snapdragon lapkás laptopokhoz. Ha a böngésző megmondja, milyen processzor van ebben a gépben, a csempék a megfelelő változatot adják, különben az x64-et. A mellettük lévő gombok a másikat adják. A macOS-alkalmazás Intelen és Apple siliconon is fut.`,"settings.resolvers.presetFormatsUnknown":`A KnightLoader még nem tudja, milyen formátumokat kínál a(z) {host}, ezért a menük mindet felkínálják. Amint egy {host} link ellenőrzésre kerül, az eddig ellenőrzött linkekben talált formátumokat kínálják, és a hangmenü alattuk sorolja fel a többit, amelyekre át lehet alakítani.`,"settings.transfer.colArrives":`Így kerül át`,"settings.transfer.colArrivesHint":`A fájlt író verzió mást értett ezen az értéken. A KnightLoader úgy veszi át, ahogy egy frissítés olvasná.`,"rename.linkHint":`A név, amelyen a fájl mentésre kerül. A már befejezett letöltés a lemezen is átnevezésre kerül, hogy a lista és a mappa egyezzen. A név nem elérési út, ezért a / és a \\ nem megengedett.`,"rename.packageHint":`Ha a letöltési mappa a csomagról kapta a nevét, az is megkapja az új nevet, amíg a csomagból még semmi nem kezdett letöltődni. A név nem elérési út, ezért a / és a \\ nem megengedett.`,"rename.keepsFolder":`A csomag egy része már letöltődött vagy éppen letöltődik. Ha a mappája a csomagról kapta a nevét, a mappa megtartja a nevét, és csak a csomag kap új nevet.`,"quick.speedWindowHint":`Milyen messzire nyúlik vissza a sávban lévő sebességgörbe, 10 másodperctől egy óráig. Két percig másodpercenként egy mérést rajzol, azon túl tízmásodpercenként egyet.`,"settings.access.tokens.rights":`Jogok`,"settings.access.tokens.rightsHint":`Mit tehet egy alkalmazás ezzel a tokennel. A „Teljes hozzáférés” mindent megtehet, a beállításokat és a jelszót is beleértve. A Sonarrnak és a Radarrnak elég a „Hozzáadás és olvasás”. Ha ezek eltávolítanak egy kész letöltést, az a listádban marad, hacsak a tokennek nincs „Vezérlés” joga is. A „Csak olvasás” látja a letöltéseidet, és nem változtat semmin.`,"settings.access.tokens.preset.full":`Teljes hozzáférés`,"settings.access.tokens.preset.addRead":`Hozzáadás és olvasás`,"settings.access.tokens.preset.read":`Csak olvasás`,"settings.access.tokens.preset.custom":`Egyéni`,"settings.access.tokens.scope.read":`Olvasás`,"settings.access.tokens.scope.readHint":`A letöltések, a sor, az előzmények és a statisztika megtekintése.`,"settings.access.tokens.scope.add":`Hozzáadás`,"settings.access.tokens.scope.addHint":`Linkek, torrentek, NZB-fájlok és konténerek hozzáadása.`,"settings.access.tokens.scope.control":`Vezérlés`,"settings.access.tokens.scope.controlHint":`Letöltések szüneteltetése, folytatása, eltávolítása és átrendezése, valamint captchák megválaszolása.`,"settings.access.tokens.scope.admin":`Adminisztráció`,"settings.access.tokens.scope.adminHint":`Beállítások, fiókok, tokenek és példányok módosítása, valamint a naplók olvasása.`,"settings.modules.detail.downloadclientNoAddReadToken":`Egyetlen API-token sem tud hozzáadni és olvasni, ezért a Sonarrt és a Radarrt elutasítjuk. Hozz létre egyet a „Hozzáadás és olvasás” beállítással a Távoli elérés oldalon.`,"settings.modules.detail.metricsNoReadToken":`Ennek a példánynak van jelszava, de nincs olvasni tudó API-tokenje, ezért egy felügyeleti rendszert elutasítunk. Hozz létre egyet a „Csak olvasás” beállítással a Távoli elérés oldalon.`,"settings.selftest.proxy.prefix.root":`Ezt a példányt közvetlenül a(z) {host} gyökerén szolgáljuk ki.`,"settings.selftest.proxy.prefix.mismatch":`A proxyd ezt a példányt a(z) {path} alatt szolgálja ki, de a példány a(z) {base} útvonalra van beállítva.`,"settings.selftest.proxy.prefix.mismatchAdvice":`Ez a példány a saját útvonalát minden fájl és minden hívás elé odateszi, amelyet az oldal kér, ezért ennek annak az útvonalnak kell lennie, amelyet a proxyd használ. Állítsd a KL_BASE_PATH értékét erre az útvonalra, vagy hagyd a KL_BASE_PATH-t beállítatlanul, és döntsön a proxyd X-Forwarded-Prefix fejléce. Csak egyszerű útvonal számít, például /kl, és nem kezdődhet /api vagy /relay részlettel.`,"settings.modules.detail.downloadclientReadyBoth":`SABnzbd-ként itt érhető el: {sabnzbd}, qBittorrentként itt: {qbittorrent}. A Sonarrban vagy a Radarrban állítsd a URL Base mezőt erre: „{sabnzbdBase}” vagy „{qbittorrentBase}”, és használd ennek a példánynak az egyik API-tokenjét API key-ként vagy qBittorrent-jelszóként.`,"captcha.unsolvableTurnstile":`A KnightLoader maga nem tud Cloudflare Turnstile feladványt megjeleníteni, ezért csak a Captcha beállításaiban megadott megfejtő tud rá válaszolni. A Mégse kihagyja ezt a captchát.`,"captcha.solverWaiting":`{time} múlva egy megfejtő átveszi.`,"captcha.solverWaitingHint":`You are watching, so the solvers wait for your answer first. Once this tab is in the background, this window is minimised or in the tray, or the time runs out, the first solver in your order takes over.`,"captcha.solverSolving":`{solver} éppen megoldja ezt a captchát.`,"captcha.solverSolvingHint":`Ettől még te magad is válaszolhatsz rá. Az a válasz számít, amelyik előbb érkezik.`,"captcha.solverStopped":`Egyik megfejtő sem tudta átvenni ezt a captchát.`,"captcha.solverUnsupported":`{solver} nem old meg ilyen fajta captchát.`,"captcha.solverRefused":`{solver} elutasította: {reason}`,"settings.captcha.whenTitle":`Mikor indulnak a megfejtők`,"settings.captcha.onlyUnwatched":`Csak ha senki sem nézi`,"settings.captcha.wait":`Várakozás válaszra (másodperc)`,"settings.captcha.waitHint":`Meddig várnak a megfejtők, amíg valaki nézi, mielőtt mégis átveszik. Soha nem várnak tovább, mint a captcha hátralévő idejének a fele, hogy egy megfejtőnek még legyen ideje megválaszolni. 10 és 600 másodperc között.`,"captcha.solverStoppedTaken":`{solver} átvette ezt a captchát, de nem küldött választ.`,"captcha.solverNotPassedOn":`{solver} így is felszámolhatja, ezért a KnightLoader nem küldi el egy másik megfejtőnek is. Te magad továbbra is válaszolhatsz rá.`,"captcha.solverNoAnswer":`{solver} átvette, de nem jött vissza válasz.`,"captcha.solverGaveUp":`{solver} átvette, aztán feladta: {reason}`,"captcha.solverFailed":`{solver} nem volt elérhető.`,"settings.captcha.onlyUnwatchedHint":`Off: the solvers start as soon as a captcha arrives, at the same time as the captcha window. On: while someone is watching, the captcha window comes first and the solvers wait. Someone is watching while a browser tab with KnightLoader is in the foreground or the desktop app's window is on screen, and while the phone app has this instance open in the foreground or another app keeps reading its captcha list. A tab in the background and a window that is minimised or in the tray do not count, and a closed page stops counting after a few seconds. The phone app counts only for the captchas it can answer, which on a connection made with the phrase are pictures and clicks. A Cloudflare Turnstile goes to the solvers at once, since nobody can answer it in KnightLoader. Once nobody is watching, or the time below runs out without an answer, the first solver in the order takes over.`,"settings.accounts.freeTitle":`Ingyenes letöltések`,"settings.accounts.premiumOnly":`Csak prémium`,"settings.accounts.premiumOnlyHint":`Azt a tárhelylinket, amelyet egyik fiókod sem tud letölteni, a JDownloader kapja meg, és ingyen tölti le: lassan, várakozásokkal és captchákkal. Ha a „Csak prémium” be van kapcsolva, a link ehelyett a sorban vár, és megmondja, miért; ugyanígy a szüneteltetett ingyenes letöltés is. Magától indul, amint hozzáadsz egy belépést ehhez a tárhelyhez, vagy egy debrid szolgáltatást, amely támogatja. Egy kategória a saját linkjeire ezt másképp is eldöntheti.`,"settings.categories.premiumOnly":`Csak prémium`,"settings.categories.premiumOnlyHint":`Hogy egy ide sorolt link, amely csak ingyen tölthető le, inkább fiókra várjon-e. Az „Öröklés” a Fiókok beállítási oldal „Csak prémium” kapcsolóját követi. A „Be” akkor is visszatartja az ilyen linkeket, ha az a kapcsoló ki van kapcsolva. A „Ki” akkor is engedi ebben a kategóriában az ingyenes letöltést, ha az be van kapcsolva.`,"settings.hostRules.preferHint":`Melyik backend kapja először az erről a tárhelyről érkező linkeket. Az „Automatikus” a Fiókok oldal prioritási sorrendjét követi. Ha a választott backend nem tud átvenni egy linket, mert nem támogatja ezt a tárhelyet, vagy a fiókja épp nem érhető el, a link a szokásos módon halad tovább lefelé a prioritási sorrendben. Olyan backendhez, amelyet lent kikapcsoltál, soha nem kerül. Az a letöltés, amelyet a tulajdonságaiban egy backendhez rögzítettél, annál a backendnél marad.`,"settings.hostRules.backends":`Backendek ehhez a tárhelyhez`,"settings.hostRules.backendsHint":`Az erről a tárhelyről érkező linkek soha nem kerülnek olyan backendhez, amelyet itt kikapcsolsz, akárhol áll is a prioritási sorrendben. Az ott elkezdett, szüneteltetett letöltés folytatáskor a következő backendhez kerül, és elölről kezdődik. Ha nem marad olyan backend, amely át tudja venni a linket, a link meghiúsul, és jelzi, hogy itt zártad ki. Az a letöltés, amelyet a tulajdonságaiban egy backendhez rögzítettél, továbbra is oda megy. A fent kiválasztott backend nem szerepel a listában: azt kérdezzük meg először.`,"task.waiting.premium":`Prémiumfiókra vár`,"settings.downloads.keepAwake":`A számítógép ébren tartása letöltés közben`,"settings.downloads.keepAwakeContainerHint":`Nincs ebben a buildben. Csak az asztali alkalmazás tudja ébren tartani a számítógépet; az a gép, amelyen a konténer fut, maga dönti el, mikor alszik el.`,"settings.modules.detail.eventprogramsOff":`Ki. Egyetlen esemény sem indít programot, a már futó program pedig befejeződik.`,"settings.modules.detail.programsEnabled":`{n} program bekapcsolva`,"settings.modules.detail.programsEnabledOne":`1 program bekapcsolva`,"settings.module.eventprograms":`Eseményprogramok`,"settings.eventPrograms.titleHint":`Saját programjaid, amelyeket ez a példány elindít, ha történik valami, például egy szkript, amely a helyére teszi a kész letöltést. Mindegyik közvetlenül indul, parancsértelmező nélkül, és az eseményt az argumentumaiban és környezeti változókban kapja meg. Semmi nem fut, amíg be nem kapcsolsz egy programot.`,"settings.eventPrograms.add":`Program hozzáadása`,"settings.eventPrograms.newName":`{n}. program`,"settings.eventPrograms.empty":`Még nincs program.`,"settings.eventPrograms.emptyHint":`Vegyél fel egyet, hogy egy saját szkripted fusson, amikor egy letöltés befejeződik, egy csomag elkészül, vagy egy archívumot kibontottak.`,"settings.eventPrograms.remove":`Eltávolítás`,"settings.eventPrograms.name":`Név`,"settings.eventPrograms.nameHint":`Így hívják a programot ebben a listában és a naplóban. A napló soha nem mutatja a program útvonalát és az argumentumait.`,"settings.eventPrograms.enabled":`A program futtatása`,"settings.eventPrograms.enabledHint":`Minden felvett programnál ki van kapcsolva. Amíg ki van kapcsolva, a sor megtart mindent, amit beírtál, és semmi nem fut.`,"settings.eventPrograms.program":`Program`,"settings.eventPrograms.programHint":`A program vagy szkript teljes útvonala. Közvetlenül indul, nem parancsértelmezőn keresztül. Ha parancsértelmezőt szeretnél, ide magát a parancsértelmezőt írd, például /bin/sh, a parancssorodat pedig az argumentumokba. Mentés után a programot és az argumentumait itt nem mutatjuk többé, ugyanúgy, mint a sor végi parancsot, mert egy argumentumban token is lehet.`,"settings.eventPrograms.args":`Argumentumok`,"settings.eventPrograms.placeholdersHint":`Nevek, amelyeket az argumentumokba írhatsz, mindkét oldalukon két százalékjellel. Az első öt ugyanazt az értéket tartalmazza, mint a lenti környezeti változók. A többi ugyanaz, amit az eseménycélok használnak.`,"settings.eventPrograms.env":`Környezeti változók`,"settings.eventPrograms.eventsHint":`Mely események indítják ezt a programot. Kezdetben semmi sincs bepipálva.`,"settings.eventPrograms.eventsBurst":`Egy link hozzáadása linkenként egyszer indítja el ezt a programot, kétszáz beillesztett link tehát kétszázszor futtatja. Ami nem fér be a sorba, azt eldobjuk, és lent megszámoljuk.`,"settings.eventPrograms.eventsNone":`Nincs bepipálva semmi, ez a program tehát soha nem fut.`,"settings.eventPrograms.timeout":`Leállítás ennyi után (másodperc)`,"settings.eventPrograms.parallel":`Egyszerre`,"settings.eventPrograms.parallelHint":`Ennek a programnak hány futása mehet egyszerre, 1 és 4 között. 1 esetén minden esemény megvárja az előtte lévő futást, így a program abban a sorrendben látja az eseményeket, ahogy történtek.`,"settings.eventPrograms.status":`Állapot`,"settings.eventPrograms.statusHint":`Amit a kiszolgáló az indulása óta látott. Ebből semmit nem tárolunk a lemezen. Ha az események gyorsabban érkeznek, mint ahogy a program feldolgozza őket, a 256 várakozón felül mindent eldobunk, és itt megszámolunk.`,"settings.eventPrograms.statusUnknown":`A kiszolgáló indulása óta semmi nem futott. Ez nem azt jelenti, hogy még soha nem futott.`,"settings.eventPrograms.checkOk":`A program megtalálható.`,"settings.eventPrograms.lastRun":`Utolsó futás: {when}, a(z) „{event}” eseményre.`,"settings.eventPrograms.lastRunOk":`{duration} után rendben befejeződött.`,"settings.eventPrograms.output":`Kimenet: {output}`,"settings.eventPrograms.runCount":`{n} futás a kiszolgáló indulása óta, ebből {failed} sikertelen.`,"settings.eventPrograms.dropped":`{n} esemény eldobva, mert túl sok várakozott.`,"settings.downloads.keepAwakeHint":`Amíg egy letöltés fut, és amíg utána ellenőrzik, kibontják, áthelyezik vagy átadják egy eseményprogramnak, a számítógép nem alszik el. A következő próbálkozására váró letöltés is számít. A képernyő ettől még kikapcsolhat. Ha mindez véget ért, a gép a szokásos módon újra elalszik.`,"settings.transfer.incompleteEventPrograms":`az eseményprogramok parancssorai`,"settings.eventPrograms.argsHint":`Soronként egy. Minden sor egyetlen argumentumként jut el a programhoz, kitöltött helyőrzőkkel, és semmilyen parancsértelmező nem olvassa: a $( ) vagy ; karaktereket tartalmazó fájlnév pontosan ezekkel a karakterekkel érkezik. Egy .bat vagy .cmd fájl minden argumentumot idézőjelben kap, ott tehát "%~1" formában olvasd. Ha a program egy parancsértelmező, helyőrzők helyett a környezeti változókat használd, dupla idézőjelek között, például "$KL_FILE", hogy a parancsértelmező ne olvashasson parancsként egy fájlnevet.`,"settings.eventPrograms.envHint":`Minden futás megkapja ezeket, üresen ott, ahol az eseménynek nincs hozzájuk semmije. A KL_FILE a letöltés fájlja, a KL_FOLDER pedig a mappa, amelyben van. Kész csomagnál a KL_FOLDER az a mappa, amelybe a legtöbb fájlja került; kibontott archívumnál az a mappa, amelybe kibontották. A sikertelen kibontás is elindítja a programot, ilyenkor a KL_EXTRACT_OK értéke false. Ha munkamappát használsz, a kész letöltés vagy csomag megvárja, amíg a fájljait kiviszik belőle, legfeljebb 15 percig. Ennek a példánynak a saját KL_ beállításait, a szolgáltatáskulcsokat is beleértve, soha nem adjuk tovább.`,"settings.eventPrograms.timeoutHint":`Meddig tarthat egy futás, mielőtt leállítjuk, 5 és 3600 másodperc között. Minden, amit a program elindított, vele együtt leáll.`,"settings.eventPrograms.runCountOne":`1 futás a kiszolgáló indulása óta.`,"settings.eventPrograms.droppedOne":`1 esemény eldobva, mert túl sok várakozott.`,"settings.torrents.filesTitle":`Fájlkiválasztás`,"settings.torrents.minFileSize":`Minimális fájlméret`,"settings.torrents.minFileSizeHint":`A kisebb fájlokat kihagyjuk, például a .nfo fájlokat és a rövid mintákat. 0 = nincs minimum.`,"settings.torrents.includeFiles":`Csak ezek a fájlok`,"settings.torrents.includeFilesHint":`Soronként egy reguláris kifejezés, a fájl torrenten belüli útvonalához hasonlítva, ahogy az „illeszkedik a mintára” egy Packagizer-szabályban. Egy fájlnak valamelyikre illeszkednie kell, hogy letöltődjön. A kis- és nagybetű számít; írj (?i)-t a minta elejére, ha azt akarod, hogy ne számítson.`,"settings.torrents.excludeFiles":`Kihagyandó fájlok`,"settings.torrents.excludeFilesHint":`Soronként egy reguláris kifejezés, ugyanúgy hasonlítva, mint a mellette lévő mezőben. Az illeszkedő fájlt kihagyjuk, például (?i)sample vagy \\.(nfo|exe)$.`,"settings.torrents.trackersTitle":`Trackerek`,"settings.torrents.extraTrackers":`További trackerek`,"settings.torrents.trackerList":`Trackerlista`,"settings.torrents.trackerListHint":`Egy nyilvános lista címe, soronként egy trackerrel, például ngosang trackers_best.txt fájlja. Legfeljebb naponta egyszer kérjük le, és a trackereit ugyanúgy adjuk hozzá, mint a fentieket. Ha egy lekérés meghiúsul, a legutóbbi sikeres lekérés listája marad használatban.`,"settings.torrents.trackerListFetched":`{n} tracker, lekérve: {when}`,"settings.torrents.trackerListFetching":`A lista lekérése…`,"settings.torrents.trackerListPending":`Még nincs lekérve.`,"settings.torrents.trackerListFailed":`A legutóbbi lekérés sikertelen: {error}`,"settings.torrents.bannedTrackers":`Tiltott trackerek`,"collector.toastStartHeld":`{n} link(s) were rejected and not started.`,"torrent.held":`{file} was rejected: {reason}`,"collector.filtered.heldSummary":`{n} link(s) rejected`,"collector.filtered.heldInfo":`Links a link filter rule rejected, and torrents that announce a banned tracker. They are kept here instead of in the list above, so a working filter does not leave the collector looking full of junk. Nothing was lost. Restore puts a link back and lets it past the rule or ban that caught it, for when that turned out to be too broad. Clear deletes it. Either way, no file has been downloaded.`,"collector.filtered.toastHeldBack":`Staged {n} link(s); {held} rejected`,"collector.filtered.toastAllHeldBack":`Nothing was staged: {held} link(s) rejected`,"settings.torrents.filesHint":`Kiválasztja, hogy egy torrent mely fájljai töltődjenek le, ha senki nem választotta ki őket kézzel. Magnet linknél ez akkor történik meg, amikor megérkezik a fájllistája. Egy .torrent fájl már ezzel a kiválasztással bejelölve nyitja meg a fájllistáját, és ez érvényes, ha változtatás nélkül adod hozzá a torrentet. Amit te magad jelölsz be vagy veszel ki, az mindig nyer. Ha semmi sem maradna, minden fájl letöltődik. Egy kategóriának ehelyett saját fájlkiválasztása is lehet.`,"settings.torrents.extraTrackersHint":`Soronként egy tracker-cím; a torrentek megkapják ezeket, hogy több peert találjanak. A privátnak jelölt .torrent fájl soha nem kapja meg őket. A magnet link csak akkor árulja el, hogy privát-e, amikor megérkezik a fájllistája, és addigra a trackerek már hozzá vannak adva, ezért az a magnet sem kap egyet sem, amelynek a saját tracker-címe passkeyt tartalmaz. Azt a privát trackert, amely passkey helyett az IP-címed alapján ismer fel, így nem lehet kiszúrni: hagyd üresen ezt a mezőt, ha ilyenről kapsz magnet linkeket.`,"settings.torrents.bannedTrackersHint":`One host name or tracker address per line; its subdomains count too. A torrent that announces to one of them is not added: it is rejected with the reason and waits in the collector beside the links the link filter rejected. Restoring it there lets it past the line that caught it, not past one you add later. A banned tracker is never added as an extra tracker either.`,"detail.heldBecause":`Rejected because`,"settings.categories.torrentFiles":`Torrentek fájlkiválasztása`,"settings.categories.torrentFilesHint":`Egy ide sorolt torrent mely fájljai töltődjenek le, ha senki nem jelölte be őket kézzel. Az „Öröklés” a Torrentek oldal fájlkiválasztását használja. A „Saját” lecseréli ezt ennél a kategóriánál, például egy zenei kategóriában, ahol a kis fájlok maguk az album. A torrent indulásakor érvényesül, így arra a torrentre is vonatkozik, amelyet egy Packagizer-szabály sorolt ide. Az általad bejelölt fájlok mindig nyernek.`,"settings.categories.torrentFilesOwn":`Saját`,"settings.watchDirFilesHint":`Az ide tett fájlokat automatikusan felvesszük: linklisták (.txt, .crawljob, .magnet), .torrent fájlok, konténerek (.dlc, .ccf, .rsdf) és .nzb fájlok.`,"container.usenet":`A(z) {file} a(z) {service} szolgáltatáshoz került. A fájljai itt jelennek meg, amint a(z) {service} lehozta őket a Usenetről.`,"settings.help.intake.watchFiles":`A figyelt mappa felveszi, amit beletesznek: linklisták (.txt, .crawljob, .magnet), .torrent fájlok, konténerek (.dlc, .ccf, .rsdf) és .nzb fájlok.`,"container.nzbTooBig":`nagyobb, mint {max}, pedig egy .nzb legfeljebb ekkora lehet`,"container.noUsenet":`.nzb fájl, ezeket pedig egy TorBox- vagy Premiumize.me-fiók hozza le a Usenetről. Egyik fiókod sem tud ilyet: vegyél fel egyet a Fiókok alatt.`,"activity.usenet":`Usenet`,"settings.help.intake.nzb":`An .nzb, uploaded here or sent by Sonarr or Radarr, goes to your TorBox or Premiumize.me account, which fetches it from Usenet. Its files then download like any other link. TorBox takes .nzb files only on plans that include Usenet. KnightLoader finds out when TorBox turns down the first one, and that .nzb fails unless a Premiumize.me account takes it.`,"task.remote":`{service} tölti le`,"task.remoteSeeds":`Seedek: {n}`,"accounts.routing.orderHintTorrents":`Magnet links and .torrent files go either to the built-in torrent client or to a debrid service that takes torrents, whichever is higher in the list.`,"accounts.routing.tip.torrent":`A beépített torrentkliens. Ha egy torrenteket fogadó debrid szolgáltatás e sor fölött áll, a magnet linkeket és a .torrent fájlokat helyette az tölti le.`,"settings.torrents.debridTitle":`Debrid szolgáltatáson keresztül`,"settings.torrents.debridHint":`TorBox, Real-Debrid, AllDebrid, Premiumize.me and Debrid-Link can fetch magnet links and .torrent files instead of the built-in torrent client. The service downloads the torrent to its own servers, and KnightLoader then fetches the files from there like any other link. Nothing seeds from this machine and your address never appears in a swarm, so no port needs to be open. A torrent the service already has is ready at once. The priority order on the Accounts page decides whether a debrid service or the built-in torrent client goes first. A torrent from a private tracker always stays with the built-in torrent client. The file selection on this page chooses the files here too: Real-Debrid and Debrid-Link fetch only those, and from the other services only those come here.`,"accounts.col.import":`Importálás`,"task.remoteHint":`{service} a saját szervereire tölti le ezt, és eddig {percent} van meg. A fájlok akkor jönnek ide, amikor már mind megvan neki.`,"settings.modules.detail.torrentsOffDebrid":`Ki. A futó torrentek folytatódnak és tovább seedelnek. Az újak egy torrenteket fogadó debrid szolgáltatáshoz kerülnek.`,"collector.filtered.origin.account":`debrid-fiók`,"accounts.importAccount":`Importálás innen: {account}`,"accounts.importHint":`KnightLoader reads the service's list once a minute and brings in whatever was added there since you switched this on: torrents, and from TorBox and Premiumize.me also web and Usenet downloads. They land in the link collector like any other link and are fetched from this account. Nothing KnightLoader added itself comes in. The service does not say who added a download, so whatever another app adds with the same account comes in as well. Leave this off for an account that rdt-client or a second KnightLoader also uses. A download is deleted on the service once its files are here, or when you remove it here, unless "Keep downloads on the debrid service" is switched on under Settings, Torrents. A dash means the service has no list KnightLoader can read.`,"settings.torrents.keepOnService":`Letöltések megtartása a debrid szolgáltatásnál`,"settings.torrents.keepOnServiceHint":`Ha ez ki van kapcsolva, a KnightLoader törli a torrentet a debrid szolgáltatásról, amint minden fájlja itt van, és ugyanígy tesz a fiókból importált letöltéssel is, hogy egyik se gyűljön fel ott a fiók korlátait terhelve. Ha egy importált letöltést a befejezése előtt itt eltávolítasz, ott is törlődik. Ha be van kapcsolva, mindkettő a szolgáltatásnál marad, például hogy később onnan streamelhesd őket. A KnightLoader által hozzáadott torrent mindenképp törlődik, ha a befejezése előtt eltávolítod, a fiókban már korábban is meglévő torrent pedig soha nem törlődik.`,"settings.access.tokens.name":`Name`};export{e as hu};